#!/bin/bash

# ============================================================================
# Terminal Failure Handling
# ============================================================================
# Display fatal installation errors and keep an interactive terminal visible
# until Enter is pressed. A successful exit or user cancellation does not pause.
# Avoid waiting in noninteractive jobs without an attached terminal.
wrf_mosit_pause_on_failure() {
  local exit_status=$?

  # User interrupts and ordinary cancellations should close normally.
  if (( exit_status == 0 || exit_status == 130 || exit_status == 143 )); then
    return 0
  fi

  printf '\n============================================================\n' >&2
  printf 'WRF-MOSIT installation stopped with exit status %s\n' "$exit_status" >&2
  printf 'Review the error above and any configure.log or compile.log.\n' >&2
  printf '============================================================\n' >&2

  if [[ -t 0 ]]; then
    read -r -p 'Press Enter to close this terminal... ' _ || true
  elif [[ -r /dev/tty && -w /dev/tty ]]; then
    printf 'Press Enter to close this terminal... ' > /dev/tty
    IFS= read -r _ < /dev/tty || true
  fi
}
trap wrf_mosit_pause_on_failure EXIT

ulimit -s unlimited

################################################################################
# WRF-MOSIT v2.0.0 | Installer and Library Registry
# Guided, multi-model installer. Shared-library YAML reuse is restricted to
# compatible WRF-ARW, WRF-Chem, and WRF-Hydro installations.
# One YAML registry for reusable scientific libraries only.
# The original guided installer handles the supported model branches.
# Model-specific exports remain in their existing installation sections.
# Existing YAML profiles now bypass library builds in each model branch.
################################################################################

# ============================================================================
# HOW TO READ THIS INSTALLER
# 1. The YAML functions above the menus record, validate, and restore the
#    scientific-library environment. They do not compile WRF models.
# 2. The six startup stages select the host compiler, model, library source,
#    geographic data, optional utilities, and installation confirmation.
# 3. Each platform/model branch then runs the matching build procedure.
#    Most shared-model branches have a fresh-library path and a reuse path.
# 4. Fresh builds compile libraries in dependency order, then test them before
#    compiling the model. YAML reuse restores the existing library environment.
# 5. WRF-ARW, WRF-Chem, and WRF-Hydro can reuse compatible shared libraries.
#    WRF-SFIRE, WRF-CMAQ, and COAWST always build model-specific libraries.
# 6. Compiler family and CPU architecture must match the reusable YAML.
#    Matching metadata does not replace a full functional build test.
# 7. WPS_GEOG is separate from scientific libraries and can be linked from an
#    existing installation to avoid downloading large geographical datasets.
# 8. The final sections install selected optional tools, refresh allowed YAML
#    profiles, remove downloaded archives, and report the elapsed time.
#
# KEY VARIABLES
# WRF_FOLDER              Root directory for the currently selected model.
# DIR                     Scientific-library prefix for that installation.
# MOSIT_REUSE_LIBS        1 only after compatible YAML was loaded and checked.
# MOSIT_REUSE_GEOG        1 when an existing WPS_GEOG directory is selected.
# WRF_VERSION/WPS_VERSION Source versions used in model download commands.
# *_PICK                  Menu selection flags that activate one model branch.
# auto_config            1 sends predefined choices to configure; 0 prompts.
# ============================================================================

# ----------------------------------------------------------------------
# YAML Registry | Save Shared Scientific Libraries
# Record reusable scientific-library paths for WRF-ARW, WRF-Chem, and
# WRF-Hydro only.
# ----------------------------------------------------------------------
wrf_mosit_save_library_profile() {
  # CMAQ, SFIRE, and COAWST require fresh, model-specific library builds.
  if [ "${CMAQ_PICK:-0}" = 1 ] || [ "${SFIRE_PICK:-0}" = 1 ] || [ "${COAWST_PICK:-0}" = 1 ]; then
    echo "WRF-MOSIT: specialized model libraries are not registered for YAML reuse."
    return 0
  fi
  local profile_root_name
  # Inspect the installation root name as an additional guard against
  # registering specialized CMAQ, SFIRE, or COAWST libraries as shared.
  profile_root_name=$(printf "%s" "${WRF_FOLDER##*/}" | tr "[:lower:]" "[:upper:]")
  case "$profile_root_name" in
    *CMAQ* | *SFIRE* | *COAWST*)
      echo "ERROR: Specialized CMAQ, SFIRE, or COAWST libraries cannot be registered as reusable YAML."
      return 1
      ;;
  esac
  # Do not write a YAML file until essential NetCDF-Fortran and HDF5
  # headers and library files exist in the installation.
  if [ -z "${WRF_FOLDER:-}" ] || [ -z "${DIR:-}" ] || [ ! -f "${DIR}/NETCDF/include/netcdf.inc" ] \
    || ! compgen -G "${DIR}/NETCDF/lib/libnetcdff.*" > /dev/null \
    || ! compgen -G "${DIR}/grib2/lib/libhdf5.*" > /dev/null; then
    echo "WRF-MOSIT: library registry skipped (required installed libraries are missing)."
    return 1
  fi

  local compiler_family
  # The registry records the selected Fortran compiler family.
  # GNU and Intel oneAPI libraries must never be mixed.
  case "${FC##*/}" in
    ifx) compiler_family="intel" ;;
    gfortran) compiler_family="gnu" ;;
    *)
      echo "WRF-MOSIT: unsupported compiler in library registry: ${FC:-unset}"
      return 1
      ;;
  esac

  mkdir -p "${WRF_FOLDER}/Libs" || return 1
  MOSIT_PROFILE_FILE="${WRF_FOLDER}/Libs/wrf-libraries.yaml" \
    MOSIT_COMPILER_FAMILY="$compiler_family" \
    MOSIT_PROFILE_ORIGIN="${MOSIT_PROFILE_ORIGIN:-compatibility-tests-passed}" \
    python3 - << 'WRF_MOSIT_WRITE_YAML'
import json
import os
from pathlib import Path

e = os.environ
root = Path(e['DIR'])
compiler = e['MOSIT_COMPILER_FAMILY']
netcdf = root / 'NETCDF'
grib2 = root / 'grib2'
mpi = root / 'MPICH'
mct = root / 'MCT'

# Only library locations and installation metadata are retained.
out = {
    'schema_version': 1,
    'compiler': compiler,
    'library_group': 'wrf_shared',
    'platform': e.get('SYSTEMOS') or os.uname().sysname,
    'architecture': os.uname().machine,
    'WRF_FOLDER': str(Path(e['WRF_FOLDER']).resolve()),
    'DIR': str(root.resolve()),
    'NETCDF': str(netcdf.resolve()),
    'HDF5': str(grib2.resolve()),
}
if list((grib2/'lib').glob('libpnetcdf.*')):
    out['PNETCDF'] = str(grib2.resolve())
if compiler == 'gnu' and (mpi/'bin/mpifort').is_file() and (mpi/'bin/mpicc').is_file():
    out['MPI_DIR'] = str(mpi.resolve())
if (mct/'include').is_dir() and (mct/'lib').is_dir():
    out['MCT_DIR'] = str(mct.resolve())

# Prepend only paths owned by the installed scientific libraries.
path = [str(p.resolve()) for p in (netcdf/'bin', grib2/'bin') if p.is_dir()]
ld = [str(p.resolve()) for p in (netcdf/'lib', grib2/'lib') if p.is_dir()]
if 'MPI_DIR' in out:
    path.insert(0, str((mpi/'bin').resolve()))
    if (mpi/'lib').is_dir():
        ld.append(str((mpi/'lib').resolve()))
if 'MCT_DIR' in out:
    ld.append(str((mct/'lib').resolve()))
out['PATH'] = ':'.join(path)
out['LD_LIBRARY_PATH'] = ':'.join(ld)

lines = ['# WRF-MOSIT v2.0.0: reusable scientific-library locations only',
         '# WRF, WRFDA, WRFPLUS, KPP, and other model exports remain in MOSIT.']
for key, value in out.items():
    lines.append(f'{key}: {value}' if isinstance(value, int) else
                 f'{key}: {json.dumps(value, ensure_ascii=True)}')
p = Path(e['MOSIT_PROFILE_FILE'])
temp = p.with_suffix('.yaml.tmp')
with temp.open('w', encoding='utf-8') as fh:
    fh.write('\n'.join(lines) + '\n')
os.chmod(temp, 0o600)
temp.replace(p)
print(f'WRF-MOSIT: library profile saved: {p}')
WRF_MOSIT_WRITE_YAML
}

# ----------------------------------------------------------------------
# YAML Registry | Parse an Existing Library Profile
# Read the restricted YAML schema and export only recognized library metadata.
# ----------------------------------------------------------------------
wrf_mosit_load_library_profile() {
  local profile="$1" settings_file
  [ -f "$profile" ] || {
    echo "Library profile not found: $profile"
    return 1
  }
  # Parse YAML into a temporary file of shell-safe exports rather than
  # executing arbitrary text from the input YAML file.
  settings_file=$(mktemp) || return 1
  python3 - "$profile" > "$settings_file" << 'WRF_MOSIT_READ_YAML'
import json
import re
import shlex
import sys
from pathlib import Path

keys = {'DIR', 'NETCDF', 'HDF5', 'PNETCDF', 'MPI_DIR', 'MCT_DIR'}
meta = {'compiler': 'MOSIT_PROFILE_COMPILER',
        'library_group': 'MOSIT_PROFILE_GROUP',
        'platform': 'MOSIT_PROFILE_PLATFORM',
        'architecture': 'MOSIT_PROFILE_ARCH',
        'PATH': 'MOSIT_PROFILE_PATH',
        'LD_LIBRARY_PATH': 'MOSIT_PROFILE_LD_LIBRARY_PATH',
        'WRF_FOLDER': 'MOSIT_PROFILE_SOURCE_ROOT'}
values = {}
for i, line in enumerate(Path(sys.argv[1]).read_text(encoding='utf-8').splitlines(), 1):
    if not line.strip() or line.lstrip().startswith('#'):
        continue
    match = re.fullmatch(r'([A-Za-z][A-Za-z0-9_]*): (.+)', line)
    if not match:
        sys.exit(f'Unsupported profile syntax at line {i}')
    key, raw = match.groups()
    if key == 'schema_version':
        if raw != '1':
            sys.exit('Unsupported YAML profile version')
        values[key] = 1
        continue
    try:
        value = json.loads(raw)
    except ValueError:
        sys.exit(f'Invalid quoted YAML value at line {i}')
    if not isinstance(value, str):
        sys.exit(f'Profile field {key} must be a string')
    values[key] = value

required = ('schema_version', 'compiler', 'platform', 'architecture',
            'WRF_FOLDER', 'DIR', 'NETCDF', 'HDF5', 'PATH', 'LD_LIBRARY_PATH')
if any(k not in values for k in required):
    sys.exit('Library profile is incomplete')
if values['compiler'] not in ('gnu', 'intel'):
    sys.exit('Unsupported library compiler family')
for key, value in values.items():
    target = meta.get(key, key if key in keys else None)
    if target:
        print(f'export {target}={shlex.quote(value)}')
WRF_MOSIT_READ_YAML
  if [ $? -ne 0 ]; then
    rm -f "$settings_file"
    return 1
  fi
  unset PNETCDF MPI_DIR MCT_DIR MOSIT_PROFILE_GROUP
  # Load only exports generated by the constrained YAML parser.
  . "$settings_file"
  rm -f "$settings_file"
}

# ----------------------------------------------------------------------
# YAML Registry | Register Previously Installed Libraries
# Register locations from an existing installation; this does not rerun
# compiler tests.
# ----------------------------------------------------------------------
wrf_mosit_existing_libraries() {
  local existing_root compiler_choice default_root=""
  echo "Register already-installed WRF scientific libraries"
  if [ -d "$HOME/WRF_Intel/Libs" ]; then
    default_root="$HOME/WRF_Intel"
  elif [ -d "$HOME/WRF/Libs" ]; then
    default_root="$HOME/WRF"
  fi
  if [ -n "$default_root" ]; then
    read -r -p "Existing installation root [$default_root]: " existing_root
    existing_root="${existing_root:-$default_root}"
  else
    read -r -p "Existing installation root (full path): " existing_root
  fi
  if [[ "$existing_root" == "~/"* ]]; then existing_root="$HOME/${existing_root:2}"; fi
  # Accept an installation root, its Libs folder, or an existing library YAML path.
  case "$existing_root" in
    */wrf-libraries.yaml) existing_root="${existing_root%/Libs/wrf-libraries.yaml}" ;;
    */Libs) existing_root="${existing_root%/Libs}" ;;
    */Libs/) existing_root="${existing_root%/Libs/}" ;;
  esac
  if [ -z "$existing_root" ] || [ ! -d "$existing_root/Libs" ]; then
    echo "Libs directory not found. Enter an existing WRF installation root, its Libs folder, or wrf-libraries.yaml."
    return 1
  fi
  WRF_FOLDER=$(cd "$existing_root" && pwd -P) || return 1
  export WRF_FOLDER DIR="${WRF_FOLDER}/Libs"
  read -r -p "Compiler family: 1) GNU  2) Intel oneAPI: " compiler_choice
  case "$compiler_choice" in
    1) export FC=gfortran ;;
    2) export FC=ifx ;;
    *)
      echo "Invalid compiler selection."
      return 1
      ;;
  esac
  export MOSIT_PROFILE_ORIGIN="registered-existing-paths-only"
  if ! wrf_mosit_save_library_profile; then
    unset MOSIT_PROFILE_ORIGIN
    echo "Existing library registration failed."
    return 1
  fi
  unset MOSIT_PROFILE_ORIGIN
  echo "Registration checks library locations only; build compatibility is not verified here."
}

# Reuse-library mode is set only after a validated YAML profile has been loaded.
MOSIT_REUSE_LIBS=0
MOSIT_REUSE_GEOG=0

# ----------------------------------------------------------------------
# YAML Registry | Validate Compatibility Before Reuse
# Reject specialized profiles, compiler-family mismatches, architecture
# mismatches, and missing libraries.
# ----------------------------------------------------------------------
wrf_mosit_select_existing_yaml() {
  local candidate prompt_value default_profile="" profile_root_name
  if [ "${CMAQ_PICK:-0}" = 1 ] || [ "${SFIRE_PICK:-0}" = 1 ] || [ "${COAWST_PICK:-0}" = 1 ]; then
    echo "ERROR: WRF-CMAQ, WRF-SFIRE, and COAWST always require fresh scientific libraries."
    return 1
  fi
  echo ""
  echo "Existing WRF-MOSIT YAML profiles:"
  local count=0
  # List profiles found within the user home directory. If exactly one
  # profile exists, offer it as the default choice.
  while IFS= read -r candidate; do
    count=$((count + 1))
    printf '  %s\n' "$candidate"
    if [ "$count" -eq 1 ]; then default_profile="$candidate"; fi
  done < <(find "$HOME" -maxdepth 4 -name 'wrf-libraries.yaml' -type f -print 2> /dev/null | sort)
  if [ "$count" -ne 1 ]; then default_profile=""; fi
  if [ -n "$default_profile" ]; then
    read -r -p "Existing library YAML [$default_profile]: " prompt_value
    candidate="${prompt_value:-$default_profile}"
  else
    read -r -p "Full path to wrf-libraries.yaml: " candidate
  fi
  candidate="${candidate#\'}"
  candidate="${candidate%\'}"
  candidate="${candidate#\"}"
  candidate="${candidate%\"}"
  case "$candidate" in
    '~/'*) candidate="$HOME/${candidate:2}" ;;
    '\$HOME/'*) candidate="$HOME/${candidate:6}" ;;
  esac
  if ! wrf_mosit_load_library_profile "$candidate"; then
    echo "ERROR: Could not load existing scientific-library YAML."
    return 1
  fi
  # A profile marked for a specialized model is not a shared WRF library
  # stack, even when the compiler family happens to match.
  if [ -n "${MOSIT_PROFILE_GROUP:-}" ] && [ "$MOSIT_PROFILE_GROUP" != wrf_shared ]; then
    echo "ERROR: YAML library group is not compatible with WRF-ARW, WRF-Chem, or WRF-Hydro."
    return 1
  fi
  profile_root_name=$(printf "%s" "${MOSIT_PROFILE_SOURCE_ROOT##*/}" | tr "[:lower:]" "[:upper:]")
  case "$profile_root_name" in
    *CMAQ* | *SFIRE* | *COAWST*)
      echo "ERROR: Specialized CMAQ, SFIRE, or COAWST libraries cannot be reused for WRF-ARW, WRF-Chem, or WRF-Hydro."
      return 1
      ;;
  esac
  # Reject profiles from a different CPU architecture before checking files.
  if [ "$MOSIT_PROFILE_ARCH" != "$(uname -m)" ]; then
    echo "ERROR: YAML architecture $MOSIT_PROFILE_ARCH does not match $(uname -m)."
    return 1
  fi
  # Do not mix compiler families: GNU-built libraries are for GNU builds,
  # and Intel oneAPI-built libraries are for Intel oneAPI builds only.
  local selected_compiler=""
  if [ "${Ubuntu_64bit_Intel:-0}" = 1 ] || [ "${RHL_64bit_Intel:-0}" = 1 ]; then
    selected_compiler="intel"
  fi
  if [ "${Ubuntu_64bit_GNU:-0}" = 1 ] || [ "${RHL_64bit_GNU:-0}" = 1 ] \
    || [ "${RHL_64bit_GNU:-0}" = 2 ] || [ "${macos_64bit_GNU:-0}" = 1 ]; then
    if [ -n "$selected_compiler" ]; then
      echo "ERROR: Conflicting Intel and GNU compiler selections."
      return 1
    fi
    selected_compiler="gnu"
  fi
  if [ -z "$selected_compiler" ]; then
    echo "ERROR: Select GNU or Intel oneAPI before loading a library YAML."
    return 1
  fi
  # Reject incompatible compiler families before any model is built.
  # This is an explicit safety boundary for compiled Fortran/C libraries.
  if [ "$MOSIT_PROFILE_COMPILER" != "$selected_compiler" ]; then
    echo "ERROR: Incompatible scientific-library YAML compiler family."
    echo "  Selected build compiler: $selected_compiler"
    echo "  YAML library compiler:   $MOSIT_PROFILE_COMPILER"
    echo "GNU libraries cannot build Intel WRF, and Intel libraries cannot build GNU WRF."
    echo "Choose a matching YAML or install new scientific libraries."
    return 1
  fi
  echo "[PASS] YAML compiler family matches the selected $selected_compiler build"
  if [ ! -d "$DIR" ] || [ ! -f "$NETCDF/include/netcdf.inc" ] \
    || ! compgen -G "$NETCDF/lib/libnetcdff.*" > /dev/null \
    || ! compgen -G "$HDF5/lib/libhdf5.*" > /dev/null; then
    echo "ERROR: The YAML references missing NetCDF-Fortran or HDF5 files."
    return 1
  fi
  if [ "$MOSIT_PROFILE_COMPILER" = gnu ] \
    && { [ -z "${MPI_DIR:-}" ] || [ ! -x "$MPI_DIR/bin/mpifort" ] || [ ! -x "$MPI_DIR/bin/mpicc" ]; }; then
    echo "ERROR: Missing GNU MPI wrappers in the YAML library profile."
    return 1
  fi
  if [ "${COAWST_PICK:-0}" = 1 ] \
    && ! compgen -G "$NETCDF/lib/libnetcdf_c++4.*" > /dev/null \
    && ! compgen -G "$NETCDF/lib/libnetcdf_c++.*" > /dev/null; then
    echo "ERROR: COAWST requires a YAML library installation containing NetCDF-CXX."
    echo "Register COAWST libraries or install NetCDF-CXX before rebuilding."
    return 1
  fi
  # Resolve the original library location to a physical path so a new
  # installation can link to it without confusing the source and target.
  MOSIT_SOURCE_LIBS="$(cd "$DIR" && pwd -P)" || return 1
  MOSIT_PROFILE_SOURCE_ROOT="$(cd "$(dirname "$MOSIT_SOURCE_LIBS")" && pwd -P)" || return 1
  export MOSIT_SOURCE_LIBS MOSIT_PROFILE_SOURCE_ROOT
  echo "[PASS] Scientific-library YAML loaded: $candidate"
  echo "[PASS] Compiler family: $MOSIT_PROFILE_COMPILER; architecture: $MOSIT_PROFILE_ARCH"
  echo "[PASS] NetCDF and HDF5 library locations verified"
  MOSIT_REUSE_LIBS=1
}

# ----------------------------------------------------------------------
# YAML Registry | Create an Independent Model Directory
# Create links to shared scientific libraries without overwriting the source
# installation.
# ----------------------------------------------------------------------
wrf_mosit_prepare_reused_tree() {
  local suffix suggested_root target requested target_real
  suffix="MODEL"
  if [ "${WRF_PICK:-0}" = 1 ]; then
    case "$WRF_NESTING_OPTION" in
      1) suffix="ARW_BASIC" ;;
      2) suffix="ARW_MOVING" ;;
      3) suffix="ARW_VORTEX" ;;
      *)
        echo "Invalid WRF-ARW nesting selection."
        return 1
        ;;
    esac
  fi
  if [ "${WRFHYDRO_COUPLED_PICK:-0}" = 1 ]; then suffix="WRFHYDRO_COUPLED"; fi
  if [ "${WRFHYDRO_STANDALONE_PICK:-0}" = 1 ]; then suffix="WRFHYDRO_STANDALONE"; fi
  if [ "${SFIRE_PICK:-0}" = 1 ]; then suffix="WRF_SFIRE"; fi
  if [ "${CMAQ_PICK:-0}" = 1 ]; then suffix="WRF_CMAQ"; fi
  if [ "${COAWST_PICK:-0}" = 1 ]; then suffix="COAWST"; fi
  if [ "${WRFCHEM_PICK:-0}" = 1 ]; then suffix="WRFCHEM"; fi
  # Restore the toolchain that matches the YAML: Intel oneAPI on this path,
  # and GNU plus the registered MPICH wrappers on the alternate path.
  if [ "$MOSIT_PROFILE_COMPILER" = intel ]; then
    suggested_root="$HOME/WRF_Intel_${suffix}_${WRF_VERSION}"
  else
    suggested_root="$HOME/WRF_GNU_${suffix}_${WRF_VERSION}"
  fi
  read -r -p "New model installation directory [$suggested_root]: " requested
  target="${requested:-$suggested_root}"
  case "$target" in
    '~/'*) target="$HOME/${target:2}" ;;
    '\$HOME/'*) target="$HOME/${target:6}" ;;
  esac
  case "$target" in /*) ;; *)
    echo "ERROR: Use an absolute directory path."
    return 1
    ;;
  esac
  # Do not overwrite an existing model tree when creating a YAML-reuse build.
  if [ -e "$target" ] && [ "$(find "$target" -mindepth 1 -maxdepth 1 -print -quit 2> /dev/null)" ]; then
    echo "ERROR: Installation directory already contains files: $target"
    echo "Existing WRF installations are never overwritten."
    return 1
  fi
  mkdir -p "$target/Libs" "$target/Downloads" || return 1
  target_real="$(cd "$target" && pwd -P)" || return 1
  if [ "$target_real" = "$MOSIT_PROFILE_SOURCE_ROOT" ] \
    || [[ "$target_real/" == "$MOSIT_PROFILE_SOURCE_ROOT/"* ]] \
    || [[ "$MOSIT_PROFILE_SOURCE_ROOT/" == "$target_real/"* ]]; then
    echo "ERROR: New model directory must be separate from existing scientific libraries."
    return 1
  fi
  if [ -e "$target_real/Libs/NETCDF" ] || [ -e "$target_real/Libs/grib2" ]; then
    echo "ERROR: Library aliases already exist in target directory."
    return 1
  fi
  # Create directory links to the validated library prefixes; do not copy
  # or recompile shared binaries into the new model directory.
  ln -s "$NETCDF" "$target_real/Libs/NETCDF" || return 1
  ln -s "$HDF5" "$target_real/Libs/grib2" || return 1
  if [ -n "${MPI_DIR:-}" ]; then
    ln -s "$MPI_DIR" "$target_real/Libs/MPICH" || return 1
  fi
  MOSIT_NEW_ROOT="$target_real"
  export MOSIT_NEW_ROOT
  echo "[PASS] Independent WRF installation directory: $MOSIT_NEW_ROOT"
  echo "[PASS] Scientific-library aliases point to existing library files"
}

# ----------------------------------------------------------------------
# YAML Registry | Restore Compiler and Library Exports
# Set compiler, MPI, NetCDF, HDF5, and other exports for the new installation.
# ----------------------------------------------------------------------
wrf_mosit_restore_reused_libraries() {
  # Keep branch-specific WRF, WRFDA, WRFPLUS, KPP, and Hydro exports in their original blocks.
  export WRF_FOLDER="$MOSIT_NEW_ROOT" DIR="$MOSIT_NEW_ROOT/Libs"
  export NETCDF="$DIR/NETCDF" NETCDF_ROOT="$DIR/NETCDF" NetCDF_ROOT="$DIR/NETCDF"
  export NETCDF_INC="$NETCDF/include" NETCDF_LIB="$NETCDF/lib"
  export NETCDF_INCDIR="$NETCDF/include" NETCDF_LIBDIR="$NETCDF/lib" NETCDFPATH="$NETCDF"
  export HDF5="$DIR/grib2" HDF5_ROOT="$DIR/grib2" PHDF5="$DIR/grib2" PHDF5_ROOT="$DIR/grib2"
  export HDF5_INCDIR="$DIR/grib2/include" HDF5_LIBDIR="$DIR/grib2/lib"
  export PHDF5_INCDIR="$DIR/grib2/include" PHDF5_LIBDIR="$DIR/grib2/lib"
  if compgen -G "$DIR/grib2/lib/libpnetcdf.*" > /dev/null; then
    export PNETCDF="$DIR/grib2" PNETCDF_DIR="$DIR/grib2" PNETCDF_ROOT="$DIR/grib2"
    local netcdf_pnetcdf_link="-lpnetcdf "
  else
    unset PNETCDF PNETCDF_DIR PNETCDF_ROOT
    local netcdf_pnetcdf_link=""
  fi
  export JASPERLIB="$DIR/grib2/lib" JASPERINC="$DIR/grib2/include" JASPER_DIR="$DIR/grib2"
  export Jasper_ROOT="$DIR/grib2/lib" PNG_ROOT="$DIR/grib2"
  export ZLIB_ROOT="$DIR/grib2" ZLIBLIB="$DIR/grib2/lib" ZLIBINC="$DIR/grib2/include"
  if [ "$MOSIT_PROFILE_COMPILER" = intel ]; then
    if [ -f /opt/intel/oneapi/setvars.sh ]; then
      source /opt/intel/oneapi/setvars.sh --force > /dev/null || return 1
    else
      echo "ERROR: Intel oneAPI environment is missing."
      return 1
    fi
    export CC=icx CXX=icpx FC=ifx F77=ifx F90=ifx
    export MPIFC=mpiifx MPIF77=mpiifx MPIF90=mpiifx MPICC=mpiicx MPICXX=mpiicpx
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-unused-command-line-argument"
    export FFLAGS="" FCFLAGS=""
    export LIBS="-lnetcdf ${netcdf_pnetcdf_link}-lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc"
  else
    export CC=gcc CXX=g++ FC=gfortran F77=gfortran F90=gfortran
    export MPIFC="$DIR/MPICH/bin/mpifort" MPIF77="$DIR/MPICH/bin/mpifort" MPIF90="$DIR/MPICH/bin/mpifort"
    export MPICC="$DIR/MPICH/bin/mpicc" MPICXX="$DIR/MPICH/bin/mpicxx"
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"
    local gcc_major
    gcc_major="$(gfortran -dumpversion | cut -d. -f1)"
    if [[ "$gcc_major" =~ ^[0-9]+$ ]] && [ "$gcc_major" -ge 10 ]; then
      export fallow_argument=-fallow-argument-mismatch boz_argument=-fallow-invalid-boz
    else
      export fallow_argument="" boz_argument=""
    fi
    export FFLAGS="$fallow_argument" FCFLAGS="$fallow_argument"
    export LIBS="-lnetcdf ${netcdf_pnetcdf_link}-lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
  fi
  # Point configure/build tools at the selected library headers and
  # linker paths, including runtime library search paths.
  export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
  export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
  export PATH="$DIR/NETCDF/bin:$DIR/grib2/bin${MPI_DIR:+:$DIR/MPICH/bin}:$PATH"
  export LD_LIBRARY_PATH="$DIR/NETCDF/lib:$DIR/grib2/lib${MPI_DIR:+:$DIR/MPICH/lib}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  if [ "$MOSIT_PROFILE_COMPILER" = gnu ]; then
    export GCC_VERSION="$(gcc -dumpversion)" GFORTRAN_VERSION="$(gfortran -dumpversion)"
    export GPLUSPLUS_VERSION="$(g++ -dumpversion)"
    export GCC_VERSION_MAJOR_VERSION="${GCC_VERSION%%.*}"
    export GFORTRAN_VERSION_MAJOR_VERSION="${GFORTRAN_VERSION%%.*}"
    export GPLUSPLUS_VERSION_MAJOR_VERSION="${GPLUSPLUS_VERSION%%.*}"
    export version_10=10
  fi
  # Fail early if a selected compiler or MPI wrapper is unavailable;
  # the profile paths alone cannot make a missing tool executable.
  if ! command -v "$CC" > /dev/null 2>&1 || ! command -v "$FC" > /dev/null 2>&1 \
    || ! command -v "$MPIFC" > /dev/null 2>&1 || ! command -v "$MPICC" > /dev/null 2>&1; then
    echo "ERROR: Compiler or MPI wrappers required by the library profile are missing."
    return 1
  fi
  export CPU_CORE="$(getconf _NPROCESSORS_ONLN 2> /dev/null || echo 2)"
  export CPU_6CORE=6
  export CPU_QUARTER=$((CPU_CORE / 4))
  export CPU_QUARTER_EVEN=$((CPU_QUARTER - CPU_QUARTER % 2))
  if [ "$CPU_CORE" -le 6 ]; then export CPU_QUARTER_EVEN=2; fi
  mkdir -p "$WRF_FOLDER/Downloads" || return 1
  echo "[PASS] Reusing installed NetCDF, HDF5, MPI, and GRIB2 scientific libraries"
  echo "[PASS] Library exports restored for $WRF_FOLDER"
}

# ----------------------------------------------------------------------
# WPS Geography | Link an Existing Dataset
# Link existing WPS_GEOG data and refuse to replace an unrelated directory.
# ----------------------------------------------------------------------
wrf_mosit_link_existing_geog() {
  if [ -z "${MOSIT_GEOG_SOURCE:-}" ]; then
    echo "ERROR: No existing WPS_GEOG source has been selected."
    return 1
  fi
  mkdir -p "$WRF_FOLDER/GEOG" || return 1
  if [ -L "$WRF_FOLDER/GEOG/WPS_GEOG" ]; then
    if [ "$(readlink -f "$WRF_FOLDER/GEOG/WPS_GEOG")" = "$MOSIT_GEOG_SOURCE" ]; then
      return 0
    fi
    echo "ERROR: GEOG link points to a different dataset."
    return 1
  fi
  if [ -e "$WRF_FOLDER/GEOG/WPS_GEOG" ]; then
    if [ "$(cd "$WRF_FOLDER/GEOG/WPS_GEOG" && pwd -P)" = "$MOSIT_GEOG_SOURCE" ]; then
      return 0
    fi
    echo "ERROR: Cannot replace existing GEOG directory: $WRF_FOLDER/GEOG/WPS_GEOG"
    return 1
  fi
  # Link large geographic datasets instead of copying or downloading them.
  # The existing WPS_GEOG source directory is never changed here.
  ln -s "$MOSIT_GEOG_SOURCE" "$WRF_FOLDER/GEOG/WPS_GEOG" || return 1
  echo "[PASS] WPS_GEOG linked to existing data without redownloading"
}

# ----------------------------------------------------------------------
# WPS Geography | Select Download or Existing Dataset
# Ask whether to reuse geographic input files or download a fresh dataset.
# ----------------------------------------------------------------------
wrf_mosit_choose_geog() {
  local default_geog="" answer input_path
  # Prefer GEOG data next to the selected shared-library source when it
  # exists; users can still choose another valid dataset directory.
  if [ "$MOSIT_REUSE_LIBS" = 1 ] && [ -d "$MOSIT_PROFILE_SOURCE_ROOT/GEOG/WPS_GEOG" ]; then
    default_geog="$MOSIT_PROFILE_SOURCE_ROOT/GEOG/WPS_GEOG"
  elif [ -d "$HOME/WRF_Intel/GEOG/WPS_GEOG" ]; then
    default_geog="$HOME/WRF_Intel/GEOG/WPS_GEOG"
  elif [ -d "$HOME/WRF/GEOG/WPS_GEOG" ]; then
    default_geog="$HOME/WRF/GEOG/WPS_GEOG"
  fi
  echo 'Mandatory WPS geographical-data source:'
  echo '  1) Download new WPS_GEOG data (default)'
  echo '  2) Reuse an existing WPS_GEOG directory'
  echo '  Note: downloading can require substantial disk space.'
  read -r -p 'Select data source [1-2, default 1]: ' answer || return 1
  case "${answer:-1}" in
    1)
      echo 'GEOG source: new download of mandatory datasets.'
      MOSIT_REUSE_GEOG=0
      return 0
      ;;
    2) ;;
    *)
      echo 'Invalid GEOG selection. Enter 1 or 2.'
      return 1
      ;;
  esac
  if [ -n "$default_geog" ]; then
    read -r -p "Existing WPS_GEOG path [$default_geog]: " input_path
    input_path="${input_path:-$default_geog}"
  else
    read -r -p "Existing WPS_GEOG path (absolute; leave blank to download): " input_path
  fi
  case "$input_path" in
    '~/'*) input_path="$HOME/${input_path:2}" ;;
    '\$HOME/'*) input_path="$HOME/${input_path:6}" ;;
  esac
  if [ -z "$input_path" ]; then
    echo 'ERROR: Select option 1 to download GEOG, or enter an existing directory.'
    return 1
  fi
  if [ ! -d "$input_path" ] || [ -z "$(find "$input_path" -mindepth 1 -maxdepth 1 -print -quit 2> /dev/null)" ]; then
    echo "ERROR: Existing WPS_GEOG directory is missing or empty: $input_path"
    return 1
  fi
  # Store the canonical GEOG path, which is used to create and check links.
  MOSIT_GEOG_SOURCE="$(cd "$input_path" && pwd -P)" || return 1
  MOSIT_REUSE_GEOG=1
  echo "[PASS] Existing WPS geographical data selected: $MOSIT_GEOG_SOURCE"
  if [ "$MOSIT_REUSE_LIBS" = 1 ]; then
    mkdir -p "$MOSIT_NEW_ROOT/GEOG" || return 1
    if [ -e "$MOSIT_NEW_ROOT/GEOG/WPS_GEOG" ] || [ -L "$MOSIT_NEW_ROOT/GEOG/WPS_GEOG" ]; then
      echo "ERROR: Destination GEOG path already exists."
      return 1
    fi
    ln -s "$MOSIT_GEOG_SOURCE" "$MOSIT_NEW_ROOT/GEOG/WPS_GEOG" || return 1
  fi
}

