################################################################################
# System Detection | CPU Architecture
# Determine if the system is 32 or 64-bit based on the architecture
################################################################################
# The hardware architecture controls supported binary downloads and
# whether a reusable YAML matches the host machine.
export SYS_ARCH=$(uname -m)

if [ "$SYS_ARCH" = "x86_64" ] || [ "$SYS_ARCH" = "arm64" ] || [ "$SYS_ARCH" = "aarch64" ]; then
  export SYSTEMBIT="64"
else
  export SYSTEMBIT="32"
fi

# Determine if aarch64 is present
if [ "$SYS_ARCH" = "aarch64" ]; then
  export aarch64=1
fi

# Determine the chip type if on macOS (ARM or Intel)
if [ "$SYS_ARCH" = "arm64" ]; then
  export MAC_CHIP="ARM"
else
  export MAC_CHIP="Intel"
fi

################################################################################
# System Detection | Operating System
# Detect if the OS is macOS or Linux
################################################################################
export SYS_OS=$(uname -s)

if [ "$SYS_OS" = "Darwin" ]; then
  export SYSTEMOS="MacOS"
  # Get the macOS version using sw_vers
  export MACOS_VERSION=$(sw_vers -productVersion)
elif [ "$SYS_OS" = "Linux" ]; then
  export SYSTEMOS="Linux"
fi

################################################################################
# System Detection | Linux Distribution
# More accurate Linux distribution detection using /etc/os-release
################################################################################
################################################################################
# System Detection | Distribution and Package Manager
################################################################################
# Use /etc/os-release to select the Debian/Ubuntu versus RHL package path;
# the package manager is detected separately from the OS family.
if [ "$SYSTEMOS" = "Linux" ]; then
  if [ -r /etc/os-release ]; then
    . /etc/os-release

    # Human-friendly info
    DISTRO_NAME="${NAME:-Linux}"
    DISTRO_VERSION="${VERSION_ID:-unknown}"

    # Classify distro family using ID / ID_LIKE (more reliable than checking yum/dnf)
    # We'll use SYSTEMOS values you already branch on: "RHL" or "Linux"
    case " ${ID:-} ${ID_LIKE:-} " in
      *" rhel "* | *" fedora "* | *" centos "* | *" rocky "* | *" almalinux "*)
        SYSTEMOS="RHL"
        ;;
      *" debian "* | *" ubuntu "*)
        SYSTEMOS="Linux" # keep your existing "Linux" meaning Debian/Ubuntu path
        ;;
      *)
        SYSTEMOS="Linux" # unknowns fall back to generic Linux path
        ;;
    esac

    # Choose package manager (used for installs, not OS identity)
    if command -v dnf > /dev/null 2>&1; then
      PKG_MGR="dnf"
    elif command -v yum > /dev/null 2>&1; then
      PKG_MGR="yum"
    elif command -v apt-get > /dev/null 2>&1; then
      PKG_MGR="apt"
    else
      PKG_MGR="none"
    fi

  else
    echo "Unable to detect the Linux distribution version (missing /etc/os-release)."
    SYSTEMOS="Linux"
    PKG_MGR="none"
  fi
fi

# Display one platform summary before asking for the compiler.
printf '\n============================================================\n'
printf ' STEP 1 OF 6 | SYSTEM AND COMPILER\n'
printf '============================================================\n'
printf ' Platform : %s %s\n' "${DISTRO_NAME:-$SYSTEMOS}" "${DISTRO_VERSION:-${MACOS_VERSION:-}}"
printf ' Architecture: %s\n' "$SYS_ARCH"
if [ "$SYSTEMOS" != MacOS ]; then
  printf ' Package manager: %s\n' "${PKG_MGR:-unknown}"
fi

################################################################################
# Compiler Selection | GNU or Intel oneAPI
# The selected compiler family must match any scientific-library YAML profile.
################################################################################

# Only proceed with RHL-specific logic if the system is RHL
if [ "$SYSTEMOS" = "RHL" ]; then
  # Check for 32-bit RHL system
  if [ "$SYSTEMBIT" = "32" ]; then
    echo "Your system is not compatible with this script."
    exit 1
  fi

  # Check for 64-bit RHL system
  if [ "$SYSTEMBIT" = "64" ]; then

    # Check if RHL_64bit_Intel or RHL_64bit_GNU environment variables are set
    if [ -n "$RHL_64bit_Intel" ] || [ -n "$RHL_64bit_GNU" ]; then
      echo "The environment variable RHL_64bit_Intel/GNU is already set."
    else

      # Prompt user to select a compiler (numeric selection)
      echo "Which compiler do you want to use?"
      echo "1) Intel"
      echo "2) GNU"

      while true; do
        read -r -p "Please select 1 or 2: " yn

        case $yn in
          1)
            echo "Intel is selected for installation."
            export RHL_64bit_Intel=1
            break
            ;;
          2)
            echo "GNU is selected for installation."
            export RHL_64bit_GNU=1
            break
            ;;
          *)
            echo "Invalid selection. Please enter 1 or 2."
            ;;
        esac
      done
    fi

    # Check for the version of the GNU compiler (gcc)
    if [ -n "$RHL_64bit_GNU" ]; then
      export gcc_test_version=$(gcc -dumpversion 2>&1 | awk '{print $1}')
      export gcc_test_version_major=$(echo $gcc_test_version | awk -F. '{print $1}')
      export gcc_version_9="9"

      if [[ $gcc_test_version_major -lt $gcc_version_9 ]]; then
        export RHL_64bit_GNU=2
        echo "OLD GNU FILES FOUND."
        echo "RHL_64bit_GNU=$RHL_64bit_GNU"
      fi
    fi
  fi
fi

# Check for 64-bit Linux system (Debian/Ubuntu)
if [ "$SYSTEMBIT" = "64" ] && [ "$SYSTEMOS" = "Linux" ]; then
  echo ""

  # Check if Ubuntu_64bit_Intel or Ubuntu_64bit_GNU environment variables are set
  if [ -n "$Ubuntu_64bit_Intel" ] || [ -n "$Ubuntu_64bit_GNU" ]; then
    echo "The environment variable Ubuntu_64bit_Intel/GNU is already set."
  else

    # Prompt user to select a compiler
    echo "Which compiler do you want to use?"
    echo "1) Intel"
    echo "2) GNU"
      echo "Note: WRF-CMAQ is only compatible with GNU compilers."

    while true; do
      read -r -p "Please select 1 or 2: " yn

      case $yn in
        1)
          echo "Intel is selected for installation."
          export Ubuntu_64bit_Intel=1
          break
          ;;
        2)
          echo "GNU is selected for installation."
          export Ubuntu_64bit_GNU=1
          break
          ;;
        *)
          echo "Invalid selection. Please enter 1 or 2."
          ;;
      esac
    done
  fi
fi

# Check for 32-bit Linux system
if [ "$SYSTEMBIT" = "32" ] && [ "$SYSTEMOS" = "Linux" ]; then
  echo "Your system is not compatible with this script."
  exit 1
fi

################################################################################
# macOS Prerequisites | Command Line Tools and Homebrew
################################################################################

# Check for 32-bit macOS system
if [ "$SYSTEMBIT" = "32" ] && [ "$SYSTEMOS" = "MacOS" ]; then
  echo "Your system is not compatible with this script."
  exit 1
fi

# Check for 64-bit Intel-based macOS system
if [ "$SYSTEMBIT" = "64" ] && [ "$SYSTEMOS" = "MacOS" ] && [ "$MAC_CHIP" = "Intel" ]; then
  echo "Your system is a 64-bit version of macOS with an Intel chip."
  echo "Intel compilers are not compatible with this script."
  echo "Setting compiler to GNU."
  export macos_64bit_GNU=1

  # Ensure Xcode Command Line Tools are installed
  if ! xcode-select --print-path &> /dev/null; then
    echo "Installing Xcode Command Line Tools..."
    xcode-select --install

    # Add a loop to wait for the installation to be completed
    echo "Waiting for Xcode Command Line Tools to install. Please follow the installer prompts..."
    while ! xcode-select --print-path &> /dev/null; do
      sleep 30 # Wait for 5 seconds before checking again
    done

    echo "Xcode Command Line Tools installation confirmed."
  fi

  # Install Homebrew for Intel Macs in /usr/local
  echo "Installing Homebrew..."
  /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"

  echo 'eval "$(/usr/local/bin/brew shellenv)"' >> ~/.profile
  eval "$(/usr/local/bin/brew shellenv)"

  chsh -s /bin/bash
fi

# Check for 64-bit ARM-based macOS system (M1, M2 chips)
if [ "$SYSTEMBIT" = "64" ] && [ "$SYSTEMOS" = "MacOS" ] && [ "$MAC_CHIP" = "ARM" ]; then
  echo "Your system is a 64-bit version of macOS with an ARM chip (M1/M2)."
  echo "Intel compilers are not compatible with this script."
  echo "Setting compiler to GNU."
  export macos_64bit_GNU=1

  # Ensure Xcode Command Line Tools are installed
  if ! xcode-select --print-path &> /dev/null; then
    echo "Installing Xcode Command Line Tools..."
    xcode-select --install

    # Add a loop to wait for the installation to be completed
    echo "Waiting for Xcode Command Line Tools to install. Please follow the installer prompts..."
    while ! xcode-select --print-path &> /dev/null; do
      sleep 5 # Wait for 5 seconds before checking again
    done

    echo "Xcode Command Line Tools installation confirmed."
  fi

  # Install Homebrew for ARM Macs in /opt/homebrew
  echo "Installing Homebrew..."
  /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"

  echo 'eval "$(/opt/homebrew/bin/brew shellenv)"' >> ~/.profile
  eval "$(/opt/homebrew/bin/brew shellenv)"

  chsh -s /bin/bash
fi

################################################################################
# STEP 2 OF 6 | Modeling System and Nesting
# Choose a model before requesting its library and geographic dependencies.
################################################################################
printf '\n============================================================\n'
printf ' STEP 2 OF 6 | MODEL SELECTION\n'
printf '============================================================\n'
echo '  1) WRF-ARW'
echo '  2) WRF-Chem'
echo '  3) WRF-Hydro Coupled'
echo '  4) WRF-Hydro Standalone'
echo '  5) WRF-SFIRE          (GNU only)'
echo '  6) WRF-CMAQ           (GNU only; Linux x86_64)'
echo '  7) COAWST             (GNU only; Linux)'

while true; do
  read -r -p 'Select a model [1-7]: ' model_choice || exit 1
  case "$model_choice" in
    1) export WRF_PICK=1; MODEL_LABEL='WRF-ARW'; break ;;
    2) export WRFCHEM_PICK=1; MODEL_LABEL='WRF-Chem'; break ;;
    3) export WRFHYDRO_COUPLED_PICK=1; MODEL_LABEL='WRF-Hydro Coupled'; break ;;
    4) export WRFHYDRO_STANDALONE_PICK=1; MODEL_LABEL='WRF-Hydro Standalone'; break ;;
    5) export SFIRE_PICK=1; MODEL_LABEL='WRF-SFIRE'; break ;;
    6) export CMAQ_PICK=1; MODEL_LABEL='WRF-CMAQ'; break ;;
    7) export COAWST_PICK=1; MODEL_LABEL='COAWST'; break ;;
    *) echo 'Invalid model selection. Enter a number from 1 to 7.' ;;
  esac
done
printf 'Selected model: %s\n' "$MODEL_LABEL"

# Moving and vortex-following nesting are supported only for WRF-ARW.
NESTING_LABEL='Not applicable'
if [ "${WRF_PICK:-0}" = 1 ]; then
  echo ''
  echo 'WRF-ARW nesting configuration:'
  echo '  1) Basic nesting'
  echo '  2) Preset moves'
  echo '  3) Vortex following'
  while true; do
    read -r -p 'Select nesting mode [1-3]: ' nesting_choice || exit 1
    case "$nesting_choice" in
      1) export WRF_NESTING_OPTION=1; NESTING_LABEL='Basic'; break ;;
      2) export WRF_NESTING_OPTION=2; NESTING_LABEL='Preset moves'; break ;;
      3) export WRF_NESTING_OPTION=3; NESTING_LABEL='Vortex following'; break ;;
      *) echo 'Invalid nesting selection. Enter 1, 2, or 3.' ;;
    esac
  done
  printf 'Selected nesting: %s\n' "$NESTING_LABEL"
fi

################################################################################
# STEP 3 OF 6 | Scientific Libraries
# Reuse is allowed for WRF-ARW, WRF-Chem, and WRF-Hydro only. Specialized
# models always build their own dependency stacks from source.
################################################################################
printf '\n============================================================\n'
printf ' STEP 3 OF 6 | SCIENTIFIC LIBRARIES\n'
printf '============================================================\n'
# These specialized models must always install their own dependencies.
# Do not offer the shared YAML option for them.
if [ "${CMAQ_PICK:-0}" = 1 ] || [ "${SFIRE_PICK:-0}" = 1 ] || [ "${COAWST_PICK:-0}" = 1 ]; then
  echo "$MODEL_LABEL requires fresh, model-specific scientific libraries."
  MOSIT_LIBRARY_CHOICE=1
else
  echo '  1) Install new scientific libraries (default)'
  echo '  2) Reuse existing compatible libraries using YAML'
  read -r -p 'Select library source [1-2, default 1]: ' MOSIT_LIBRARY_CHOICE || exit 1
fi
case "${MOSIT_LIBRARY_CHOICE:-1}" in
  1)
    MOSIT_REUSE_LIBS=0
    echo 'Library source: fresh installation.'
    ;;
  2)
    # Validate the existing profile before accepting its paths, compiler,
    # architecture, and library locations for this model build.
    wrf_mosit_select_existing_yaml || exit 1
    read -r -p "WRF version [${WRF_VERSION}]: " MOSIT_WANT_WRF_VERSION || exit 1
    if [ -n "$MOSIT_WANT_WRF_VERSION" ]; then
      if [[ ! "$MOSIT_WANT_WRF_VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        echo 'ERROR: WRF version must use X.Y.Z format.'
        exit 1
      fi
      export WRF_VERSION="$MOSIT_WANT_WRF_VERSION"
    fi
    read -r -p "WPS version [${WPS_VERSION}]: " MOSIT_WANT_WPS_VERSION || exit 1
    if [ -n "$MOSIT_WANT_WPS_VERSION" ]; then
      if [[ ! "$MOSIT_WANT_WPS_VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        echo 'ERROR: WPS version must use X.Y.Z format.'
        exit 1
      fi
      export WPS_VERSION="$MOSIT_WANT_WPS_VERSION"
    fi
    # Prepare a separate model installation tree with symlinks to the
    # registered libraries so the source installation is not overwritten.
    wrf_mosit_prepare_reused_tree || exit 1
    echo 'Library source: existing validated YAML profile.'
    ;;
  *)
    echo 'Invalid scientific-library choice.'
    exit 1
    ;;
esac

################################################################################
# STEP 4 OF 6 | WPS Geographic Input Data
# Select new or existing mandatory data first. Optional datasets are relevant
# only when MOSIT downloads a fresh WPS_GEOG dataset.
################################################################################
printf '\n============================================================\n'
printf ' STEP 4 OF 6 | WPS GEOGRAPHICAL DATA\n'
printf '============================================================\n'
WPS_GEOG_APPLICABLE=0
if [ "${WRF_PICK:-0}" = 1 ] || [ "${WRFCHEM_PICK:-0}" = 1 ] \
  || [ "${WRFHYDRO_COUPLED_PICK:-0}" = 1 ] || [ "${SFIRE_PICK:-0}" = 1 ] \
  || [ "${CMAQ_PICK:-0}" = 1 ]; then
  WPS_GEOG_APPLICABLE=1
  wrf_mosit_choose_geog || exit 1
else
  echo 'This model uses its own model-specific geographical-data workflow.'
fi

# Set explicit default values, including for branches where GEOG is skipped.
export WPS_Specific_Applications=0 Optional_GEOG=0
if [ "$WPS_GEOG_APPLICABLE" = 1 ] && [ "${MOSIT_REUSE_GEOG:-0}" != 1 ]; then
  echo ''
  echo 'Optional geographical-data packages (downloaded after mandatory GEOG):'
  echo 'Reference: https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html'
  echo ''
  echo 'Application-specific datasets (e.g., Noah-MP, urban, and chemistry):'
  echo '  1) Include'
  echo '  2) Skip (default)'
  while true; do
    read -r -p 'Select [1-2, default 2]: ' geog_specific_choice || exit 1
    case "${geog_specific_choice:-2}" in
      1) export WPS_Specific_Applications=1; break ;;
      2) break ;;
      *) echo 'Enter 1 or 2.' ;;
    esac
  done
  echo ''
  echo 'Additional optional datasets (e.g., alternate land-use products):'
  echo '  1) Include'
  echo '  2) Skip (default)'
  while true; do
    read -r -p 'Select [1-2, default 2]: ' geog_optional_choice || exit 1
    case "${geog_optional_choice:-2}" in
      1) export Optional_GEOG=1; break ;;
      2) break ;;
      *) echo 'Enter 1 or 2.' ;;
    esac
  done
elif [ "${MOSIT_REUSE_GEOG:-0}" = 1 ]; then
  echo 'Additional GEOG downloads skipped because an existing dataset was selected.'
fi

################################################################################
# STEP 5 OF 6 | Visualization, Model Configuration, and Optional Tools
# These selections do not change the scientific-library reuse policy.
################################################################################
printf '\n============================================================\n'
printf ' STEP 5 OF 6 | CONFIGURATION AND OPTIONAL TOOLS\n'
printf '============================================================\n'
echo 'Visualization program:'
echo '  1) OpenGrADS'
echo '  2) GrADS'
if [ "$SYS_ARCH" = aarch64 ] || [ "$SYS_ARCH" = arm64 ]; then
  echo '  Note: OpenGrADS x86_64 binaries cannot run natively on ARM64.'
fi
while true; do
  read -r -p 'Select visualization [1-2]: ' grads_choice || exit 1
  case "$grads_choice" in
    1)
      if [ "$SYS_ARCH" = aarch64 ] || [ "$SYS_ARCH" = arm64 ]; then
        echo 'OpenGrADS is unavailable for ARM64. Select GrADS (2).'
        continue
      fi
      export GRADS_PICK=1
      GRADS_LABEL='OpenGrADS'
      break
      ;;
    2) export GRADS_PICK=2; GRADS_LABEL='GrADS'; break ;;
    *) echo 'Enter 1 or 2.' ;;
  esac
done

echo ''
echo 'WRF/WPS configuration:'
echo '  1) Automatic configure selections'
echo '  2) Manual configure selections'
if [ "${WRF_PICK:-0}" = 1 ]; then
  echo "  WRF-ARW nesting mode: $NESTING_LABEL"
fi
while true; do
  read -r -p 'Select configuration [1-2]: ' config_choice || exit 1
  case "$config_choice" in
    1) export auto_config=1; CONFIG_LABEL='Automatic'; break ;;
    2) export auto_config=0; CONFIG_LABEL='Manual'; break ;;
    *) echo 'Enter 1 or 2.' ;;
  esac
done

# WRF-Chem preprocessing tools are offered only when WRF-Chem is selected.
export WRFCHEM_TOOLS=0
if [ "${WRFCHEM_PICK:-0}" = 1 ]; then
  echo ''
  echo 'Optional WRF-Chem preprocessing tools:'
  echo '  1) Install'
  echo '  2) Skip'
  while true; do
    read -r -p 'Select [1-2]: ' chem_tools_choice || exit 1
    case "$chem_tools_choice" in
      1) export WRFCHEM_TOOLS=1; break ;;
      2) break ;;
      *) echo 'Enter 1 or 2.' ;;
    esac
  done
fi

# DTC MET/METplus is an optional, independent installation. It is not
# available for macOS and remains disabled when using an existing YAML stack.
export DTC_MET=0
if [ "${MOSIT_REUSE_LIBS:-0}" = 1 ]; then
  echo ''
  echo 'DTC MET/METplus: unavailable when reusing scientific libraries.'
elif [ "$SYSTEMOS" = MacOS ]; then
  echo ''
  echo 'DTC MET/METplus: unavailable for macOS.'
else
  echo ''
  echo 'Optional DTC MET/METplus verification tools:'
  echo '  1) Install'
  echo '  2) Skip (default)'
  while true; do
    read -r -p 'Select [1-2, default 2]: ' dtc_choice || exit 1
    case "${dtc_choice:-2}" in
      1) export DTC_MET=1; break ;;
      2) break ;;
      *) echo 'Enter 1 or 2.' ;;
    esac
  done
fi

################################################################################
# Preflight Checks | Available Disk Space
################################################################################

printf '\n============================================================\n'
printf ' STEP 6 OF 6 | PREFLIGHT AND REVIEW\n'
printf '============================================================\n'
echo 'Checking available disk space...'

# Cross-platform disk space check (Linux + macOS)

HOME_DIR="${HOME}"
REQUIRED_GB=300
if [ "${MOSIT_REUSE_LIBS:-0}" = 1 ] && [ "${MOSIT_REUSE_GEOG:-0}" = 1 ]; then
  # Reduce the startup free-space requirement only when BOTH scientific
  # libraries and geographical data are being reused.
  REQUIRED_GB=50 # Both the scientific libraries and GEOG already exist
fi
REQUIRED_KB=$((REQUIRED_GB * 1024 * 1024)) # GiB in KiB

# df -k prints sizes in 1K blocks on both GNU (Linux) and BSD (macOS)
AVAILABLE_KB=$(df -k "$HOME_DIR" | awk 'NR==2 {print $4}')

if [ -z "$AVAILABLE_KB" ]; then
  echo "ERROR: Could not determine available disk space for $HOME_DIR"
  exit 1
fi

# Human-readable strings (GiB)
AVAILABLE_HR=$(awk -v kb="$AVAILABLE_KB" 'BEGIN { printf "%.1f GiB", kb/1024/1024 }')
REQUIRED_HR=$(awk -v kb="$REQUIRED_KB" 'BEGIN { printf "%.1f GiB", kb/1024/1024 }')

if [ "$AVAILABLE_KB" -lt "$REQUIRED_KB" ]; then
  echo
  echo "############################################################"
  echo "Not enough free disk space in $HOME_DIR."
  echo "  Required:  $REQUIRED_HR"
  echo "  Available: $AVAILABLE_HR"
  echo "Please free up space and rerun this script."
  echo "############################################################"
  echo
  exit 1
else
  echo "Disk space check passed: $AVAILABLE_HR available (need at least $REQUIRED_HR)."
fi

# Show the selected configuration before requesting elevated privileges.
if [ "${Ubuntu_64bit_Intel:-0}" = 1 ] || [ "${RHL_64bit_Intel:-0}" = 1 ]; then
  COMPILER_LABEL='Intel oneAPI'
else
  COMPILER_LABEL='GNU'
fi
printf '\n------------------------------------------------------------\n'
printf ' INSTALLATION SUMMARY\n'
