printf ' Visualization     : %s\n' "$GRADS_LABEL"
printf ' Configuration     : %s\n' "$CONFIG_LABEL"
printf ' DTC MET/METplus   : %s\n' "$([ "${DTC_MET:-0}" = 1 ] && echo Install || echo Skip)"
if [ "${WRFCHEM_PICK:-0}" = 1 ]; then
  printf ' WRF-Chem tools    : %s\n' "$([ "${WRFCHEM_TOOLS:-0}" = 1 ] && echo Install || echo Skip)"
fi
printf ' Available storage : %s\n' "$AVAILABLE_HR"
printf ' Required storage  : %s\n' "$REQUIRED_HR"
printf '%s\n' '------------------------------------------------------------'
echo '  1) Install'
echo '  2) Cancel'
while true; do
  # Ask for explicit approval before the sudo prompt or model builds begin.
  read -r -p 'Select [1-2]: ' install_choice || exit 1
  case "$install_choice" in
    1) break ;;
    2) echo 'Installation cancelled before model builds.'; exit 0 ;;
    *) echo 'Enter 1 to install or 2 to cancel.' ;;
  esac
done

################################################################################
# Preflight Checks | Sudo Authentication
################################################################################

# Limit password-entry attempts before stopping the installation.
MAX_RETRIES=3
attempt=0

while true; do
  ((attempt++))

  # After first failure, offer visible input
  if ((attempt > 1)); then
    read -r -p "Show password while typing? (y/N): " show_pw
  else
    show_pw="n"
  fi

  if [[ "$show_pw" =~ ^[Yy]$ ]]; then
    read -r -p "
    Password is only saved locally.
    Please enter your sudo password (user account password): " password1
    echo
    read -r -p "Please re-enter your password to verify: " password2
    echo
  else
    read -r -s -p "
    Password is only saved locally and will not be seen when typing.
    Please enter your sudo password (user account password): " password1
    echo
    read -r -s -p "Please re-enter your password to verify: " password2
    echo
  fi

  # Check if the passwords match
  if [ "$password1" = "$password2" ]; then
    export PASSWD="$password1"
    unset password1 password2 show_pw
    echo "Password verified successfully."
    break
  else
    echo "Passwords do not match."
    unset password1 password2
  fi

  # Enforce retry limit
  if ((attempt >= MAX_RETRIES)); then
    echo "Maximum attempts ($MAX_RETRIES) reached. Exiting."
    exit 1
  fi
done

echo "Beginning Installation"
echo ""
echo ""
################################################################################
