  GCC_LIB_DIR="/usr/lib/gcc/x86_64-linux-gnu"
  HIGHEST_GCC_MAJOR=$(ls "$GCC_LIB_DIR" | sort -V | tail -n 1)

  echo "Highest GCC directory detected: $HIGHEST_GCC_MAJOR"

  if [ ! -d "/usr/include/c++/${HIGHEST_GCC_MAJOR}" ]; then
