    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 "

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/bin/gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/bin/gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/bin/g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/
    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # I/O API | CMAQ Data Interfaces
    # Compile the I/O API components required by the CMAQ workflow.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    mkdir ioapi
    cd ioapi
    env -u LD_LIBRARY_PATH tar -xzf "${WRF_FOLDER}"/Downloads/ioapi-3.2.tar.gz

    # set gnu version
    export BIN=Linux2_x86_64gfort10
    export CPLMODE=nocpl
    mkdir $BIN

    # Link netcdf and grib lib folders to ioapi
    ln -sf "${WRF_FOLDER}"/Libs/NETCDF/lib/* "${WRF_FOLDER}"/Downloads/ioapi/$BIN
    ln -sf "${WRF_FOLDER}"/Libs/grib2/lib/* "${WRF_FOLDER}"/Downloads/ioapi/$BIN

    # copy makefiles from ioapi directory to source makefile
    # cp "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makefile.nocpl "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makefile
    # cp "${WRF_FOLDER}"/Downloads/ioapi/m3tools/Makefile.nocpl "${WRF_FOLDER}"/Downloads/ioapi/m3tools/Makefile
    cp "${WRF_FOLDER}"/Downloads/ioapi/Makefile.template "${WRF_FOLDER}"/Downloads/ioapi/Makefile

    # Add proper sed statements needed for gfortran
    sed -i '193s|-lnetcdff -lnetcdf| -lnetcdff -lnetcdf -lhdf5hl_fortran -lhdf5_fortran -lhdf5_hl -lhdf5 -ljpeg -lm -lz -lcurl|g' "${WRF_FOLDER}"/Downloads/ioapi/Makefile
    sed -i '210s|${IODIR}/Makefile ${TOOLDIR}/Makefile| |g' "${WRF_FOLDER}"/Downloads/ioapi/Makefile

    # Remove openmnp flags from Makefile
    sed -i '30s/ -fopenmp//g' "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makeinclude.$BIN
    sed -i '31s/ -fopenmp//g' "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makeinclude.$BIN

    # Fix GCC compatibility: declare exit() from stdlib.h
    sed -i '/#include "parms3.h"/a #include <stdlib.h>' \
      "${WRF_FOLDER}"/Downloads/ioapi/ioapi/sortic.c

    # Build IOAPI
    make configure 2>&1 | tee configure.log
    make -j 1 2>&1 | tee make.log

    # If statement to check that libioapi.a & m3xtract exist

    cd "${WRF_FOLDER}"/Downloads/ioapi/$BIN
    n=$(ls -lrt libioapi.a | wc -l)
    m=$(ls -rlt m3xtract | wc -l)
    if ((($n == 1) && ($m == 1))); then
      echo "All expected files created."

    else
      echo "Missing one or more expected files. Exiting the script."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
    echo " "

    mv "${WRF_FOLDER}"/Downloads/ioapi/$BIN "${WRF_FOLDER}"/Downloads/ioapi/Linux2_x86_64gfort
    export BIN=Linux2_x86_64gfort
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WRF-CMAQ | Source Download and Compilation
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  git clone -b main https://github.com/USEPA/CMAQ.git #clone CMAQ github to WRF_CMAQ Main Folder

  cd CMAQ
  cp bldit_project.csh bldit_project.csh.old # Create backup of build project script

  # Set path to where CMAQ will be built
  sed -i '19s|/home/username/path|"${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}|g' "${WRF_FOLDER}"/Downloads/CMAQ/bldit_project.csh
  # Build CMAQ Project
  ./bldit_project.csh

  cd "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}

  cp config_cmaq.csh config_cmaq.csh.old # Create backup of configure script

  # Sed statements to configure the Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}
  sed -i 's|netcdf_root_gcc|"${WRF_FOLDER}"/Libs/NETCDF|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|ioapi_root_gcc|"${WRF_FOLDER}"/Downloads/ioapi|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i '148s|WRF_ARCH|WRF_ARCH 34|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh

  # sed statements for paths in configure file
  sed -i 's|ioapi_inc_gcc|"${WRF_FOLDER}"/Downloads/ioapi/$BIN|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|ioapi_lib_gcc|"${WRF_FOLDER}"/Downloads/ioapi/$BIN|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdf_lib_gcc |"${WRF_FOLDER}"/Libs/NETCDF/lib|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdf_inc_gcc|"${WRF_FOLDER}"/Libs/NETCDF/include|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdff_lib_gcc|"${WRF_FOLDER}"/Libs/NETCDF/lib|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdff_inc_gcc|"${WRF_FOLDER}"/Libs/NETCDF/include|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|mpi_incl_gcc|"${WRF_FOLDER}"/Libs/MPICH|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|mpi_lib_gcc|"${WRF_FOLDER}"/Libs/MPICH|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh

  # compile the Chemistry Transport Model (CCTM) preprocess

  cd "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts

  cp bldit_cctm.csh bldit_cctm.csh.old # make a back up copy of .csh script

  # Sed statements for configuration
  sed -i 's|make_options = "-j" |make_options = "-j 1" |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh  # set multicore to half of available cpus
  sed -i '84s|#set|set|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh                                   # build two way
  sed -i 's|WRF_VRSN = v4.4.1|WRF_VRSN = v${WRF_VERSION}|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh # change wrf version from 4.4 to ${WRF_Version}

  sed -i '442s| if ( $? != 0 ) then| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i '443s|    set shaID   = "not_a_repo"| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i '444s| endif| |g' "${WRF_FOLDER}"/Downloads/CMAQ//Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  sed -i '814s|  if ($? == 0) then| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh #remove if statment for git_check
  sed -i '816s|  endif| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  sed -i 's|git clone --branch|git clone --recurse-submodules --branch|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i 's|compile em_real|compile -j 1 em_real|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  # Remove Intel-specific compiler flags from the CMAQ build generator.
  # This prevents bldmake from adding them to GNU WRF-CMAQ builds.

  sed -i \
    's|add_flags  = -fno-alias -mp1 -fp-model source -ftz |add_flags  = |g' \
    "${WRF_FOLDER}/Downloads/CMAQ/UTIL/bldmake/src/bldmake.f"

  # Build WRF-CMAQ
  ./bldit_cctm.csh gcc 2>&1 | tee bldit.cctm.twoway.gcc.log

  # Move built folder to top level directory

  mkdir "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  mv "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/BLD_WRFv${WRF_VERSION}_CCTM_v55_gcc/* "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files. Exiting the script."
    read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi
  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files. Exiting the script."
    read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-CMAQ | RHL | GNU
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$RHL_64bit_GNU" = "1" ] && [ "$CMAQ_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
    echo "$PASSWD" | sudo -S dnf -y install bzip2-devel
    echo "$PASSWD" | sudo -S dnf -y install cairo-devel
    echo "$PASSWD" | sudo -S dnf -y install cmake
    echo "$PASSWD" | sudo -S dnf -y install cpp
    echo "$PASSWD" | sudo -S dnf -y install curl
    echo "$PASSWD" | sudo -S dnf -y install curl-devel
    echo "$PASSWD" | sudo -S dnf -y install flex
    echo "$PASSWD" | sudo -S dnf -y install flex-devel
    echo "$PASSWD" | sudo -S dnf -y install fontconfig
    echo "$PASSWD" | sudo -S dnf -y install fontconfig-devel
    echo "$PASSWD" | sudo -S dnf -y install gcc
    echo "$PASSWD" | sudo -S dnf -y install gcc-c++
    echo "$PASSWD" | sudo -S dnf -y install gcc-gfortran
    echo "$PASSWD" | sudo -S dnf -y install git
    echo "$PASSWD" | sudo -S dnf -y install ksh
    echo "$PASSWD" | sudo -S dnf -y install libjpeg
    echo "$PASSWD" | sudo -S dnf -y install libjpeg-devel
    echo "$PASSWD" | sudo -S dnf -y install libstdc++
    echo "$PASSWD" | sudo -S dnf -y install libstdc++-devel
    echo "$PASSWD" | sudo -S dnf -y install libX11
    echo "$PASSWD" | sudo -S dnf -y install libX11-devel
    echo "$PASSWD" | sudo -S dnf -y install libXaw
    echo "$PASSWD" | sudo -S dnf -y install libXaw-devel
    echo "$PASSWD" | sudo -S dnf -y install libXext-devel
    echo "$PASSWD" | sudo -S dnf -y install libXmu
    echo "$PASSWD" | sudo -S dnf -y install libXmu-devel
    echo "$PASSWD" | sudo -S dnf -y install libXrender
    echo "$PASSWD" | sudo -S dnf -y install libXrender-devel
    echo "$PASSWD" | sudo -S dnf -y install libXt
    echo "$PASSWD" | sudo -S dnf -y install libXt-devel
    echo "$PASSWD" | sudo -S dnf -y install libxml2
    echo "$PASSWD" | sudo -S dnf -y install libxml2-devel
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff-devel
    echo "$PASSWD" | sudo -S dnf -y install libtiff
    echo "$PASSWD" | sudo -S dnf -y install libtiff-devel
    echo "$PASSWD" | sudo -S dnf -y install m4
    echo "$PASSWD" | sudo -S dnf -y install nfs-utils
    echo "$PASSWD" | sudo -S dnf -y install perl
    echo "$PASSWD" | sudo -S dnf -y install 'perl(XML::LibXML)'
    echo "$PASSWD" | sudo -S dnf -y install pkgconfig
    echo "$PASSWD" | sudo -S dnf -y install pixman
    echo "$PASSWD" | sudo -S dnf -y install pixman-devel
    echo "$PASSWD" | sudo -S dnf -y install python3
    echo "$PASSWD" | sudo -S dnf -y install python3-devel
    echo "$PASSWD" | sudo -S dnf -y install tcsh
    echo "$PASSWD" | sudo -S dnf -y install time
    echo "$PASSWD" | sudo -S dnf -y install unzip
    echo "$PASSWD" | sudo -S dnf -y install wget

    echo "$PASSWD" | sudo -S dnf -y install java
    echo "$PASSWD" | sudo -S dnf -y install java-devel

    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk

    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk

    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade
    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_CMAQ
    export WRF_FOLDER=$HOME/WRF_CMAQ
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://www.cmascenter.org/ioapi/download/ioapi-3.2.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=mpifort
    export MPIF77=mpifort
    export MPIF90=mpifort
    export MPICC=mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    echo $CFLAGS

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    echo $CFLAGS
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    echo " "

    # ----------------------------------------------------------------------
    # I/O API | CMAQ Data Interfaces
    # Compile the I/O API components required by the CMAQ workflow.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    mkdir ioapi
    cd ioapi
    env -u LD_LIBRARY_PATH tar -xzf "${WRF_FOLDER}"/Downloads/ioapi-3.2.tar.gz

    # set gnu version
    export BIN=Linux2_x86_64gfort10
    export CPLMODE=nocpl
    mkdir $BIN

    # Link netcdf and grib lib folders to ioapi
    ln -sf "${WRF_FOLDER}"/Libs/NETCDF/lib/* "${WRF_FOLDER}"/Downloads/ioapi/$BIN
    ln -sf "${WRF_FOLDER}"/Libs/grib2/lib/* "${WRF_FOLDER}"/Downloads/ioapi/$BIN

    # copy makefiles from ioapi directory to source makefile
    # cp "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makefile.nocpl "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makefile
    # cp "${WRF_FOLDER}"/Downloads/ioapi/m3tools/Makefile.nocpl "${WRF_FOLDER}"/Downloads/ioapi/m3tools/Makefile
    cp "${WRF_FOLDER}"/Downloads/ioapi/Makefile.template "${WRF_FOLDER}"/Downloads/ioapi/Makefile

    # Add proper sed statements needed for gfortran
    sed -i '193s|-lnetcdff -lnetcdf| -lnetcdff -lnetcdf -lhdf5hl_fortran -lhdf5_fortran -lhdf5_hl -lhdf5 -ljpeg -lm -lz -lcurl|g' "${WRF_FOLDER}"/Downloads/ioapi/Makefile
    sed -i '210s|${IODIR}/Makefile ${TOOLDIR}/Makefile| |g' "${WRF_FOLDER}"/Downloads/ioapi/Makefile

    # Remove openmnp flags from Makefile
    sed -i '30s/ -fopenmp//g' "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makeinclude.$BIN
    sed -i '31s/ -fopenmp//g' "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makeinclude.$BIN

    # Fix GCC compatibility: declare exit() from stdlib.h
    sed -i '/#include "parms3.h"/a #include <stdlib.h>' \
      "${WRF_FOLDER}"/Downloads/ioapi/ioapi/sortic.c

    # Build IOAPI
    make configure 2>&1 | tee configure.log
    make -j 1 2>&1 | tee make.log

    # If statement to check that libioapi.a & m3xtract exist

    cd "${WRF_FOLDER}"/Downloads/ioapi/$BIN
    n=$(ls -lrt libioapi.a | wc -l)
    m=$(ls -rlt m3xtract | wc -l)
    if ((($n == 1) && ($m == 1))); then
      echo "All expected files created."

    else
      echo "Missing one or more expected files. Exiting the script."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
    echo " "

    mv "${WRF_FOLDER}"/Downloads/ioapi/$BIN "${WRF_FOLDER}"/Downloads/ioapi/Linux2_x86_64gfort
    export BIN=Linux2_x86_64gfort
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WRF-CMAQ | Source Download and Compilation
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  git clone -b main https://github.com/USEPA/CMAQ.git #clone CMAQ github to WRF_CMAQ Main Folder

  cd CMAQ
  cp bldit_project.csh bldit_project.csh.old # Create backup of build project script

  # Set path to where CMAQ will be built
  sed -i '19s|/home/username/path|"${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}|g' "${WRF_FOLDER}"/Downloads/CMAQ/bldit_project.csh
  # Build CMAQ Project
  ./bldit_project.csh

  cd "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}

  cp config_cmaq.csh config_cmaq.csh.old # Create backup of configure script

  # Sed statements to configure the Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}
  sed -i 's|netcdf_root_gcc|"${WRF_FOLDER}"/Libs/NETCDF|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|ioapi_root_gcc|"${WRF_FOLDER}"/Downloads/ioapi|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i '148s|WRF_ARCH|WRF_ARCH 34|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh

  # sed statements for paths in configure file
  sed -i 's|ioapi_inc_gcc|"${WRF_FOLDER}"/Downloads/ioapi/$BIN|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|ioapi_lib_gcc|"${WRF_FOLDER}"/Downloads/ioapi/$BIN|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdf_lib_gcc |"${WRF_FOLDER}"/Libs/NETCDF/lib|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdf_inc_gcc|"${WRF_FOLDER}"/Libs/NETCDF/include|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdff_lib_gcc|"${WRF_FOLDER}"/Libs/NETCDF/lib|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdff_inc_gcc|"${WRF_FOLDER}"/Libs/NETCDF/include|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|mpi_incl_gcc|"${WRF_FOLDER}"/Libs/MPICH|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|mpi_lib_gcc|"${WRF_FOLDER}"/Libs/MPICH|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh

  # compile the Chemistry Transport Model (CCTM) preprocess

  cd "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts

  cp bldit_cctm.csh bldit_cctm.csh.old # make a back up copy of .csh script

  # Sed statements for configuration
  sed -i 's|make_options = "-j" |make_options = "-j 1" |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh  # set multicore to half of available cpus
  sed -i '84s|#set|set|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh                                   # build two way
  sed -i 's|WRF_VRSN = v4.4.1|WRF_VRSN = v${WRF_VERSION}|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh # change wrf version from 4.4 to ${WRF_Version}

  sed -i '442s| if ( $? != 0 ) then| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i '443s|    set shaID   = "not_a_repo"| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i '444s| endif| |g' "${WRF_FOLDER}"/Downloads/CMAQ//Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  sed -i '814s|  if ($? == 0) then| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh #remove if statment for git_check
  sed -i '816s|  endif| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  sed -i 's|git clone --branch|git clone --recurse-submodules --branch|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i 's|compile em_real|compile -j 1 em_real|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  # Remove Intel-specific compiler flags from the CMAQ build generator.
  # This prevents bldmake from adding them to GNU WRF-CMAQ builds.

  sed -i \
    's|add_flags  = -fno-alias -mp1 -fp-model source -ftz |add_flags  = |g' \
    "${WRF_FOLDER}/Downloads/CMAQ/UTIL/bldmake/src/bldmake.f"

  # Build WRF-CMAQ
  ./bldit_cctm.csh gcc 2>&1 | tee bldit.cctm.twoway.gcc.log

  # Move built folder to top level directory

  mkdir "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  mv "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/BLD_WRFv${WRF_VERSION}_CCTM_v55_gcc/* "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files. Exiting the script."
    read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi
  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files. Exiting the script."
    read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-CMAQ | RHL | GNU (legacy GCC)
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$RHL_64bit_GNU" = "2" ] && [ "$CMAQ_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo "old version of GNU detected"
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install RHL-release-scl -y
    echo $PASSWD | sudo -S yum clean all
    echo $PASSWD | sudo -S yum remove devtoolset-11*
    echo $PASSWD | sudo -S yum install devtoolset-11
    echo $PASSWD | sudo -S yum install devtoolset-11-\* -y
    echo $PASSWD | sudo -S yum -y update
    echo $PASSWD | sudo -S yum -y upgrade

    source /opt/rh/devtoolset-11/enable
    gcc --version
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
    echo "$PASSWD" | sudo -S dnf -y install bzip2-devel
    echo "$PASSWD" | sudo -S dnf -y install cairo-devel
    echo "$PASSWD" | sudo -S dnf -y install cmake
    echo "$PASSWD" | sudo -S dnf -y install cpp
    echo "$PASSWD" | sudo -S dnf -y install curl
    echo "$PASSWD" | sudo -S dnf -y install curl-devel
    echo "$PASSWD" | sudo -S dnf -y install flex
    echo "$PASSWD" | sudo -S dnf -y install flex-devel
    echo "$PASSWD" | sudo -S dnf -y install fontconfig
    echo "$PASSWD" | sudo -S dnf -y install fontconfig-devel
    echo "$PASSWD" | sudo -S dnf -y install gcc
    echo "$PASSWD" | sudo -S dnf -y install gcc-c++
    echo "$PASSWD" | sudo -S dnf -y install gcc-gfortran
    echo "$PASSWD" | sudo -S dnf -y install git
    echo "$PASSWD" | sudo -S dnf -y install ksh
    echo "$PASSWD" | sudo -S dnf -y install libjpeg
    echo "$PASSWD" | sudo -S dnf -y install libjpeg-devel
    echo "$PASSWD" | sudo -S dnf -y install libstdc++
    echo "$PASSWD" | sudo -S dnf -y install libstdc++-devel
    echo "$PASSWD" | sudo -S dnf -y install libX11
    echo "$PASSWD" | sudo -S dnf -y install libX11-devel
    echo "$PASSWD" | sudo -S dnf -y install libXaw
    echo "$PASSWD" | sudo -S dnf -y install libXaw-devel
    echo "$PASSWD" | sudo -S dnf -y install libXext-devel
    echo "$PASSWD" | sudo -S dnf -y install libXmu
    echo "$PASSWD" | sudo -S dnf -y install libXmu-devel
    echo "$PASSWD" | sudo -S dnf -y install libXrender
    echo "$PASSWD" | sudo -S dnf -y install libXrender-devel
    echo "$PASSWD" | sudo -S dnf -y install libXt
    echo "$PASSWD" | sudo -S dnf -y install libXt-devel
    echo "$PASSWD" | sudo -S dnf -y install libxml2
    echo "$PASSWD" | sudo -S dnf -y install libxml2-devel
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff-devel
    echo "$PASSWD" | sudo -S dnf -y install libtiff
    echo "$PASSWD" | sudo -S dnf -y install libtiff-devel
    echo "$PASSWD" | sudo -S dnf -y install m4
    echo "$PASSWD" | sudo -S dnf -y install nfs-utils
    echo "$PASSWD" | sudo -S dnf -y install perl
    echo "$PASSWD" | sudo -S dnf -y install 'perl(XML::LibXML)'
    echo "$PASSWD" | sudo -S dnf -y install pkgconfig
    echo "$PASSWD" | sudo -S dnf -y install pixman
    echo "$PASSWD" | sudo -S dnf -y install pixman-devel
    echo "$PASSWD" | sudo -S dnf -y install python3
    echo "$PASSWD" | sudo -S dnf -y install python3-devel
    echo "$PASSWD" | sudo -S dnf -y install tcsh
    echo "$PASSWD" | sudo -S dnf -y install time
    echo "$PASSWD" | sudo -S dnf -y install unzip
    echo "$PASSWD" | sudo -S dnf -y install wget

    echo "$PASSWD" | sudo -S dnf -y install java
    echo "$PASSWD" | sudo -S dnf -y install java-devel

    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk

    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk

    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade source /opt/rh/devtoolset-11/enable
    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_CMAQ
    export WRF_FOLDER=$HOME/WRF_CMAQ
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://www.cmascenter.org/ioapi/download/ioapi-3.2.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=mpifort
    export MPIF77=mpifort
    export MPIF90=mpifort
    export MPICC=mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    echo $CFLAGS

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    echo $CFLAGS
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make -j 2 check

    echo " "

    # ----------------------------------------------------------------------
    # I/O API | CMAQ Data Interfaces
    # Compile the I/O API components required by the CMAQ workflow.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    mkdir ioapi
    cd ioapi
    env -u LD_LIBRARY_PATH tar -xzf "${WRF_FOLDER}"/Downloads/ioapi-3.2.tar.gz

    # set gnu version
    export BIN=Linux2_x86_64gfort10
    export CPLMODE=nocpl
    mkdir $BIN

    # Link netcdf and grib lib folders to ioapi
    ln -sf "${WRF_FOLDER}"/Libs/NETCDF/lib/* "${WRF_FOLDER}"/Downloads/ioapi/$BIN
    ln -sf "${WRF_FOLDER}"/Libs/grib2/lib/* "${WRF_FOLDER}"/Downloads/ioapi/$BIN

    # copy makefiles from ioapi directory to source makefile
    # cp "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makefile.nocpl "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makefile
    # cp "${WRF_FOLDER}"/Downloads/ioapi/m3tools/Makefile.nocpl "${WRF_FOLDER}"/Downloads/ioapi/m3tools/Makefile
    cp "${WRF_FOLDER}"/Downloads/ioapi/Makefile.template "${WRF_FOLDER}"/Downloads/ioapi/Makefile

    # Add proper sed statements needed for gfortran
    sed -i '193s|-lnetcdff -lnetcdf| -lnetcdff -lnetcdf -lhdf5hl_fortran -lhdf5_fortran -lhdf5_hl -lhdf5 -ljpeg -lm -lz -lcurl|g' "${WRF_FOLDER}"/Downloads/ioapi/Makefile
    sed -i '210s|${IODIR}/Makefile ${TOOLDIR}/Makefile| |g' "${WRF_FOLDER}"/Downloads/ioapi/Makefile

    # Remove openmnp flags from Makefile
    sed -i '30s/ -fopenmp//g' "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makeinclude.$BIN
    sed -i '31s/ -fopenmp//g' "${WRF_FOLDER}"/Downloads/ioapi/ioapi/Makeinclude.$BIN

    # Fix GCC compatibility: declare exit() from stdlib.h
    sed -i '/#include "parms3.h"/a #include <stdlib.h>' \
      "${WRF_FOLDER}"/Downloads/ioapi/ioapi/sortic.c

    # Build IOAPI
    make configure 2>&1 | tee configure.log
    make -j 1 2>&1 | tee make.log

    # If statement to check that libioapi.a & m3xtract exist

    cd "${WRF_FOLDER}"/Downloads/ioapi/$BIN
    n=$(ls -lrt libioapi.a | wc -l)
    m=$(ls -rlt m3xtract | wc -l)
    if ((($n == 1) && ($m == 1))); then
      echo "All expected files created."

    else
      echo "Missing one or more expected files. Exiting the script."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
    echo " "

    mv "${WRF_FOLDER}"/Downloads/ioapi/$BIN "${WRF_FOLDER}"/Downloads/ioapi/Linux2_x86_64gfort
    export BIN=Linux2_x86_64gfort
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WRF-CMAQ | Source Download and Compilation
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  git clone -b main https://github.com/USEPA/CMAQ.git #clone CMAQ github to WRF_CMAQ Main Folder

  cd CMAQ
  cp bldit_project.csh bldit_project.csh.old # Create backup of build project script

  # Set path to where CMAQ will be built
  sed -i '19s|/home/username/path|"${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}|g' "${WRF_FOLDER}"/Downloads/CMAQ/bldit_project.csh
  # Build CMAQ Project
  ./bldit_project.csh

  cd "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}

  cp config_cmaq.csh config_cmaq.csh.old # Create backup of configure script

  # Sed statements to configure the Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}
  sed -i 's|netcdf_root_gcc|"${WRF_FOLDER}"/Libs/NETCDF|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|ioapi_root_gcc|"${WRF_FOLDER}"/Downloads/ioapi|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i '148s|WRF_ARCH|WRF_ARCH 34|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh

  # sed statements for paths in configure file
  sed -i 's|ioapi_inc_gcc|"${WRF_FOLDER}"/Downloads/ioapi/$BIN|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|ioapi_lib_gcc|"${WRF_FOLDER}"/Downloads/ioapi/$BIN|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdf_lib_gcc |"${WRF_FOLDER}"/Libs/NETCDF/lib|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdf_inc_gcc|"${WRF_FOLDER}"/Libs/NETCDF/include|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdff_lib_gcc|"${WRF_FOLDER}"/Libs/NETCDF/lib|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|netcdff_inc_gcc|"${WRF_FOLDER}"/Libs/NETCDF/include|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|mpi_incl_gcc|"${WRF_FOLDER}"/Libs/MPICH|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh
  sed -i 's|mpi_lib_gcc|"${WRF_FOLDER}"/Libs/MPICH|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/config_cmaq.csh

  # compile the Chemistry Transport Model (CCTM) preprocess

  cd "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts

  cp bldit_cctm.csh bldit_cctm.csh.old # make a back up copy of .csh script

  # Sed statements for configuration
  sed -i 's|make_options = "-j" |make_options = "-j 1" |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh  # set multicore to half of available cpus
  sed -i '84s|#set|set|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh                                   # build two way
  sed -i 's|WRF_VRSN = v4.4.1|WRF_VRSN = v${WRF_VERSION}|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh # change wrf version from 4.4 to ${WRF_Version}

  sed -i '442s| if ( $? != 0 ) then| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i '443s|    set shaID   = "not_a_repo"| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i '444s| endif| |g' "${WRF_FOLDER}"/Downloads/CMAQ//Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  sed -i '814s|  if ($? == 0) then| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh #remove if statment for git_check
  sed -i '816s|  endif| |g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  sed -i 's|git clone --branch|git clone --recurse-submodules --branch|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh
  sed -i 's|compile em_real|compile -j 1 em_real|g' "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/bldit_cctm.csh

  # Remove Intel-specific compiler flags from the CMAQ build generator.
  # This prevents bldmake from adding them to GNU WRF-CMAQ builds.

  sed -i \
    's|add_flags  = -fno-alias -mp1 -fp-model source -ftz |add_flags  = |g' \
    "${WRF_FOLDER}/Downloads/CMAQ/UTIL/bldmake/src/bldmake.f"

  # Build WRF-CMAQ
  ./bldit_cctm.csh gcc 2>&1 | tee bldit.cctm.twoway.gcc.log

  # Move built folder to top level directory

  mkdir "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  mv "${WRF_FOLDER}"/Downloads/CMAQ/Build_WRFv${WRF_VERSION}-CMAQv${CMAQ_VERSION}/CCTM/scripts/BLD_WRFv${WRF_VERSION}_CCTM_v55_gcc/* "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}_CMAQv${CMAQ_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files. Exiting the script."
    read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi
  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files. Exiting the script."
    read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-SFIRE | GNU, Model-Specific Scientific Libraries
# Build an isolated GNU scientific-library stack for the fire-atmosphere
# model; shared-library YAML reuse is not supported.
# WRF_SFIRE installation with parallel process.
# Download and install required library and data files for WRF_SFIRE.
# Tested in Ubuntu 22.04 & 24.04, Rocky Linux 9 & macOS Ventura 64bit
# Built in 64-bit system
# GNU compilers only in WRF-MOSIT v2.0.0.
# Tested with current available libraries on 03/01/2025
# If newer libraries exist edit script paths for changes
# Estimated Run Time ~ 30 - 60 Minutes with 10mb/s downloadspeed.
# Special thanks to:
# Youtube's meteoadriatic, GitHub user jamal919.
# University of Manchester's  Doug L
# University of Tunis El Manar's Hosni
# GSL's Jordan S.
# NCAR's Mary B., Christine W., & Carl D.
# DTC's Julie P., Tara J., George M., & John H.
# UCAR's Katelyn F., Jim B., Jordan P., Kevin M.,
# University of Colorado Denver's Jan M.
################################################################################

################################################################################
# WRF-SFIRE | Ubuntu/Debian | GNU | x86_64
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$Ubuntu_64bit_GNU" = "1" ] && [ "$SFIRE_PICK" = "1" ] && [ "$aarch64" != "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
    echo "$PASSWD" | sudo -S apt -y install default-jdk
    echo "$PASSWD" | sudo -S apt -y install default-jre
    echo "$PASSWD" | sudo -S apt -y install flex
    echo "$PASSWD" | sudo -S apt -y install freeglut3-dev
    echo "$PASSWD" | sudo -S apt -y install libfl-dev
    echo "$PASSWD" | sudo -S apt -y install g++
    echo "$PASSWD" | sudo -S apt -y install gawk
    echo "$PASSWD" | sudo -S apt -y install gcc
    echo "$PASSWD" | sudo -S apt -y install gettext
    echo "$PASSWD" | sudo -S apt -y install gfortran
    echo "$PASSWD" | sudo -S apt -y install git
    echo "$PASSWD" | sudo -S apt -y install ksh
    echo "$PASSWD" | sudo -S apt -y install libcurl4-gnutls-dev
    echo "$PASSWD" | sudo -S apt -y install libjpeg-dev
    echo "$PASSWD" | sudo -S apt -y install libncurses6
    echo "$PASSWD" | sudo -S apt -y install libncursesw5-dev
    echo "$PASSWD" | sudo -S apt -y install libpixman-1-dev
    echo "$PASSWD" | sudo -S apt -y install libpng-dev
    echo "$PASSWD" | sudo -S apt -y install libtool
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16-dev
    echo "$PASSWD" | sudo -S apt -y install libxml-libxml-perl
    echo "$PASSWD" | sudo -S apt -y install m4
    echo "$PASSWD" | sudo -S apt -y install make
    echo "$PASSWD" | sudo -S apt -y install ncview
    echo "$PASSWD" | sudo -S apt -y install pipenv
    echo "$PASSWD" | sudo -S apt -y install pkg-config
    echo "$PASSWD" | sudo -S apt -y install python3
    echo "$PASSWD" | sudo -S apt -y install python3-dev
    echo "$PASSWD" | sudo -S apt -y install python3-pip
    echo "$PASSWD" | sudo -S apt -y install python3-dateutil
    echo "$PASSWD" | sudo -S apt -y install tcsh
    echo "$PASSWD" | sudo -S apt -y install unzip
    echo "$PASSWD" | sudo -S apt -y install xauth
    echo "$PASSWD" | sudo -S apt -y install xorg
    echo "$PASSWD" | sudo -S apt -y install time
    echo "$PASSWD" | sudo -S apt -y install ghostscript
    echo "$PASSWD" | sudo -S apt -y install less
    echo "$PASSWD" | sudo -S apt -y install libbz2-dev
    echo "$PASSWD" | sudo -S apt -y install libc6-dev
    echo "$PASSWD" | sudo -S apt -y install libffi-dev
    echo "$PASSWD" | sudo -S apt -y install libgdbm-dev
    echo "$PASSWD" | sudo -S apt -y install libopenblas-dev
    echo "$PASSWD" | sudo -S apt -y install libreadline-dev
    echo "$PASSWD" | sudo -S apt -y install libssl-dev
    echo "$PASSWD" | sudo -S apt -y install libtiff-dev
    echo "$PASSWD" | sudo -S apt -y install libgeotiff-dev
    echo "$PASSWD" | sudo -S apt -y install tk-dev
    echo "$PASSWD" | sudo -S apt -y install vim
    echo "$PASSWD" | sudo -S apt -y install wget

    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_SFIRE
    export WRF_FOLDER=$HOME/WRF_SFIRE
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://github.com/openwfm/convert_geotiff/releases/download/v0.1/convert_geotiff-0.1.0.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/bin/gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/bin/gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/bin/g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/
    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/
    ./configure --prefix=$DIR/grib2
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Geospatial Utilities | GeoTIFF Conversion
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf convert_geotiff-0.1.0.tar.gz
    cd convert_geotiff-0.1.0

    # GCC 15+ defaults to C23, which conflicts with the legacy bool typedef.
    # Compile convert_geotiff using GNU11 for compatibility with GCC 15+.
    CFLAGS="${CFLAGS} -std=gnu11"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --exec-prefix=$DIR/grib2 --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Version 2.2.1 64-bit Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH

    echo " "
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    echo $PASSWD | sudo -S apt -y install grads

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # Installing Miniconda3 to WRF-Hydro directory and updating libraries
  # ----------------------------------------------------------------------

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Fire-Atmosphere Model Compilation
  # Compile the WRF-SFIRE atmosphere and fire components using the
  # model-specific build steps.
  # WRF-SFIRE
  # Cloned from openwfm
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  # WRF-SFIRE comes from its own upstream source tree and needs its
  # own fresh scientific-library stack, separate from WRF-ARW.
  git clone https://github.com/openwfm/WRF-SFIRE.git

  cd "${WRF_FOLDER}"/WRF-SFIRE/
  ./clean -a # Clean old configuration files

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo 1
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  sed -i \
    '/^CFLAGS_LOCAL *=/ s/=/= -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int /' \
    configure.wrf

  sed -i \
    '/^CC_TOOLS *=/c\CC_TOOLS        =      $(SCC) -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int' \
    configure.wrf

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe 2> /dev/null | wc -l)
  if (($n == 5)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 5)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  cd "${WRF_FOLDER}"/WRF-SFIRE

  # Remove existing symbolic links before compiling em_fire.
  find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

  # Compile the fire-specific WRF executable, in addition to em_real.
  ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
  if (($n == 2)); then
    echo "All expected WRF-SFIRE fire executables created."
    read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected WRF-SFIRE fire executables."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/

    find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 2)); then
      echo "All expected WRF-SFIRE fire executables created."
      read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-SFIRE

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v4.2
  # Downloaded from git tagged releases
  # Cloned from openwfm
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  git clone https://github.com/openwfm/WPS.git

  cd "${WRF_FOLDER}"/WPS
  ./clean -a

  cd "${WRF_FOLDER}"/WPS
  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    FFLAGS=$FFLAGS echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    FFLAGS=$FFLAGS ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi

  # sed statements for issue with GNUv10+

  if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
    sed -i '70s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
    sed -i '71s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
  fi

  ./compile 2>&1 | tee compile.wps.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"

    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-SFIRE | Ubuntu/Debian | GNU | ARM64
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$Ubuntu_64bit_GNU" = "1" ] && [ "$SFIRE_PICK" = "1" ] && [ "$aarch64" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
    echo "$PASSWD" | sudo -S apt -y install default-jdk
    echo "$PASSWD" | sudo -S apt -y install default-jre
    echo "$PASSWD" | sudo -S apt -y install flex
    echo "$PASSWD" | sudo -S apt -y install freeglut3-dev
    echo "$PASSWD" | sudo -S apt -y install libfl-dev
    echo "$PASSWD" | sudo -S apt -y install g++
    echo "$PASSWD" | sudo -S apt -y install gawk
    echo "$PASSWD" | sudo -S apt -y install gcc
    echo "$PASSWD" | sudo -S apt -y install gettext
    echo "$PASSWD" | sudo -S apt -y install gfortran
    echo "$PASSWD" | sudo -S apt -y install git
    echo "$PASSWD" | sudo -S apt -y install ksh
    echo "$PASSWD" | sudo -S apt -y install libcurl4-gnutls-dev
    echo "$PASSWD" | sudo -S apt -y install libjpeg-dev
    echo "$PASSWD" | sudo -S apt -y install libncurses6
    echo "$PASSWD" | sudo -S apt -y install libncursesw5-dev
    echo "$PASSWD" | sudo -S apt -y install libpixman-1-dev
    echo "$PASSWD" | sudo -S apt -y install libpng-dev
    echo "$PASSWD" | sudo -S apt -y install libtool
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16-dev
    echo "$PASSWD" | sudo -S apt -y install libxml-libxml-perl
    echo "$PASSWD" | sudo -S apt -y install m4
    echo "$PASSWD" | sudo -S apt -y install make
    echo "$PASSWD" | sudo -S apt -y install ncview
    echo "$PASSWD" | sudo -S apt -y install pipenv
    echo "$PASSWD" | sudo -S apt -y install pkg-config
    echo "$PASSWD" | sudo -S apt -y install python3
    echo "$PASSWD" | sudo -S apt -y install python3-dev
    echo "$PASSWD" | sudo -S apt -y install python3-pip
    echo "$PASSWD" | sudo -S apt -y install python3-dateutil
    echo "$PASSWD" | sudo -S apt -y install tcsh
    echo "$PASSWD" | sudo -S apt -y install unzip
    echo "$PASSWD" | sudo -S apt -y install xauth
    echo "$PASSWD" | sudo -S apt -y install xorg
    echo "$PASSWD" | sudo -S apt -y install time
    echo "$PASSWD" | sudo -S apt -y install ghostscript
    echo "$PASSWD" | sudo -S apt -y install less
    echo "$PASSWD" | sudo -S apt -y install libbz2-dev
    echo "$PASSWD" | sudo -S apt -y install libc6-dev
    echo "$PASSWD" | sudo -S apt -y install libffi-dev
    echo "$PASSWD" | sudo -S apt -y install libgdbm-dev
    echo "$PASSWD" | sudo -S apt -y install libopenblas-dev
    echo "$PASSWD" | sudo -S apt -y install libreadline-dev
    echo "$PASSWD" | sudo -S apt -y install libssl-dev
    echo "$PASSWD" | sudo -S apt -y install libtiff-dev
    echo "$PASSWD" | sudo -S apt -y install libgeotiff-dev
    echo "$PASSWD" | sudo -S apt -y install tk-dev
    echo "$PASSWD" | sudo -S apt -y install vim
    echo "$PASSWD" | sudo -S apt -y install wget

    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_SFIRE
    export WRF_FOLDER=$HOME/WRF_SFIRE
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://github.com/openwfm/convert_geotiff/releases/download/v0.1/convert_geotiff-0.1.0.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/bin/gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/bin/gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/bin/g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/
    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/
    ./configure --prefix=$DIR/grib2
    F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --build=aarch64-unknown-linux-gnu --host=aarch64-unknown-linux-gnu --prefix="$DIR/grib2" 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Geospatial Utilities | GeoTIFF Conversion
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf convert_geotiff-0.1.0.tar.gz
    cd convert_geotiff-0.1.0

    # GCC 15+ defaults to C23, which conflicts with the legacy bool typedef.
    # Compile convert_geotiff using GNU11 for compatibility with GCC 15+.
    CFLAGS="${CFLAGS} -std=gnu11"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --exec-prefix=$DIR/grib2 --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 32bit of Linux
  # ----------------------------------------------------------------------
  # if [[ $GRADS_PICK -eq 1 ]]; then
  # cd "${WRF_FOLDER}"/Downloads
  # env -u LD_LIBRARY_PATH tar -xzf cd "${WRF_FOLDER}"/Downloads
  # wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
  # env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
  # cd "${WRF_FOLDER}"/
  # mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
  # cd GrADS/Contents
  # wget -c https://github.com/regisgrundig/SIMOP/blob/master/g2ctl.pl
  # chmod +x g2ctl.pl
  # wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-i686-glib2.5-linux-gnu.tar.gz
  # env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-i686-glib2.5-linux-gnu.tar.gz
  # cd wgrib2-v0.1.9.4/bin
  # mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
  # cd "${WRF_FOLDER}"/GrADS/Contents
  # rm wgrib2-v0.1.9.4-bin-i686-glib2.5-linux-gnu.tar.gz
  # rm -r wgrib2-v0.1.9.4

  # export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH

  # echo " "
  # fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    echo $PASSWD | sudo -S apt -y install grads

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # Installing Miniconda3 to WRF-Hydro directory and updating libraries
  # ----------------------------------------------------------------------

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  # conda create -n ncl_stable -c conda-forge ncl -y
  # conda activate ncl_stable

  # conda deactivate
  # conda deactivate
  # conda deactivate

  # echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  # source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  # conda create --name cdo_stable -y
  # conda activate cdo_stable
  # conda install -c conda-forge cdo -y
  # conda update --all -y
  # conda deactivate
  # conda deactivate
  # conda deactivate

  # echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Fire-Atmosphere Model Compilation
  # Compile the WRF-SFIRE atmosphere and fire components using the
  # model-specific build steps.
  # WRF-SFIRE
  # Cloned from openwfm
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  # WRF-SFIRE comes from its own upstream source tree and needs its
  # own fresh scientific-library stack, separate from WRF-ARW.
  git clone https://github.com/openwfm/WRF-SFIRE.git

  cd "${WRF_FOLDER}"/WRF-SFIRE/
  ./clean -a # Clean old configuration files

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo 1
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  sed -i \
    '/^CFLAGS_LOCAL *=/ s/=/= -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int /' \
    configure.wrf

  sed -i \
    '/^CC_TOOLS *=/c\CC_TOOLS        =      $(SCC) -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int' \
    configure.wrf

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe 2> /dev/null | wc -l)
  if (($n == 5)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 5)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  cd "${WRF_FOLDER}"/WRF-SFIRE

  # Remove existing symbolic links before compiling em_fire.
  find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

  # Compile the fire-specific WRF executable, in addition to em_real.
  ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
  if (($n == 2)); then
    echo "All expected WRF-SFIRE fire executables created."
    read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected WRF-SFIRE fire executables."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/

    find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 2)); then
      echo "All expected WRF-SFIRE fire executables created."
      read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-SFIRE

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v4.2
  # Downloaded from git tagged releases
  # Cloned from openwfm
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  git clone https://github.com/openwfm/WPS.git

  cd "${WRF_FOLDER}"/WPS
  ./clean -a

  cd "${WRF_FOLDER}"/WPS
  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    FFLAGS=$FFLAGS echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    FFLAGS=$FFLAGS ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi

  # sed statements for issue with GNUv10+

  if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
    sed -i '70s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
    sed -i '71s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
  fi

  ./compile 2>&1 | tee compile.wps.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"

    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-SFIRE | RHL | GNU
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$RHL_64bit_GNU" = "1" ] && [ "$SFIRE_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
    echo "$PASSWD" | sudo -S dnf -y install bzip2-devel
    echo "$PASSWD" | sudo -S dnf -y install cairo-devel
    echo "$PASSWD" | sudo -S dnf -y install cmake
    echo "$PASSWD" | sudo -S dnf -y install cpp
    echo "$PASSWD" | sudo -S dnf -y install curl
    echo "$PASSWD" | sudo -S dnf -y install curl-devel
    echo "$PASSWD" | sudo -S dnf -y install flex
    echo "$PASSWD" | sudo -S dnf -y install flex-devel
    echo "$PASSWD" | sudo -S dnf -y install fontconfig
    echo "$PASSWD" | sudo -S dnf -y install fontconfig-devel
    echo "$PASSWD" | sudo -S dnf -y install gcc
    echo "$PASSWD" | sudo -S dnf -y install gcc-c++
    echo "$PASSWD" | sudo -S dnf -y install gcc-gfortran
    echo "$PASSWD" | sudo -S dnf -y install git
    echo "$PASSWD" | sudo -S dnf -y install ksh
    echo "$PASSWD" | sudo -S dnf -y install libjpeg
    echo "$PASSWD" | sudo -S dnf -y install libjpeg-devel
    echo "$PASSWD" | sudo -S dnf -y install libstdc++
    echo "$PASSWD" | sudo -S dnf -y install libstdc++-devel
    echo "$PASSWD" | sudo -S dnf -y install libX11
    echo "$PASSWD" | sudo -S dnf -y install libX11-devel
    echo "$PASSWD" | sudo -S dnf -y install libXaw
    echo "$PASSWD" | sudo -S dnf -y install libXaw-devel
    echo "$PASSWD" | sudo -S dnf -y install libXext-devel
    echo "$PASSWD" | sudo -S dnf -y install libXmu
    echo "$PASSWD" | sudo -S dnf -y install libXmu-devel
    echo "$PASSWD" | sudo -S dnf -y install libXrender
    echo "$PASSWD" | sudo -S dnf -y install libXrender-devel
    echo "$PASSWD" | sudo -S dnf -y install libXt
    echo "$PASSWD" | sudo -S dnf -y install libXt-devel
    echo "$PASSWD" | sudo -S dnf -y install libxml2
    echo "$PASSWD" | sudo -S dnf -y install libxml2-devel
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff-devel
    echo "$PASSWD" | sudo -S dnf -y install libtiff
    echo "$PASSWD" | sudo -S dnf -y install libtiff-devel
    echo "$PASSWD" | sudo -S dnf -y install m4
    echo "$PASSWD" | sudo -S dnf -y install nfs-utils
    echo "$PASSWD" | sudo -S dnf -y install perl
    echo "$PASSWD" | sudo -S dnf -y install 'perl(XML::LibXML)'
    echo "$PASSWD" | sudo -S dnf -y install pkgconfig
    echo "$PASSWD" | sudo -S dnf -y install pixman
    echo "$PASSWD" | sudo -S dnf -y install pixman-devel
    echo "$PASSWD" | sudo -S dnf -y install python3
    echo "$PASSWD" | sudo -S dnf -y install python3-devel
    echo "$PASSWD" | sudo -S dnf -y install tcsh
    echo "$PASSWD" | sudo -S dnf -y install time
    echo "$PASSWD" | sudo -S dnf -y install unzip
    echo "$PASSWD" | sudo -S dnf -y install wget

    echo "$PASSWD" | sudo -S dnf -y install java
    echo "$PASSWD" | sudo -S dnf -y install java-devel

    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk

    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk

    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade
    echo " "

    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_SFIRE
    export WRF_FOLDER=$HOME/WRF_SFIRE
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://src.fedoraproject.org/repo/pkgs/jasper/jasper-$Jasper_Version.zip/a342b2b4495b3e1394e161eb5d85d754/jasper-$Jasper_Version.zip
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://github.com/openwfm/convert_geotiff/releases/download/v0.1/convert_geotiff-0.1.0.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(gcc -dumpversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(gfortran -dumpversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(g++ -dumpversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/
    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/
    ./configure --prefix=$DIR/grib2
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Geospatial Utilities | GeoTIFF Conversion
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf convert_geotiff-0.1.0.tar.gz
    cd convert_geotiff-0.1.0
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include -I/usr/include/libgeotiff"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -L/usr/lib/libgeotiff"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --exec-prefix=$DIR/grib2 --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Version 2.2.1 64-bit Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH

    echo " "
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c ftp://cola.gmu.edu/grads/2.2/grads-2.2.1-bin-RHL7.4-x86_64.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf grads-2.2.1-bin-RHL7.4-x86_64.tar.gz -C "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"/grads-2.2.1/bin
    chmod 775 *

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # Installing Miniconda3 to WRF-Hydro directory and updating libraries
  # ----------------------------------------------------------------------

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  echo " "

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Fire-Atmosphere Model Compilation
  # Compile the WRF-SFIRE atmosphere and fire components using the
  # model-specific build steps.
  # WRF-SFIRE
  # Cloned from openwfm
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  # WRF-SFIRE comes from its own upstream source tree and needs its
  # own fresh scientific-library stack, separate from WRF-ARW.
  git clone https://github.com/openwfm/WRF-SFIRE.git

  cd "${WRF_FOLDER}"/WRF-SFIRE/
  ./clean -a # Clean old configuration files

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo 1
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  sed -i \
    '/^CFLAGS_LOCAL *=/ s/=/= -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int /' \
    configure.wrf

  sed -i \
    '/^CC_TOOLS *=/c\CC_TOOLS        =      $(SCC) -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int' \
    configure.wrf

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe 2> /dev/null | wc -l)
  if (($n == 5)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 5)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  cd "${WRF_FOLDER}"/WRF-SFIRE

  # Remove existing symbolic links before compiling em_fire.
  find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

  # Compile the fire-specific WRF executable, in addition to em_real.
  ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
  if (($n == 2)); then
    echo "All expected WRF-SFIRE fire executables created."
    read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected WRF-SFIRE fire executables."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/

    find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 2)); then
      echo "All expected WRF-SFIRE fire executables created."
      read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-SFIRE

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v4.2
  # Downloaded from git tagged releases
  # Cloned from openwfm
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  git clone https://github.com/openwfm/WPS.git

  cd "${WRF_FOLDER}"/WPS
  ./clean -a

  cd "${WRF_FOLDER}"/WPS
  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    FFLAGS=$FFLAGS echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    FFLAGS=$FFLAGS ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi

  # sed statements for issue with GNUv10+

  if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
    sed -i '70s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
    sed -i '71s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
  fi

  ./compile 2>&1 | tee compile.wps.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"

    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-SFIRE | RHL | GNU (legacy GCC)
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$RHL_64bit_GNU" = "2" ] && [ "$SFIRE_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo "old version of GNU detected"
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install RHL-release-scl -y
    echo $PASSWD | sudo -S yum clean all
    echo $PASSWD | sudo -S yum remove devtoolset-11*
    echo $PASSWD | sudo -S yum install devtoolset-11
    echo $PASSWD | sudo -S yum install devtoolset-11-\* -y
    echo $PASSWD | sudo -S yum -y update
    echo $PASSWD | sudo -S yum -y upgrade

    source /opt/rh/devtoolset-11/enable
    gcc --version
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
    echo "$PASSWD" | sudo -S dnf -y install bzip2-devel
    echo "$PASSWD" | sudo -S dnf -y install cairo-devel
    echo "$PASSWD" | sudo -S dnf -y install cmake
    echo "$PASSWD" | sudo -S dnf -y install cpp
    echo "$PASSWD" | sudo -S dnf -y install curl
    echo "$PASSWD" | sudo -S dnf -y install curl-devel
    echo "$PASSWD" | sudo -S dnf -y install flex
    echo "$PASSWD" | sudo -S dnf -y install flex-devel
    echo "$PASSWD" | sudo -S dnf -y install fontconfig
    echo "$PASSWD" | sudo -S dnf -y install fontconfig-devel
    echo "$PASSWD" | sudo -S dnf -y install gcc
    echo "$PASSWD" | sudo -S dnf -y install gcc-c++
    echo "$PASSWD" | sudo -S dnf -y install gcc-gfortran
    echo "$PASSWD" | sudo -S dnf -y install git
    echo "$PASSWD" | sudo -S dnf -y install ksh
    echo "$PASSWD" | sudo -S dnf -y install libjpeg
    echo "$PASSWD" | sudo -S dnf -y install libjpeg-devel
    echo "$PASSWD" | sudo -S dnf -y install libstdc++
    echo "$PASSWD" | sudo -S dnf -y install libstdc++-devel
    echo "$PASSWD" | sudo -S dnf -y install libX11
    echo "$PASSWD" | sudo -S dnf -y install libX11-devel
    echo "$PASSWD" | sudo -S dnf -y install libXaw
    echo "$PASSWD" | sudo -S dnf -y install libXaw-devel
    echo "$PASSWD" | sudo -S dnf -y install libXext-devel
    echo "$PASSWD" | sudo -S dnf -y install libXmu
    echo "$PASSWD" | sudo -S dnf -y install libXmu-devel
    echo "$PASSWD" | sudo -S dnf -y install libXrender
    echo "$PASSWD" | sudo -S dnf -y install libXrender-devel
    echo "$PASSWD" | sudo -S dnf -y install libXt
    echo "$PASSWD" | sudo -S dnf -y install libXt-devel
    echo "$PASSWD" | sudo -S dnf -y install libxml2
    echo "$PASSWD" | sudo -S dnf -y install libxml2-devel
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff-devel
    echo "$PASSWD" | sudo -S dnf -y install libtiff
    echo "$PASSWD" | sudo -S dnf -y install libtiff-devel
    echo "$PASSWD" | sudo -S dnf -y install m4
    echo "$PASSWD" | sudo -S dnf -y install nfs-utils
    echo "$PASSWD" | sudo -S dnf -y install perl
    echo "$PASSWD" | sudo -S dnf -y install 'perl(XML::LibXML)'
    echo "$PASSWD" | sudo -S dnf -y install pkgconfig
    echo "$PASSWD" | sudo -S dnf -y install pixman
    echo "$PASSWD" | sudo -S dnf -y install pixman-devel
    echo "$PASSWD" | sudo -S dnf -y install python3
    echo "$PASSWD" | sudo -S dnf -y install python3-devel
    echo "$PASSWD" | sudo -S dnf -y install tcsh
    echo "$PASSWD" | sudo -S dnf -y install time
    echo "$PASSWD" | sudo -S dnf -y install unzip
    echo "$PASSWD" | sudo -S dnf -y install wget

    echo "$PASSWD" | sudo -S dnf -y install java
    echo "$PASSWD" | sudo -S dnf -y install java-devel

    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk

    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk

    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade source /opt/rh/devtoolset-11/enable
    echo " "

    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_SFIRE
    export WRF_FOLDER=$HOME/WRF_SFIRE
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://src.fedoraproject.org/repo/pkgs/jasper/jasper-$Jasper_Version.zip/a342b2b4495b3e1394e161eb5d85d754/jasper-$Jasper_Version.zip
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://github.com/openwfm/convert_geotiff/releases/download/v0.1/convert_geotiff-0.1.0.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(gcc -dumpversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(gfortran -dumpversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(g++ -dumpversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/
    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Geospatial Utilities | GeoTIFF Conversion
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf convert_geotiff-0.1.0.tar.gz
    cd convert_geotiff-0.1.0
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include -I/usr/include/libgeotiff"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -L/usr/lib/libgeotiff"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --exec-prefix=$DIR/grib2 --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Version 2.2.1 64-bit Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH

    echo " "
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c ftp://cola.gmu.edu/grads/2.2/grads-2.2.1-bin-RHL7.4-x86_64.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf grads-2.2.1-bin-RHL7.4-x86_64.tar.gz -C "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"/grads-2.2.1/bin
    chmod 775 *

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # Installing Miniconda3 to WRF-Hydro directory and updating libraries
  # ----------------------------------------------------------------------

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  echo " "

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Fire-Atmosphere Model Compilation
  # Compile the WRF-SFIRE atmosphere and fire components using the
  # model-specific build steps.
  # WRF-SFIRE
  # Cloned from openwfm
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  # WRF-SFIRE comes from its own upstream source tree and needs its
  # own fresh scientific-library stack, separate from WRF-ARW.
  git clone https://github.com/openwfm/WRF-SFIRE.git

  cd "${WRF_FOLDER}"/WRF-SFIRE/
  ./clean -a # Clean old configuration files

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo 1
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  sed -i \
    '/^CFLAGS_LOCAL *=/ s/=/= -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int /' \
    configure.wrf

  sed -i \
    '/^CC_TOOLS *=/c\CC_TOOLS        =      $(SCC) -std=gnu89 -Wno-error=implicit-function-declaration -Wno-error=implicit-int' \
    configure.wrf

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe 2> /dev/null | wc -l)
  if (($n == 5)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./real.exe ./ndown.exe ./tc.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 5)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  cd "${WRF_FOLDER}"/WRF-SFIRE

  # Remove existing symbolic links before compiling em_fire.
  find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

  # Compile the fire-specific WRF executable, in addition to em_real.
  ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-SFIRE/main
  n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
  if (($n == 2)); then
    echo "All expected WRF-SFIRE fire executables created."
    read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected WRF-SFIRE fire executables."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-SFIRE/

    find test/em_fire/two_fires test/em_fire/rain -maxdepth 1 -type l -delete

    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire2.log
    cd "${WRF_FOLDER}"/WRF-SFIRE/main
    n=$(ls ./wrf.exe ./ideal.exe 2> /dev/null | wc -l)
    if (($n == 2)); then
      echo "All expected WRF-SFIRE fire executables created."
      read -r -t 5 -p "Finished installing WRF-SFIRE. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-SFIRE

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v4.2
  # Downloaded from git tagged releases
  # Cloned from openwfm
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"
  git clone https://github.com/openwfm/WPS.git

  cd "${WRF_FOLDER}"/WPS
  ./clean -a

  cd "${WRF_FOLDER}"/WPS

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    FFLAGS=$FFLAGS echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    FFLAGS=$FFLAGS ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi

  # sed statements for issue with GNUv10+

  if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
    sed -i '70s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
    sed -i '71s/-frecord-marker=4/-frecord-marker=4  -fallow-argument-mismatch/g' "${WRF_FOLDER}"/WPS/configure.wps
  fi

  ./compile 2>&1 | tee compile.wps.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"

    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-SFIRE | macOS | GNU | Intel Mac
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$macos_64bit_GNU" = "1" ] && [ "$SFIRE_PICK" = "1" ] && [ "$MAC_CHIP" = "Intel" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # WRF installation with parallel process.
    # Download and install required library and data files for WRF.
    # Tested in macOS Ventura 13.4.1
    # Tested in 64-bit
    # Tested with current available libraries on 03/01/2025
    # If newer libraries exist edit script paths for changes
    # Estimated Run Time ~ 90 - 150 Minutes with 10mb/s downloadspeed.
    # Special thanks to  Youtube's meteoadriatic and GitHub user jamal919.

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------

    brew cleanup -s
    brew update
    outdated_packages=$(brew outdated --quiet)

    # List of packages to check/install
    packages=(
      "autoconf" "automake" "bison" "byacc" "cmake" "curl" "flex" "gcc@13"
      "gedit" "git" "gnu-sed" "ksh"
      "libtool" "libxml2" "m4" "make" "python@3.12" "tcsh" "wget"
      "xauth" "xorgproto" "xorgrgb" "xquartz"
    )

    for pkg in "${packages[@]}"; do
      if brew list "$pkg" &> /dev/null; then
        echo "$pkg is already installed."
        if [[ $outdated_packages == *"$pkg"* ]]; then
          echo "$pkg has a newer version available. Upgrading..."
          brew upgrade "$pkg"
        fi
      else
        echo "$pkg is not installed. Installing..."
        brew install "$pkg"
      fi
      sleep 1
    done

    export LD_LIBRARY_PATH=/usr/local/lib:$LD_LIBRARY_PATH
    export PATH=/usr/local/bin:$PATH
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------

    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_SFIRE
    export WRF_FOLDER=$HOME/WRF_SFIRE
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------
    export CPU_CORE=$(sysctl -n hw.ncpu) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))
    # 1/2 of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    # Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"
    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://github.com/openwfm/convert_geotiff/releases/download/v0.1/convert_geotiff-0.1.0.tar.gz
    echo " "

    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------

    # Symlink to avoid clang conflicts with compilers
    # Default gcc path: /usr/bin/gcc
    # Default homebrew path: /usr/local/bin

    # Find the highest version of GCC, G++, and GFortran in /usr/local/bin
    latest_gcc=gcc-13
    latest_gpp=g++-13
    latest_gfortran=gfortran-13

    # Display the chosen versions
    echo "Selected gcc version: $latest_gcc"
    echo "Selected g++ version: $latest_gpp"
    echo "Selected gfortran version: $latest_gfortran"

    # Check if GCC was found

    # Create or update the symbolic links for GCC, G++, and GFortran
    echo "Linking the latest GCC version: $latest_gcc"
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/$latest_gcc /usr/local/bin/gcc

    echo "Linking the latest G++ version: $latest_gpp"
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/$latest_gpp /usr/local/bin/g++

    echo "Linking the latest GFortran version: $latest_gfortran"
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/$latest_gfortran /usr/local/bin/gfortran

    echo "Updated symbolic links for GCC, G++, and GFortran."
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/python3.12 /usr/local/bin/python3

    # Export compiler environment variables
    export CC=/usr/local/bin/gcc-13
    export CXX=/usr/local/bin/g++-13
    export FC=/usr/local/bin/gfortran-13
    export F77=/usr/local/bin/gfortran-13
    export CFLAGS="-fPIC -fPIE -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-incompatible-pointer-types -Wall"

    echo " "

    # ----------------------------------------------------------------------
    # Compiler Configuration Complete
    # ----------------------------------------------------------------------

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/local/bin/$latest_gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/local/bin/$latest_gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/local/bin/$latest_gpp -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "

    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "

    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "

    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    # drop --disable-utils (not recognized)
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS="-std=gnu99 $CFLAGS" FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    # build only libraries
    make -j 2 2>&1 | tee make.log

    # install only libraries and headers
    make install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    read -r -t 3 -p

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Geospatial Utilities | GeoTIFF Conversion
    # ----------------------------------------------------------------------

    cd $WRF_FOLDER/Downloads
    env -u LD_LIBRARY_PATH tar -xzvf convert_geotiff-0.1.0.tar.gz
    cd convert_geotiff-0.1.0

    # Adjust CPP flags for Geo Tiff

    export TIFF_LIB=/usr/local/lib
    export TIFF_INC=/usr/local/include
    export GEOTIFF_LIB=/usr/local/lib
    export GEOTIFF_INC=/usr/local/include

    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include -I$GEOTIFF_INC -I$TIFF_INC"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib -L$GEOTIFF_LIB -L$TIFF_LIB"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS="-std=c11 $CFLAGS" FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure -exec-prefix=$DIR/grib2 --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # Changes flags back to netcdf only
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------
    mkdir -p "${WRF_FOLDER}"/Tests/Environment
    mkdir -p "${WRF_FOLDER}"/Tests/Compatibility

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility
    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 64bit of Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/macOS/opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg
    sudo -S installer -pkg opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg -target /Applications/OpenGrads <<< "$PASSWD"

  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    brew install grads

  fi

  # Installing Miniconda3 to WRF directory and updating libraries
  echo $PASSWD | sudo -S apt -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-MacOSX-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "

  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate
  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Fire-Atmosphere Model Compilation
  # Compile the WRF-SFIRE atmosphere and fire components using the
  # model-specific build steps.
  # WRF-SFIRE
  # Cloned from openwfm
  # Option 17 for gfortran, option 1 for basic nesting
  # Large file support enabled with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------

  cd "$WRF_FOLDER"
  # WRF-SFIRE comes from its own upstream source tree and needs its
  # own fresh scientific-library stack, separate from WRF-ARW.
  git clone https://github.com/openwfm/WRF-SFIRE.git

  cd "$WRF_FOLDER/WRF-SFIRE/"
  ./clean -a # Clean old configuration files

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 17
      echo 1
    ) | ./configure 2>&1 | tee configure.log
  else
    ./configure 2>&1 | tee configure.log # Option 17, nesting option 1
  fi

  sed -i'' -e '145s/-c/-c -fPIC -fPIE -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-incompatible-pointer-types -Wall/g' configure.wrf

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Compile Atmospheric Model
  # Configure and compile the WRF-SFIRE atmospheric executable.
  # ----------------------------------------------------------------------

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # ----------------------------------------------------------------------
  # Build Verification | Required Executables
  # Check all five WRF executables by name.
  # -f follows symbolic links, and -x checks executable permissions.
  # ----------------------------------------------------------------------

  cd "$WRF_FOLDER/WRF-SFIRE/main"

  n=0
  for exe in wrf.exe real.exe ndown.exe tc.exe ideal.exe; do
    if [ -f "$exe" ] && [ -x "$exe" ]; then
      n=$((n + 1))
    fi
  done

  if (($n == 5)); then
    echo "All five expected WRF-SFIRE executables created."
    read -r -t 5 -p "Finished compiling WRF-SFIRE em_real. Waiting 5 seconds ..."
  else
    echo "Missing one or more expected WRF-SFIRE executables."
    echo "Running compiler again."

    cd "$WRF_FOLDER/WRF-SFIRE/"
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log

    cd "$WRF_FOLDER/WRF-SFIRE/main"

    n=0
    for exe in wrf.exe real.exe ndown.exe tc.exe ideal.exe; do
      if [ -f "$exe" ] && [ -x "$exe" ]; then
        n=$((n + 1))
      fi
    done

    if (($n == 5)); then
      echo "All five expected WRF-SFIRE executables created."
      read -r -t 5 -p "Finished compiling WRF-SFIRE em_real. Waiting 5 seconds ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Compile Fire Model
  # Compile the fire component using the WRF-SFIRE source tree.
  # ----------------------------------------------------------------------

  read -r -t 3 -p "Preparing WRF-SFIRE em_fire compilation ..."

  cd "$WRF_FOLDER/WRF-SFIRE"

  # Compile the fire-specific WRF executable, in addition to em_real.
  ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire.log
  fire_compile_status=${PIPESTATUS[0]}

  # Verify the em_fire build result.
  # Existing em_real executables alone do not establish em_fire success.

  if [ "$fire_compile_status" -eq 0 ]; then
    echo "WRF-SFIRE em_fire compilation completed successfully."
  else
    echo "WRF-SFIRE em_fire compilation returned an error."
    echo "Running compiler again."

    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire2.log
    fire_compile_status=${PIPESTATUS[0]}

    if [ "$fire_compile_status" -eq 0 ]; then
      echo "WRF-SFIRE em_fire compilation completed successfully."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="$WRF_FOLDER/WRF-SFIRE"

  read -r -t 3 -p "Preparing WPS installation ..."

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from GitHub tagged releases
  # Option 19 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # ----------------------------------------------------------------------
  # Build Configuration
  # ----------------------------------------------------------------------

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 19 | ./configure 2>&1 | tee configure.log # Option 19
  else
    ./configure 2>&1 | tee configure.log # Option 19
  fi

  # ----------------------------------------------------------------------
  # WPS | Compilation
  # ----------------------------------------------------------------------

  ./compile 2>&1 | tee compile.wps.log

  # ----------------------------------------------------------------------
  # Build Verification | Required Executables
  # Check all three primary WPS executables by name.
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}

  n=0
  for exe in geogrid.exe ungrib.exe metgrid.exe; do
    if [ -f "$exe" ] && [ -x "$exe" ]; then
      n=$((n + 1))
    fi
  done

  if (($n == 3)); then
    echo "All three expected WPS executables created."
    read -r -t 5 -p "Finished installing WPS. Waiting 5 seconds ..."
  else
    echo "Missing one or more expected WPS executables."
    echo "Running compiler again."

    ./compile 2>&1 | tee compile.wps2.log

    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}

    n=0
    for exe in geogrid.exe ungrib.exe metgrid.exe; do
      if [ -f "$exe" ] && [ -x "$exe" ]; then
        n=$((n + 1))
      fi
    done

    if (($n == 3)); then
      echo "All three expected WPS executables created."
      read -r -t 5 -p "Finished installing WPS. Waiting 5 seconds ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-SFIRE | macOS | GNU | Apple Silicon
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$macos_64bit_GNU" = "1" ] && [ "$SFIRE_PICK" = "1" ] && [ "$MAC_CHIP" = "ARM" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # WRF installation with parallel process.
    # Download and install required library and data files for WRF.
    # Tested in macOS Ventura 13.4.1
    # Tested in 64-bit
    # Tested with current available libraries on 03/01/2025
    # If newer libraries exist edit script paths for changes
    # Estimated Run Time ~ 90 - 150 Minutes with 10mb/s downloadspeed.
    # Special thanks to  Youtube's meteoadriatic and GitHub user jamal919.

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------

    brew cleanup -s
    brew update
    outdated_packages=$(brew outdated --quiet)

    # List of packages to check/install
    packages=(
      "autoconf" "automake" "bison" "byacc" "cmake" "curl" "flex" "gcc@13"
      "gedit" "git" "gnu-sed" "ksh"
      "libtool" "libxml2" "m4" "make" "python@3.12" "tcsh" "wget"
      "xauth" "xorgproto" "xorgrgb" "xquartz"
    )

    for pkg in "${packages[@]}"; do
      if brew list "$pkg" &> /dev/null; then
        echo "$pkg is already installed."
        if [[ $outdated_packages == *"$pkg"* ]]; then
          echo "$pkg has a newer version available. Upgrading..."
          brew upgrade "$pkg"
        fi
      else
        echo "$pkg is not installed. Installing..."
        brew install "$pkg"
      fi
      sleep 1
    done

    export LD_LIBRARY_PATH=/usr/local/lib:$LD_LIBRARY_PATH
    export PATH=/usr/local/bin:$PATH
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------

    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF_SFIRE
    export WRF_FOLDER=$HOME/WRF_SFIRE
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------
    export CPU_CORE=$(sysctl -n hw.ncpu) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))
    # 1/2 of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    # Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"
    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz
    wget -c https://github.com/openwfm/convert_geotiff/releases/download/v0.1/convert_geotiff-0.1.0.tar.gz
    echo " "

    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------

    # Symlink to avoid clang conflicts with compilers
    # Default gcc path: /usr/bin/gcc
    # Default homebrew path: /usr/local/bin

    # Unlink any existing Homebrew compiler symlinks
    echo $PASSWD | sudo -S unlink /opt/homebrew/bin/gfortran
    echo $PASSWD | sudo -S unlink /opt/homebrew/bin/gcc
    echo $PASSWD | sudo -S unlink /opt/homebrew/bin/g++

    # Source the bashrc to ensure environment variables are loaded
    source ~/.bashrc

    # Check current versions of gcc, g++, and gfortran (these should show "command not found" if unlinked)
    gcc --version
    g++ --version
    gfortran --version

    # Navigate to the Homebrew binaries directory
    cd /opt/homebrew/bin

    # Find the latest version of GCC, G++, and GFortran
    latest_gcc=gcc-13
    latest_gpp=g++-13
    latest_gfortran=gfortran-13

    # Check if the latest versions were found and link them
    echo "Linking the latest GCC version: $latest_gcc"
    echo $PASSWD | sudo -S ln -sf $latest_gcc gcc
    echo "Linking the latest G++ version: $latest_gpp"
    echo $PASSWD | sudo -S ln -sf $latest_gpp g++
    echo "Linking the latest GFortran version: $latest_gfortran"
    echo $PASSWD | sudo -S ln -sf $latest_gfortran gfortran

    # Return to the home directory
    cd

    # Source bashrc and bash_profile to reload the environment settings
    source ~/.bashrc
    source ~/.bash_profile

    # Check if the versions were successfully updated
    gcc --version
    g++ --version
    gfortran --version

    # Export compiler environment variables
    export CC=/usr/local/bin/gcc-13
    export CXX=/usr/local/bin/g++-13
    export FC=/usr/local/bin/gfortran-13
    export F77=/usr/local/bin/gfortran-13
    export CFLAGS="-fPIC -fPIE -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-incompatible-pointer-types -Wall"

    echo " "

    # ----------------------------------------------------------------------
    # Compiler Configuration Complete
    # ----------------------------------------------------------------------

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/local/bin/$latest_gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/local/bin/$latest_gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/local/bin/$latest_gpp -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "

    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "

    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "

    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    # drop --disable-utils (not recognized)
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS="-std=gnu99 $CFLAGS" FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    # build only libraries
    make -j 2 2>&1 | tee make.log

    # install only libraries and headers
    make install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    read -r -t 3 -p

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Geospatial Utilities | GeoTIFF Conversion
    # ----------------------------------------------------------------------

    cd $WRF_FOLDER/Downloads
    env -u LD_LIBRARY_PATH tar -xzvf convert_geotiff-0.1.0.tar.gz
    cd convert_geotiff-0.1.0

    # Adjust CPP flags for Geo Tiff

    export TIFF_LIB=/usr/local/lib
    export TIFF_INC=/usr/local/include
    export GEOTIFF_LIB=/usr/local/lib
    export GEOTIFF_INC=/usr/local/include

    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include -I$GEOTIFF_INC -I$TIFF_INC"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib -L$GEOTIFF_LIB -L$TIFF_LIB"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS="-std=c11 $CFLAGS" FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure -exec-prefix=$DIR/grib2 --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # Changes flags back to netcdf only
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------
    mkdir -p "${WRF_FOLDER}"/Tests/Environment
    mkdir -p "${WRF_FOLDER}"/Tests/Compatibility

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility
    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 64bit of Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/macOS/opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg
    sudo -S installer -pkg opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg -target /Applications/OpenGrads <<< "$PASSWD"

  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    brew install grads

  fi

  # Installing Miniconda3 to WRF directory and updating libraries
  echo $PASSWD | sudo -S apt -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-MacOSX-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "

  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate
  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Fire-Atmosphere Model Compilation
  # Compile the WRF-SFIRE atmosphere and fire components using the
  # model-specific build steps.
  # WRF-SFIRE
  # Cloned from openwfm
  # Option 17 for gfortran, option 1 for basic nesting
  # Large file support enabled with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------

  cd "$WRF_FOLDER"
  # WRF-SFIRE comes from its own upstream source tree and needs its
  # own fresh scientific-library stack, separate from WRF-ARW.
  git clone https://github.com/openwfm/WRF-SFIRE.git

  cd "$WRF_FOLDER/WRF-SFIRE/"
  ./clean -a # Clean old configuration files

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 17
      echo 1
    ) | ./configure 2>&1 | tee configure.log
  else
    ./configure 2>&1 | tee configure.log # Option 17, nesting option 1
  fi

  sed -i'' -e '145s/-c/-c -fPIC -fPIE -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-incompatible-pointer-types -Wall/g' configure.wrf

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Compile Atmospheric Model
  # Configure and compile the WRF-SFIRE atmospheric executable.
  # ----------------------------------------------------------------------

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # ----------------------------------------------------------------------
  # Build Verification | Required Executables
  # Check all five WRF executables by name.
  # -f follows symbolic links, and -x checks executable permissions.
  # ----------------------------------------------------------------------

  cd "$WRF_FOLDER/WRF-SFIRE/main"

  n=0
  for exe in wrf.exe real.exe ndown.exe tc.exe ideal.exe; do
    if [ -f "$exe" ] && [ -x "$exe" ]; then
      n=$((n + 1))
    fi
  done

  if (($n == 5)); then
    echo "All five expected WRF-SFIRE executables created."
    read -r -t 5 -p "Finished compiling WRF-SFIRE em_real. Waiting 5 seconds ..."
  else
    echo "Missing one or more expected WRF-SFIRE executables."
    echo "Running compiler again."

    cd "$WRF_FOLDER/WRF-SFIRE/"
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log

    cd "$WRF_FOLDER/WRF-SFIRE/main"

    n=0
    for exe in wrf.exe real.exe ndown.exe tc.exe ideal.exe; do
      if [ -f "$exe" ] && [ -x "$exe" ]; then
        n=$((n + 1))
      fi
    done

    if (($n == 5)); then
      echo "All five expected WRF-SFIRE executables created."
      read -r -t 5 -p "Finished compiling WRF-SFIRE em_real. Waiting 5 seconds ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WRF-SFIRE | Compile Fire Model
  # Compile the fire component using the WRF-SFIRE source tree.
  # ----------------------------------------------------------------------

  read -r -t 3 -p "Preparing WRF-SFIRE em_fire compilation ..."

  cd "$WRF_FOLDER/WRF-SFIRE"

  # Compile the fire-specific WRF executable, in addition to em_real.
  ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire.log
  fire_compile_status=${PIPESTATUS[0]}

  # Verify the em_fire build result.
  # Existing em_real executables alone do not establish em_fire success.

  if [ "$fire_compile_status" -eq 0 ]; then
    echo "WRF-SFIRE em_fire compilation completed successfully."
  else
    echo "WRF-SFIRE em_fire compilation returned an error."
    echo "Running compiler again."

    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_fire 2>&1 | tee compile.wrfsfire2.log
    fire_compile_status=${PIPESTATUS[0]}

    if [ "$fire_compile_status" -eq 0 ]; then
      echo "WRF-SFIRE em_fire compilation completed successfully."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="$WRF_FOLDER/WRF-SFIRE"

  read -r -t 3 -p "Preparing WPS installation ..."

  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from GitHub tagged releases
  # Option 19 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # ----------------------------------------------------------------------
  # Build Configuration
  # ----------------------------------------------------------------------

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 19 | ./configure 2>&1 | tee configure.log # Option 19
  else
    ./configure 2>&1 | tee configure.log # Option 19
  fi

  # ----------------------------------------------------------------------
  # WPS | Compilation
  # ----------------------------------------------------------------------

  ./compile 2>&1 | tee compile.wps.log

  # ----------------------------------------------------------------------
  # Build Verification | Required Executables
  # Check all three primary WPS executables by name.
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}

  n=0
  for exe in geogrid.exe ungrib.exe metgrid.exe; do
    if [ -f "$exe" ] && [ -x "$exe" ]; then
      n=$((n + 1))
    fi
  done

  if (($n == 3)); then
    echo "All three expected WPS executables created."
    read -r -t 5 -p "Finished installing WPS. Waiting 5 seconds ..."
  else
    echo "Missing one or more expected WPS executables."
    echo "Running compiler again."

    ./compile 2>&1 | tee compile.wps2.log

    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}

    n=0
    for exe in geogrid.exe ungrib.exe metgrid.exe; do
      if [ -f "$exe" ] && [ -x "$exe" ]; then
        n=$((n + 1))
      fi
    done

    if (($n == 3)); then
      echo "All three expected WPS executables created."
      read -r -t 5 -p "Finished installing WPS. Waiting 5 seconds ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-Hydro Standalone | Independent Hydrology Model
# Build the standalone hydrologic model; compatible shared-library YAML reuse
# is supported.
# WRFHYDRO Standalone installation with parallel process.
# Download and install required library and data files for WRFHYDRO.
# Tested in Ubuntu 22.04 & 24.04, Rocky Linux 9 & macOS Ventura 64bit
# Built in 64-bit system
# Built with Intel or GNU compilers
# Tested with current available libraries on 03/01/2025
# If newer libraries exist edit script paths for changes
# Estimated Run Time ~ 30 - 60 Minutes with 10mb/s downloadspeed.
# Special thanks to:
# Youtube's meteoadriatic, GitHub user jamal919.
# University of Manchester's  Doug L
# University of Tunis El Manar's Hosni
# GSL's Jordan S.
# NCAR's Mary B., Christine W., & Carl D.
# DTC's Julie P., Tara J., George M., & John H.
# UCAR's Katelyn F., Jim B., Jordan P., Kevin M.,
################################################################################

################################################################################
# WRF-Hydro Standalone | Ubuntu/Debian | GNU | x86_64
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$Ubuntu_64bit_GNU" = "1" ] && [ "$WRFHYDRO_STANDALONE_PICK" = "1" ] && [ "$aarch64" != "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
    echo "$PASSWD" | sudo -S apt -y install default-jdk
    echo "$PASSWD" | sudo -S apt -y install default-jre
    echo "$PASSWD" | sudo -S apt -y install flex
    echo "$PASSWD" | sudo -S apt -y install freeglut3-dev
    echo "$PASSWD" | sudo -S apt -y install libfl-dev
    echo "$PASSWD" | sudo -S apt -y install g++
    echo "$PASSWD" | sudo -S apt -y install gawk
    echo "$PASSWD" | sudo -S apt -y install gcc
    echo "$PASSWD" | sudo -S apt -y install gettext
    echo "$PASSWD" | sudo -S apt -y install gfortran
    echo "$PASSWD" | sudo -S apt -y install git
    echo "$PASSWD" | sudo -S apt -y install ksh
    echo "$PASSWD" | sudo -S apt -y install libcurl4-gnutls-dev
    echo "$PASSWD" | sudo -S apt -y install libjpeg-dev
    echo "$PASSWD" | sudo -S apt -y install libncurses6
    echo "$PASSWD" | sudo -S apt -y install libncursesw5-dev
    echo "$PASSWD" | sudo -S apt -y install libpixman-1-dev
    echo "$PASSWD" | sudo -S apt -y install libpng-dev
    echo "$PASSWD" | sudo -S apt -y install libtool
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16-dev
    echo "$PASSWD" | sudo -S apt -y install libxml-libxml-perl
    echo "$PASSWD" | sudo -S apt -y install m4
    echo "$PASSWD" | sudo -S apt -y install make
    echo "$PASSWD" | sudo -S apt -y install ncview
    echo "$PASSWD" | sudo -S apt -y install pipenv
    echo "$PASSWD" | sudo -S apt -y install pkg-config
    echo "$PASSWD" | sudo -S apt -y install python3
    echo "$PASSWD" | sudo -S apt -y install python3-dev
    echo "$PASSWD" | sudo -S apt -y install python3-pip
    echo "$PASSWD" | sudo -S apt -y install python3-dateutil
    echo "$PASSWD" | sudo -S apt -y install tcsh
    echo "$PASSWD" | sudo -S apt -y install unzip
    echo "$PASSWD" | sudo -S apt -y install xauth
    echo "$PASSWD" | sudo -S apt -y install xorg
    echo "$PASSWD" | sudo -S apt -y install time
    echo "$PASSWD" | sudo -S apt -y install ghostscript
    echo "$PASSWD" | sudo -S apt -y install less
    echo "$PASSWD" | sudo -S apt -y install libbz2-dev
    echo "$PASSWD" | sudo -S apt -y install libc6-dev
    echo "$PASSWD" | sudo -S apt -y install libffi-dev
    echo "$PASSWD" | sudo -S apt -y install libgdbm-dev
    echo "$PASSWD" | sudo -S apt -y install libopenblas-dev
    echo "$PASSWD" | sudo -S apt -y install libreadline-dev
    echo "$PASSWD" | sudo -S apt -y install libssl-dev
    echo "$PASSWD" | sudo -S apt -y install libtiff-dev
    echo "$PASSWD" | sudo -S apt -y install libgeotiff-dev
    echo "$PASSWD" | sudo -S apt -y install tk-dev
    echo "$PASSWD" | sudo -S apt -y install vim
    echo "$PASSWD" | sudo -S apt -y install wget

    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )
    mkdir $HOME/WRFHYDRO_STANDALONE
    export WRF_FOLDER=$HOME/WRFHYDRO_STANDALONE
    export DIR="${WRF_FOLDER}"/Libs
    cd "${WRF_FOLDER}"/
    mkdir Downloads
    mkdir "${WRF_FOLDER}"/Hydro-Basecode
    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/bin/gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/bin/gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/bin/g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------
    mkdir -p "${WRF_FOLDER}"/Tests/Environment
    mkdir -p "${WRF_FOLDER}"/Tests/Compatibility

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility
    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WRF-Hydro v5.4.0 | Build and Configuration
  # Version 5.4.0
  # Standalone mode
  # GNU
  # ----------------------------------------------------------------------

  # Set up NETCDF environment variables
  export NETCDF_INC="$DIR/NETCDF/include"
  export NETCDF_LIB="$DIR/NETCDF/lib"

  # Create directories for Hydro Basecode and navigate to it
  mkdir -p "${WRF_FOLDER}/Hydro-Basecode"
  cd "${WRF_FOLDER}/Hydro-Basecode"

  # Clone the WRF-Hydro repository and set up the build
  git clone https://github.com/NCAR/wrf_hydro_nwm_public.git
  cd wrf_hydro_nwm_public
  mkdir -p build
  cd build

  # Run CMake configuration for WRF-Hydro with specified options
  cmake .. \
    -DSPATIAL_SOIL=1 \
    -DWRF_HYDRO=1 \
    -DWRFIO_NCD_LARGE_FILE_SUPPORT=1 \
    -DCMAKE_Fortran_COMPILER=gfortran

  # Compile using specified CPU settings
  make -j "$CPU_QUARTER_EVEN" 2>&1 | tee make.log

  # Check if the necessary executable files were created
  # Check if the necessary executable files were created
  cd "${WRF_FOLDER}/Hydro-Basecode/wrf_hydro_nwm_public/build/Run"

  # List of expected executable files
  expected_execs=("wrf_hydro.exe" "wrf_hydro_NoahMP")

  # Function to check for missing executables
  check_missing_execs() {
    missing=0
    for exe in "${expected_execs[@]}"; do
      if [[ ! -f "$exe" ]]; then
        echo "Missing: $exe"
        missing=1
      fi
    done
    return $missing
  }

  # Function to rerun compilation
  rebuild_and_check() {
    echo "Missing one or more expected files. Running compiler again..."
    cd "${WRF_FOLDER}/Hydro-Basecode/wrf_hydro_nwm_public/build"
    make -j "$CPU_QUARTER_EVEN" 2>&1 | tee make2.log
    cd "${WRF_FOLDER}/Hydro-Basecode/wrf_hydro_nwm_public/build/Run"
  }

  # Initial check
  check_missing_execs
  if (($? == 0)); then
    echo "All expected executable files are present."
  else
    rebuild_and_check
    check_missing_execs
    if (($? != 0)); then
      echo "Missing one or more expected files even after recompilation."
      read -r -p "Please contact script authors for assistance. Press 'Enter' to exit the script."
      exit 1
    else
      echo "All expected files created after re-compiling."
    fi
  fi
  # Finish the script with a pause
  read -r -t 5 -p "Finished installing WRF Hydro Basecode. Waiting for 5 seconds..."
  # ----------------------------------------------------------------------
  # WRF-Hydro | Compilation Verification
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/

  # Download test case for WRF HYDRO and move to NWM
  cd "${WRF_FOLDER}"/Downloads
  wget -c https://github.com/NCAR/wrf_hydro_nwm_public/releases/download/v${HYDRO_CROTON_TEST_CASE}/croton_NY_training_example_v${HYDRO_CROTON_TEST_CASE_MINOR}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf croton_NY_training_example_v${HYDRO_CROTON_TEST_CASE_MINOR}.tar.gz
  mv example_case "${WRF_FOLDER}"/Hydro-Basecode

  # Copy the *.TBL files to the example configuration directory:
  cp "${WRF_FOLDER}"/Hydro-Basecode/wrf_hydro_nwm_public/build/Run/*.TBL "${WRF_FOLDER}"/Hydro-Basecode/example_case/NWM

  # Copy the wrf_hydro file:
  cp "${WRF_FOLDER}"/Hydro-Basecode/wrf_hydro_nwm_public/build/Run/wrf_hydro "${WRF_FOLDER}"/Hydro-Basecode/example_case/NWM

  # From the example_case/Gridded directory, create a symlink:
  ln -s "${WRF_FOLDER}"/Hydro-Basecode/example_case/FORCING "${WRF_FOLDER}"/Hydro-Basecode/example_case/NWM

  # Move to Gridded Folder
  cd "${WRF_FOLDER}"/Hydro-Basecode/example_case/NWM

  # Run Wrf hydro
  mpirun -np $CPU_QUARTER_EVEN ./wrf_hydro

  echo "Checking HYDRO_RST files..."
  ls -lah HYDRO_RST.*_DOMAIN1 2> /dev/null || echo "No HYDRO_RST files found."

  all_good=true
  for file in HYDRO_RST.*_DOMAIN1; do
    if [ ! -s "$file" ]; then
      echo "File $file is empty or missing!"
      all_good=false
    fi
  done

  if [ "$all_good" = true ]; then
    echo "HYDRO_RST files exist and have data — wrf_hydro.exe successful."
  else
    echo "One or more HYDRO_RST files are missing or empty."
    echo "Please check your model run."
    exit 1
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WRF-Hydro | Output Validation
  # ----------------------------------------------------------------------

  # Installing Miniconda3 to WRF directory and updating libraries
  echo $PASSWD | sudo -S apt -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  if [ "$Ubuntu_32bit_GNU" = "1" ]; then
    wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86.sh -O $Miniconda_Install_DIR/miniconda.sh
  else
    wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  fi

  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # Installation Finalization | Cleanup and Summary
  # Report completion for the current installation path and perform any final
  # cleanup.
  # ----------------------------------------------------------------------
  echo "WRF HYDRO Standalone sucessfully configured and compiled"
  read -r -t 5 -p "Congratulations! You've successfully installed all required files to run the Weather Research Forecast Model HYDRO verison 5.2."

  # ----------------------------------------------------------------------
  # Environment Exports | PATH and LD_LIBRARY_PATH
  # ----------------------------------------------------------------------
  cd $HOME

fi

################################################################################
# WRF-Hydro Standalone | Ubuntu/Debian | GNU | ARM64
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$Ubuntu_64bit_GNU" = "1" ] && [ "$WRFHYDRO_STANDALONE_PICK" = "1" ] && [ "$aarch64" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
