    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
