  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # In the namelist.input, the following settings support pNetCDF by setting
  # value to 11:
  # io_form_boundary
  # io_form_history
  # io_form_auxinput2
  # io_form_auxhist2
  # Note that you need set nocolons = .true. in the section &time_control of
  # namelist.input
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a
  sed -i '192s/x86_64/x86_64 aarch64/g' "${WRF_FOLDER}"/WPS-${WPS_VERSION}/arch/configure.defaults

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi
  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 4 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 2 | ./configure wrfplus 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi
  echo " "
  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus.log
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS

  echo " "

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 18 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 2 | ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi
  echo " "
  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee compile.wrf4dvar.log
  echo " "

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-ARW | Ubuntu/Debian | Intel oneAPI
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$Ubuntu_64bit_Intel" = "1" ] && [ "$WRF_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------

    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    # download the key to system keyring; this and the following echo command are
    # needed in order to install the Intel compilers
    wget -O- https://apt.repos.intel.com/intel-gpg-keys/GPG-PUB-KEY-INTEL-SW-PRODUCTS.PUB \
      | gpg --dearmor | sudo tee /usr/share/keyrings/oneapi-archive-keyring.gpg > /dev/null

    # add signed entry to apt sources and configure the APT client to use Intel repository:
    echo "deb [signed-by=/usr/share/keyrings/oneapi-archive-keyring.gpg] https://apt.repos.intel.com/oneapi all main" | sudo tee /etc/apt/sources.list.d/oneAPI.list

    # this update should get the Intel package info from the Intel repository
    echo $PASSWD | sudo -S apt -y update

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
    echo "$PASSWD" | sudo -S apt -y install default-jdk
    echo "$PASSWD" | sudo -S apt -y install default-jre
    echo "$PASSWD" | sudo -S apt -y install flex
    echo "$PASSWD" | sudo -S apt -y install freeglut3-dev
    echo "$PASSWD" | sudo -S apt -y install libfl-dev
    echo "$PASSWD" | sudo -S apt -y install g++
    echo "$PASSWD" | sudo -S apt -y install gawk
    echo "$PASSWD" | sudo -S apt -y install gcc
    echo "$PASSWD" | sudo -S apt -y install gettext
    echo "$PASSWD" | sudo -S apt -y install gfortran
    echo "$PASSWD" | sudo -S apt -y install git
    echo "$PASSWD" | sudo -S apt -y install ksh
    echo "$PASSWD" | sudo -S apt -y install libcurl4-gnutls-dev
    echo "$PASSWD" | sudo -S apt -y install libjpeg-dev
    echo "$PASSWD" | sudo -S apt -y install libncurses6
    echo "$PASSWD" | sudo -S apt -y install libncursesw5-dev
    echo "$PASSWD" | sudo -S apt -y install libpixman-1-dev
    echo "$PASSWD" | sudo -S apt -y install libpng-dev
    echo "$PASSWD" | sudo -S apt -y install libtool
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16-dev
    echo "$PASSWD" | sudo -S apt -y install libxml-libxml-perl
    echo "$PASSWD" | sudo -S apt -y install m4
    echo "$PASSWD" | sudo -S apt -y install make
    echo "$PASSWD" | sudo -S apt -y install ncview
    echo "$PASSWD" | sudo -S apt -y install pipenv
    echo "$PASSWD" | sudo -S apt -y install pkg-config
    echo "$PASSWD" | sudo -S apt -y install python3
    echo "$PASSWD" | sudo -S apt -y install python3-dev
    echo "$PASSWD" | sudo -S apt -y install python3-pip
    echo "$PASSWD" | sudo -S apt -y install python3-dateutil
    echo "$PASSWD" | sudo -S apt -y install tcsh
    echo "$PASSWD" | sudo -S apt -y install unzip
    echo "$PASSWD" | sudo -S apt -y install xauth
    echo "$PASSWD" | sudo -S apt -y install xorg
    echo "$PASSWD" | sudo -S apt -y install time
    echo "$PASSWD" | sudo -S apt -y install ghostscript
    echo "$PASSWD" | sudo -S apt -y install less
    echo "$PASSWD" | sudo -S apt -y install libbz2-dev
    echo "$PASSWD" | sudo -S apt -y install libc6-dev
    echo "$PASSWD" | sudo -S apt -y install libffi-dev
    echo "$PASSWD" | sudo -S apt -y install libgdbm-dev
    echo "$PASSWD" | sudo -S apt -y install libopenblas-dev
    echo "$PASSWD" | sudo -S apt -y install libreadline-dev
    echo "$PASSWD" | sudo -S apt -y install libssl-dev
    echo "$PASSWD" | sudo -S apt -y install libtiff-dev
    echo "$PASSWD" | sudo -S apt -y install libgeotiff-dev
    echo "$PASSWD" | sudo -S apt -y install tk-dev
    echo "$PASSWD" | sudo -S apt -y install vim
    echo "$PASSWD" | sudo -S apt -y install wget

    # install the Intel compilers
    echo $PASSWD | sudo -S apt -y install intel-oneapi-toolkit

    echo $PASSWD | sudo -S apt -y install intel-oneapi-python
    /opt/intel/oneapi/intelpython/python3.12/bin/python3 -m pip install python-dateutil

    echo $PASSWD | sudo -S apt -y update

    # Fix any broken installations
    echo $PASSWD | sudo -S apt --fix-broken install

    # make sure some critical packages have been installed
    which cmake pkg-config make gcc g++ gfortran

    # add the Intel compiler file paths to various environment variables
    source /opt/intel/oneapi/setvars.sh --force

    # some of the libraries we install below need one or more of these variables

    export CC=icx
    export CXX=icpx
    export FC=ifx
    export F77=ifx
    export F90=ifx
    export MPIFC=mpiifx
    export MPIF77=mpiifx
    export MPIF90=mpiifx
    export MPICC=mpiicx
    export MPICXX=mpiicpx
    export CFLAGS="-fPIC -fPIE -O3 -Wno-incompatible-pointer-types -Wno-implicit-function-declaration -Wno-unused-command-line-argument"
    export FFLAGS=""
    export FCFLAGS=""
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4)) # quarter of availble cores on system
    # Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))

    # If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
    if [ $CPU_CORE -le $CPU_6CORE ]; then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    # ----------------------------------------------------------------------
    # Installation Directories
    # makes necessary directories
    # ----------------------------------------------------------------------

    export HOME=$(
      cd ~ \
        && pwd
    )
    export WRF_FOLDER=$HOME/WRF_Intel
    export DIR="${WRF_FOLDER}"/Libs
    mkdir "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"
    mkdir Downloads

    mkdir Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # other libraries below need these variables to be set
    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 and Parallel I/O
    # Compile HDF5 with MPI support before building parallel NetCDF
    # interfaces.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # other libraries below need these variables to be set
    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/

    # these variables need to be set for the NetCDF-C install to work
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # other libraries below need these variables to be set
    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/

    # these variables need to be set for the NetCDF-Fortran install to work
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  if [ "${SYSTEMOS:-}" = "Linux" ] || [ "${SYSTEMOS:-}" = "RHL" ]; then
    if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
      # Register the just-tested shared libraries for future compatible
      # WRF-ARW, WRF-Chem, or WRF-Hydro installations.
      wrf_mosit_save_library_profile || echo "WARNING: library profile was not saved."
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 64bit of Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    echo $PASSWD | sudo -S apt -y install grads

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # ----------------------------------------------------------------------
  echo " "
  echo " "
  # Installing Miniconda3 to WRF directory and updating libraries

  echo $PASSWD | sudo -S apt -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  # Special Thanks to @_WaylonWalker for code development
  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # OBSGRID | Objective Analysis Utility
  # Compile obsgrid.exe; auxiliary plotting executables are optional.
  # OBSGRID
  # Downloaded from git tagged releases
  # Option #3
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/
  # OBSGRID provides objective analysis preprocessing.
  # The primary required result is obsgrid.exe; plot helpers are optional.
  git clone https://github.com/wrf-model/OBSGRID.git
  cd "${WRF_FOLDER}"/OBSGRID

  ./clean -a
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda activate ncl_stable

  export HOME=$(
    cd ~ \
      && pwd
  )
  export DIR="${WRF_FOLDER}"/Libs
  export NETCDF=$DIR/NETCDF

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for itnel and distribunted memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 for intel and distribunted memory
  fi

  sed -i '27s/-lnetcdf -lnetcdff/ -lnetcdff -lnetcdf/g' configure.oa

  sed -i '31s/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo -lfontconfig -lpixman-1 -lfreetype -lhdf5 -lhdf5_hl /g' configure.oa

  sed -i '38s/ifort/ifx/g' configure.oa
  sed -i '43s/gcc/icx/g' configure.oa
  sed -i '45s|/lib/cpp|ifx|g' configure.oa
  sed -i '46s|-I. -C -P -DDEC -traditional|-fpp -DDEC -I.|g' configure.oa

  # Patch .F90.o rule to use direct compile with Intel Fortran + fpp
  sed -i '/^\.F90\.o:/,/^\t\$(RM) \$\*\.f/ c\.F90.o:\n\t$(RM) $@ $*.mod\n\t$(FC) $(FFLAGS) -fpp $(CPPFLAGS) ${NETCDF_INC} -c $<' configure.oa

  echo " "
  ./compile 2>&1 | tee compile.obsgrid.log

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "
  # IF statement to check that all files were created.
  # Require obsgrid.exe itself; optional graphical helper programs
  # do not determine whether the main OBSGRID build succeeded.
  if [[ -x ./obsgrid.exe ]]; then
    echo "obsgrid.exe found."
    read -r -t 5 -p "Finished installing OBSGRID. I am going to wait for 5 seconds only ..."
  else
    echo "obsgrid.exe is missing. Attempting to compile again..."

    ./clean -a
    ./compile 2>&1 | tee compile.obsgrid.retry.log

    # Require obsgrid.exe itself; optional graphical helper programs
    # do not determine whether the main OBSGRID build succeeded.
    if [[ -x ./obsgrid.exe ]]; then
      echo "obsgrid.exe successfully created after recompilation."
      read -r -t 5 -p "Finished retrying OBSGRID compile. I am going to wait for 5 seconds only ..."
    else
      echo "Still missing obsgrid.exe after recompile. Exiting the script."
      read -r -p "Please contact script authors for assistance. Press 'Enter' to exit."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 78, option 1 for intel and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------

  source /opt/intel/oneapi/setvars.sh --force

  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 78
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #option 78 intel compiler with distributed memory option 1 for basic nesting
  fi

  # Need to remove mpich/GNU config calls to Intel config calls
  sed -i '136s|mpif90 -f90=$(SFC)|mpiifx|g' "${WRF_FOLDER}"/WRF-${WRF_VERSION}/configure.wrf
  sed -i '137s|mpicc -cc=$(SCC)|mpiicx|g' "${WRF_FOLDER}"/WRF-${WRF_VERSION}/configure.wrf

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 19 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 19 | ./configure 2>&1 | tee configure.log #Option 19 for intel and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 19 intel compiler with distributed memory
  fi

  sed -i '67s|mpif90|mpiifx|g' "${WRF_FOLDER}"/WPS-${WPS_VERSION}/configure.wps
  sed -i '68s|mpicc|mpiicx|g' "${WRF_FOLDER}"/WPS-${WPS_VERSION}/configure.wps

  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 40 for intel and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 40 | ./configure wrfplus 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  fi
  echo " "
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc

  sed -i '136s|mpif90 -f90=$(SFC)|mpiifx|g' "${WRF_FOLDER}"/WRFPLUS/configure.wrf
  sed -i '137s|mpicc -cc=$(SCC)|mpiicx|g' "${WRF_FOLDER}"/WRFPLUS/configure.wrf

  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile -j 2 wrfplus 2>&1 | tee wrfplus1.compile.log

  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS

  echo " "

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus2.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 40 for intel and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 40 | ./configure 4dvar 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  fi
  echo " "

  sed -i '136s|mpif90 -f90=$(SFC)|mpiifx|g' "${WRF_FOLDER}"/WRFDA/configure.wrf
  sed -i '137s|mpicc -cc=$(SCC)|mpiicx|g' "${WRF_FOLDER}"/WRFDA/configure.wrf

  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee wrfda.compile.log
  echo " "

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA-4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-ARW | macOS | GNU | Intel Mac
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$SYSTEMOS" = "MacOS" ] && [ "$macos_64bit_GNU" = "1" ] && [ "$WRF_PICK" = "1" ] && [ "$MAC_CHIP" = "Intel" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    brew cleanup -s
    brew update
    outdated_packages=$(brew outdated --quiet)

    # List of packages to check/install
    packages=(
      "autoconf" "automake" "bison" "byacc" "cmake" "curl" "flex" "gcc@13"
      "gedit" "git" "gnu-sed" "ksh"
      "libtool" "libxml2" "m4" "make" "python@3.12" "tcsh" "wget"
      "xauth" "xorgproto" "xorgrgb" "xquartz"
    )

    for pkg in "${packages[@]}"; do
      if brew list "$pkg" &> /dev/null; then
        echo "$pkg is already installed."
        if [[ $outdated_packages == *"$pkg"* ]]; then
          echo "$pkg has a newer version available. Upgrading..."
          brew upgrade "$pkg"
        fi
      else
        echo "$pkg is not installed. Installing..."
        brew install "$pkg"
      fi
      sleep 1
    done

    export LD_LIBRARY_PATH=/usr/local/lib:$LD_LIBRARY_PATH
    export PATH=/usr/local/bin:$PATH

    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------

    export HOME=$(
      cd ~ \
        && pwd
    )
    mkdir $HOME/WRF
    export WRF_FOLDER=$HOME/WRF
    cd "${WRF_FOLDER}"/
    mkdir Downloads

    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir -p Libs/grib2
    mkdir -p Libs/NETCDF
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------
    export CPU_CORE=$(sysctl -n hw.ncpu) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))
    # 1/2 of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    # Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"
    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "

    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------

    # Symlink to avoid clang conflicts with compilers
    # Default gcc path: /usr/bin/gcc
    # Default homebrew path: /usr/local/bin

    # Find the highest version of GCC, G++, and GFortran in /usr/local/bin
    latest_gcc=gcc-13
    latest_gpp=g++-13
    latest_gfortran=gfortran-13

    # Display the chosen versions
    echo "Selected gcc version: $latest_gcc"
    echo "Selected g++ version: $latest_gpp"
    echo "Selected gfortran version: $latest_gfortran"

    # Check if GCC was found

    # Create or update the symbolic links for GCC, G++, and GFortran
    echo "Linking the latest GCC version: $latest_gcc"
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/$latest_gcc /usr/local/bin/gcc

    echo "Linking the latest G++ version: $latest_gpp"
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/$latest_gpp /usr/local/bin/g++

    echo "Linking the latest GFortran version: $latest_gfortran"
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/$latest_gfortran /usr/local/bin/gfortran

    echo "Updated symbolic links for GCC, G++, and GFortran."
    echo $PASSWD | sudo -S ln -sf /usr/local/bin/python3.12 /usr/local/bin/python3

    # Export compiler environment variables
    export CC=/usr/local/bin/gcc-13
    export CXX=/usr/local/bin/g++-13
    export FC=/usr/local/bin/gfortran-13
    export F77=/usr/local/bin/gfortran-13
    export CFLAGS="-fPIC -fPIE -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-incompatible-pointer-types -Wall"

    echo " "

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/local/bin/$latest_gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/local/bin/$latest_gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/local/bin/$latest_gpp -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "

    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee install.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "

    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------
    mkdir -p "${WRF_FOLDER}"/Tests/Environment
    mkdir -p "${WRF_FOLDER}"/Tests/Compatibility

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility
    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 64bit of Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/macOS/opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg
    sudo -S installer -pkg opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg -target /Applications/OpenGrads <<< "$PASSWD"

  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    brew install grads

  fi

  # Installing Miniconda3 to WRF directory and updating libraries
  echo $PASSWD | sudo -S apt -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-MacOSX-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "

  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate
  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 17, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------

  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}

  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 17
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 17 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile em_real 2>&1 | tee compile.wrf.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 19 | ./configure 2>&1 | tee configure.log #Option 19 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 19 gfortran compiler with distributed memory
  fi

  ./compile 2>&1 | tee compile.wrf.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 10 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 10 | ./configure wrfplus 2>&1 | tee configure.log #Option 10 for gfortran/gcc and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 10 for gfortran/gcc and distribunted memory
  fi

  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile wrfplus 2>&1 | tee compile.wrfplus.log
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  ./clean -a
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus2.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 10 for gfortran/clang and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  ./clean -a
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 10 | ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi

  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee compile.wrf4dvar.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then

      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-ARW | macOS | GNU | Apple Silicon
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$SYSTEMOS" = "MacOS" ] && [ "$macos_64bit_GNU" = "1" ] && [ "$WRF_PICK" = "1" ] && [ "$MAC_CHIP" = "ARM" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    brew cleanup -s
    brew update
    outdated_packages=$(brew outdated --quiet)

    # List of packages to check/install
    packages=(
      "autoconf" "automake" "bison" "byacc" "cmake" "curl" "flex" "gcc@13"
      "gedit" "git" "gnu-sed" "ksh"
      "libtool" "libxml2" "m4" "make" "python@3.12" "tcsh" "wget"
      "xauth" "xorgproto" "xorgrgb" "xquartz"
    )

    for pkg in "${packages[@]}"; do
      if brew list "$pkg" &> /dev/null; then
        echo "$pkg is already installed."
        if [[ $outdated_packages == *"$pkg"* ]]; then
          echo "$pkg has a newer version available. Upgrading..."
          brew upgrade "$pkg"
        fi
      else
        echo "$pkg is not installed. Installing..."
        brew install "$pkg"
      fi
      sleep 1
    done

    export LD_LIBRARY_PATH=/usr/local/lib:$LD_LIBRARY_PATH
    export PATH=/usr/local/bin:$PATH

    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------

    export HOME=$(
      cd ~ \
        && pwd
    )
    mkdir $HOME/WRF
    export WRF_FOLDER=$HOME/WRF
    cd "${WRF_FOLDER}"/
    mkdir Downloads

    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir -p Libs/grib2
    mkdir -p Libs/NETCDF
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------
    export CPU_CORE=$(sysctl -n hw.ncpu) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))
    # 1/2 of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    # Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"
    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "

    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------

    # Unlink any existing Homebrew compiler symlinks
    echo $PASSWD | sudo -S unlink /opt/homebrew/bin/gfortran
    echo $PASSWD | sudo -S unlink /opt/homebrew/bin/gcc
    echo $PASSWD | sudo -S unlink /opt/homebrew/bin/g++

    # Source the bashrc to ensure environment variables are loaded
    source ~/.bashrc

    # Check current versions of gcc, g++, and gfortran (these should show "command not found" if unlinked)
    gcc --version
    g++ --version
    gfortran --version

    # Navigate to the Homebrew binaries directory
    cd /opt/homebrew/bin

    # Find the latest version of GCC, G++, and GFortran
    latest_gcc=gcc-13
    latest_gpp=g++-13
    latest_gfortran=gfortran-13

    # Check if the latest versions were found and link them
    echo "Linking the latest GCC version: $latest_gcc"
    echo $PASSWD | sudo -S ln -sf $latest_gcc gcc
    echo "Linking the latest G++ version: $latest_gpp"
    echo $PASSWD | sudo -S ln -sf $latest_gpp g++
    echo "Linking the latest GFortran version: $latest_gfortran"
    echo $PASSWD | sudo -S ln -sf $latest_gfortran gfortran

    # Return to the home directory
    cd

    # Source bashrc and bash_profile to reload the environment settings
    source ~/.bashrc
    source ~/.bash_profile

    # Check if the versions were successfully updated
    gcc --version
    g++ --version
    gfortran --version

    # Export compiler environment variables
    export CC=/usr/local/bin/gcc-13
    export CXX=/usr/local/bin/g++-13
    export FC=/usr/local/bin/gfortran-13
    export F77=/usr/local/bin/gfortran-13
    export CFLAGS="-fPIC -fPIE -Wno-implicit-function-declaration -Wno-incompatible-function-pointer-types -Wno-incompatible-pointer-types -Wall"

    echo " "

    # ----------------------------------------------------------------------
    # Compiler Configuration Complete
    # ----------------------------------------------------------------------

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/opt/homebrew/bin/$latest_gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/opt/homebrew/bin/$latest_gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/opt/homebrew/bin/$latest_gpp -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "

    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "

    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/

    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/

    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------
    mkdir -p "${WRF_FOLDER}"/Tests/Environment
    mkdir -p "${WRF_FOLDER}"/Tests/Compatibility

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility
    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 64bit of Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/macOS/opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg
    sudo -S installer -pkg opengrads-2.2.1.oga.1-bundle-x86_64-apple-darwin20.5.0.pkg -target /Applications/OpenGrads <<< "$PASSWD"

  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then

    brew install grads

  fi

  # Installing Miniconda3 to WRF directory and updating libraries
  echo $PASSWD | sudo -S apt -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-MacOSX-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "

  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable
  conda update -n ncl_stable --all -y
  conda deactivate
  conda deactivate
  conda deactivate
  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 17, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------

  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}

  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 17
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 17 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile em_real 2>&1 | tee compile.wrf.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 19 | ./configure 2>&1 | tee configure.log #Option 19 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 19 gfortran compiler with distributed memory
  fi

  ./compile | tee 2>&1 compile.wrf.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 10 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 10 | ./configure wrfplus 2>&1 | tee configure.log #Option 10 for gfortran/gcc and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 10 for gfortran/gcc and distribunted memory
  fi

  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile wrfplus 2>&1 | tee compile.wrfplus.log
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  ./clean -a
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus2.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 10 for gfortran/clang and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  ./clean -a
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 10 | ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi

  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee compile.wrf4dvar.log

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then

      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# WRF-ARW | RHL | GNU
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$RHL_64bit_GNU" = "1" ] && [ "$WRF_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
    echo "$PASSWD" | sudo -S dnf -y install bzip2-devel
    echo "$PASSWD" | sudo -S dnf -y install cairo-devel
    echo "$PASSWD" | sudo -S dnf -y install cmake
    echo "$PASSWD" | sudo -S dnf -y install cpp
    echo "$PASSWD" | sudo -S dnf -y install curl
    echo "$PASSWD" | sudo -S dnf -y install curl-devel
    echo "$PASSWD" | sudo -S dnf -y install flex
    echo "$PASSWD" | sudo -S dnf -y install flex-devel
    echo "$PASSWD" | sudo -S dnf -y install fontconfig
    echo "$PASSWD" | sudo -S dnf -y install fontconfig-devel
    echo "$PASSWD" | sudo -S dnf -y install gcc
    echo "$PASSWD" | sudo -S dnf -y install gcc-c++
    echo "$PASSWD" | sudo -S dnf -y install gcc-gfortran
    echo "$PASSWD" | sudo -S dnf -y install git
    echo "$PASSWD" | sudo -S dnf -y install ksh
    echo "$PASSWD" | sudo -S dnf -y install libjpeg
    echo "$PASSWD" | sudo -S dnf -y install libjpeg-devel
    echo "$PASSWD" | sudo -S dnf -y install libstdc++
    echo "$PASSWD" | sudo -S dnf -y install libstdc++-devel
    echo "$PASSWD" | sudo -S dnf -y install libX11
    echo "$PASSWD" | sudo -S dnf -y install libX11-devel
    echo "$PASSWD" | sudo -S dnf -y install libXaw
    echo "$PASSWD" | sudo -S dnf -y install libXaw-devel
    echo "$PASSWD" | sudo -S dnf -y install libXext-devel
    echo "$PASSWD" | sudo -S dnf -y install libXmu
    echo "$PASSWD" | sudo -S dnf -y install libXmu-devel
    echo "$PASSWD" | sudo -S dnf -y install libXrender
    echo "$PASSWD" | sudo -S dnf -y install libXrender-devel
    echo "$PASSWD" | sudo -S dnf -y install libXt
    echo "$PASSWD" | sudo -S dnf -y install libXt-devel
    echo "$PASSWD" | sudo -S dnf -y install libxml2
    echo "$PASSWD" | sudo -S dnf -y install libxml2-devel
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff-devel
    echo "$PASSWD" | sudo -S dnf -y install libtiff
    echo "$PASSWD" | sudo -S dnf -y install libtiff-devel
    echo "$PASSWD" | sudo -S dnf -y install m4
    echo "$PASSWD" | sudo -S dnf -y install nfs-utils
    echo "$PASSWD" | sudo -S dnf -y install perl
    echo "$PASSWD" | sudo -S dnf -y install 'perl(XML::LibXML)'
    echo "$PASSWD" | sudo -S dnf -y install pkgconfig
    echo "$PASSWD" | sudo -S dnf -y install pixman
    echo "$PASSWD" | sudo -S dnf -y install pixman-devel
    echo "$PASSWD" | sudo -S dnf -y install python3
    echo "$PASSWD" | sudo -S dnf -y install python3-devel
    echo "$PASSWD" | sudo -S dnf -y install tcsh
    echo "$PASSWD" | sudo -S dnf -y install time
    echo "$PASSWD" | sudo -S dnf -y install unzip
    echo "$PASSWD" | sudo -S dnf -y install wget

    echo "$PASSWD" | sudo -S dnf -y install java
    echo "$PASSWD" | sudo -S dnf -y install java-devel

    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk

    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk

    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade
    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF
    export WRF_FOLDER=$HOME/WRF
    cd "${WRF_FOLDER}"/
    mkdir Downloads

    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  if [ "${SYSTEMOS:-}" = "Linux" ] || [ "${SYSTEMOS:-}" = "RHL" ]; then
    if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
      # Register the just-tested shared libraries for future compatible
      # WRF-ARW, WRF-Chem, or WRF-Hydro installations.
      wrf_mosit_save_library_profile || echo "WARNING: library profile was not saved."
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Version 2.2.1 64-bit Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH

    echo " "
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c ftp://cola.gmu.edu/grads/2.2/grads-2.2.1-bin-RHL7.4-x86_64.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf grads-2.2.1-bin-RHL7.4-x86_64.tar.gz -C "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"/grads-2.2.1/bin
    chmod 775 *

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # Installing Miniconda3 to WRF-Hydro directory and updating libraries
  # ----------------------------------------------------------------------

  echo $PASSWD | sudo -S dnf -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "
  echo " "

  # ----------------------------------------------------------------------
  # OBSGRID | Objective Analysis Utility
  # Compile obsgrid.exe; auxiliary plotting executables are optional.
  # OBSGRID
  # Downloaded from git tagged releases
  # Option #2
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/
  # OBSGRID provides objective analysis preprocessing.
  # The primary required result is obsgrid.exe; plot helpers are optional.
  git clone https://github.com/wrf-model/OBSGRID.git
  cd "${WRF_FOLDER}"/OBSGRID

  ./clean -a
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda activate ncl_stable

  export HOME=$(
    cd ~ \
      && pwd
  )
  export DIR="${WRF_FOLDER}"/Libs
  export NETCDF=$DIR/NETCDF

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 2 | ./configure 2>&1 | tee configure.log #Option 2 for gfortran/gcc and distribunted memory
  else
    ./configure 2>&1 | tee configure.log #Option 2 for gfortran/gcc and distribunted memory
  fi

  sed -i '27s/-lnetcdf -lnetcdff/ -lnetcdff -lnetcdf/g' configure.oa

  sed -i '31s/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo -lfontconfig -lpixman-1 -lfreetype -lhdf5 -lhdf5_hl /g' configure.oa

  sed -i '39s/-frecord-marker=4/-frecord-marker=4 ${fallow_argument} /g' configure.oa

  sed -i '44s/=	/=	${fallow_argument} /g' configure.oa

  sed -i '45s/-C -P -traditional/-P -traditional/g' configure.oa

  echo " "
  ./compile 2>&1 | tee compile.obsgrid.log

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "
  # IF statement to check that all files were created.
  # Require obsgrid.exe itself; optional graphical helper programs
  # do not determine whether the main OBSGRID build succeeded.
  if [[ -x ./obsgrid.exe ]]; then
    echo "obsgrid.exe found."
    read -r -t 5 -p "Finished installing OBSGRID. I am going to wait for 5 seconds only ..."
  else
    echo "obsgrid.exe is missing. Attempting to compile again..."

    ./clean -a
    ./compile 2>&1 | tee compile.obsgrid.retry.log

    # Require obsgrid.exe itself; optional graphical helper programs
    # do not determine whether the main OBSGRID build succeeded.
    if [[ -x ./obsgrid.exe ]]; then
      echo "obsgrid.exe successfully created after recompilation."
      read -r -t 5 -p "Finished retrying OBSGRID compile. I am going to wait for 5 seconds only ..."
    else
      echo "Still missing obsgrid.exe after recompile. Exiting the script."
      read -r -p "Please contact script authors for assistance. Press 'Enter' to exit."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  echo " "
  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # In the namelist.input, the following settings support pNetCDF by setting
  # value to 11:
  # io_form_boundary
  # io_form_history
  # io_form_auxinput2
  # io_form_auxhist2
  # Note that you need set nocolons = .true. in the section &time_control of
  # namelist.input
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi
  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 18 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 18 | ./configure wrfplus 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi
  echo " "
  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus.log
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus2.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 18 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 18 | ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi
  echo " "
  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee compile.wrf4dvar.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
      mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG/irrigation
      mv "${WRF_FOLDER}"/GEOG/WPS_GEOG/fao "${WRF_FOLDER}"/GEOG/WPS_GEOG/irrigation

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-ARW | RHL | GNU (legacy GCC)
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$RHL_64bit_GNU" = "2" ] && [ "$WRF_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo "old version of GNU detected"
    echo $PASSWD | sudo -S yum install RHL-release-scl -y
    echo $PASSWD | sudo -S yum clean all
    echo $PASSWD | sudo -S yum remove devtoolset-11*
    echo $PASSWD | sudo -S yum install devtoolset-11
    echo $PASSWD | sudo -S yum install devtoolset-11-\* -y
    source /opt/rh/devtoolset-11/enable
    gcc --version
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
    echo "$PASSWD" | sudo -S dnf -y install bzip2-devel
    echo "$PASSWD" | sudo -S dnf -y install cairo-devel
    echo "$PASSWD" | sudo -S dnf -y install cmake
    echo "$PASSWD" | sudo -S dnf -y install cpp
    echo "$PASSWD" | sudo -S dnf -y install curl
    echo "$PASSWD" | sudo -S dnf -y install curl-devel
    echo "$PASSWD" | sudo -S dnf -y install flex
    echo "$PASSWD" | sudo -S dnf -y install flex-devel
    echo "$PASSWD" | sudo -S dnf -y install fontconfig
    echo "$PASSWD" | sudo -S dnf -y install fontconfig-devel
    echo "$PASSWD" | sudo -S dnf -y install gcc
    echo "$PASSWD" | sudo -S dnf -y install gcc-c++
    echo "$PASSWD" | sudo -S dnf -y install gcc-gfortran
    echo "$PASSWD" | sudo -S dnf -y install git
    echo "$PASSWD" | sudo -S dnf -y install ksh
    echo "$PASSWD" | sudo -S dnf -y install libjpeg
    echo "$PASSWD" | sudo -S dnf -y install libjpeg-devel
    echo "$PASSWD" | sudo -S dnf -y install libstdc++
    echo "$PASSWD" | sudo -S dnf -y install libstdc++-devel
    echo "$PASSWD" | sudo -S dnf -y install libX11
    echo "$PASSWD" | sudo -S dnf -y install libX11-devel
    echo "$PASSWD" | sudo -S dnf -y install libXaw
    echo "$PASSWD" | sudo -S dnf -y install libXaw-devel
    echo "$PASSWD" | sudo -S dnf -y install libXext-devel
    echo "$PASSWD" | sudo -S dnf -y install libXmu
    echo "$PASSWD" | sudo -S dnf -y install libXmu-devel
    echo "$PASSWD" | sudo -S dnf -y install libXrender
    echo "$PASSWD" | sudo -S dnf -y install libXrender-devel
    echo "$PASSWD" | sudo -S dnf -y install libXt
    echo "$PASSWD" | sudo -S dnf -y install libXt-devel
    echo "$PASSWD" | sudo -S dnf -y install libxml2
    echo "$PASSWD" | sudo -S dnf -y install libxml2-devel
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff
    echo "$PASSWD" | sudo -S dnf -y install libgeotiff-devel
    echo "$PASSWD" | sudo -S dnf -y install libtiff
    echo "$PASSWD" | sudo -S dnf -y install libtiff-devel
    echo "$PASSWD" | sudo -S dnf -y install m4
    echo "$PASSWD" | sudo -S dnf -y install nfs-utils
    echo "$PASSWD" | sudo -S dnf -y install perl
    echo "$PASSWD" | sudo -S dnf -y install 'perl(XML::LibXML)'
    echo "$PASSWD" | sudo -S dnf -y install pkgconfig
    echo "$PASSWD" | sudo -S dnf -y install pixman
    echo "$PASSWD" | sudo -S dnf -y install pixman-devel
    echo "$PASSWD" | sudo -S dnf -y install python3
    echo "$PASSWD" | sudo -S dnf -y install python3-devel
    echo "$PASSWD" | sudo -S dnf -y install tcsh
    echo "$PASSWD" | sudo -S dnf -y install time
    echo "$PASSWD" | sudo -S dnf -y install unzip
    echo "$PASSWD" | sudo -S dnf -y install wget

    echo "$PASSWD" | sudo -S dnf -y install java
    echo "$PASSWD" | sudo -S dnf -y install java-devel

    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-17-openjdk

    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk-devel
    echo "$PASSWD" | sudo -S dnf -y install java-21-openjdk

    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade
    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/WRF
    export WRF_FOLDER=$HOME/WRF
    cd "${WRF_FOLDER}"/
    mkdir Downloads

    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  if [ "${SYSTEMOS:-}" = "Linux" ] || [ "${SYSTEMOS:-}" = "RHL" ]; then
    if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
      # Register the just-tested shared libraries for future compatible
      # WRF-ARW, WRF-Chem, or WRF-Hydro installations.
      wrf_mosit_save_library_profile || echo "WARNING: library profile was not saved."
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Version 2.2.1 64-bit Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH

    echo " "
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c ftp://cola.gmu.edu/grads/2.2/grads-2.2.1-bin-RHL7.4-x86_64.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf grads-2.2.1-bin-RHL7.4-x86_64.tar.gz -C "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"/grads-2.2.1/bin
    chmod 775 *

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # Installing Miniconda3 to WRF-Hydro directory and updating libraries
  # ----------------------------------------------------------------------

  echo $PASSWD | sudo -S dnf -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # OBSGRID | Objective Analysis Utility
  # Compile obsgrid.exe; auxiliary plotting executables are optional.
  # OBSGRID
  # Downloaded from git tagged releases
  # Option #2
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/
  # OBSGRID provides objective analysis preprocessing.
  # The primary required result is obsgrid.exe; plot helpers are optional.
  git clone https://github.com/wrf-model/OBSGRID.git
  cd "${WRF_FOLDER}"/OBSGRID

  ./clean -a
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda activate ncl_stable

  export HOME=$(
    cd ~ \
      && pwd
  )
  export DIR="${WRF_FOLDER}"/Libs
  export NETCDF=$DIR/NETCDF

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 2 | ./configure 2>&1 | tee configure.log #Option 2 for gfortran/gcc and distribunted memory
  else
    ./configure 2>&1 | tee configure.log #Option 2 for gfortran/gcc and distribunted memory
  fi

  sed -i '27s/-lnetcdf -lnetcdff/ -lnetcdff -lnetcdf/g' configure.oa

  sed -i '31s/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo -lfontconfig -lpixman-1 -lfreetype -lhdf5 -lhdf5_hl /g' configure.oa

  sed -i '39s/-frecord-marker=4/-frecord-marker=4 ${fallow_argument} /g' configure.oa

  sed -i '44s/=	/=	${fallow_argument} /g' configure.oa

  sed -i '45s/-C -P -traditional/-P -traditional/g' configure.oa

  echo " "
  ./compile 2>&1 | tee compile.obsgrid.log

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "
  # IF statement to check that all files were created.
  # Require obsgrid.exe itself; optional graphical helper programs
  # do not determine whether the main OBSGRID build succeeded.
  if [[ -x ./obsgrid.exe ]]; then
    echo "obsgrid.exe found."
    read -r -t 5 -p "Finished installing OBSGRID. I am going to wait for 5 seconds only ..."
  else
    echo "obsgrid.exe is missing. Attempting to compile again..."

    ./clean -a
    ./compile 2>&1 | tee compile.obsgrid.retry.log

    # Require obsgrid.exe itself; optional graphical helper programs
    # do not determine whether the main OBSGRID build succeeded.
    if [[ -x ./obsgrid.exe ]]; then
      echo "obsgrid.exe successfully created after recompilation."
      read -r -t 5 -p "Finished retrying OBSGRID compile. I am going to wait for 5 seconds only ..."
    else
      echo "Still missing obsgrid.exe after recompile. Exiting the script."
      read -r -p "Please contact script authors for assistance. Press 'Enter' to exit."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  echo " "

  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 34, option 1 for gfortran and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # In the namelist.input, the following settings support pNetCDF by setting
  # value to 11:
  # io_form_boundary
  # io_form_history
  # io_form_auxinput2
  # io_form_auxhist2
  # Note that you need set nocolons = .true. in the section &time_control of
  # namelist.input
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 34
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #Option 34 gfortran compiler with distributed memory option 1 for basic nesting
  fi

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 3 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for gfortran and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 gfortran compiler with distributed memory
  fi
  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 18 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 18 | ./configure wrfplus 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi
  echo " "
  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus.log
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus2.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 18 for gfortran/gcc and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 18 | ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 18 for gfortran/gcc and distribunted memory
  fi
  echo " "
  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee compile.wrf4dvar.log
  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
      mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG/irrigation
      mv "${WRF_FOLDER}"/GEOG/WPS_GEOG/fao "${WRF_FOLDER}"/GEOG/WPS_GEOG/irrigation

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi
fi

################################################################################
# WRF-ARW | RHL | Intel oneAPI
# Build fresh scientific libraries, or reuse a validated, compiler-matched
# shared-library YAML.
################################################################################
if [ "$RHL_64bit_Intel" = "1" ] && [ "$WRF_PICK" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # Fresh-library path: build and test dependencies in this model tree.
  # When YAML reuse is selected, this source-build block is skipped.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade
    echo $PASSWD | sudo -S dnf -y install bzip2 bzip2-devel byacc cairo-devel cmake cpp curl curl-devel flex fontconfig-devel gcc-c++ gcc-gfortran git java-11-openjdk java-11-openjdk-devel ksh libX11-devel libXaw-devel libXext-devel libXrender-devel libstdc++-devel libxml2 libxml2-devel m4 nfs-utils perl "perl(XML::LibXML)" pkgconfig pixman-devel python3 python3-devel tcsh time unzip wget
    echo $PASSWD | sudo -S dnf -y groupinstall "Development Tools"

    # download the key to system keyring; this and the following echo command are
    # needed in order to install the Intel compilers

    echo $PASSWD | sudo bash -c 'printf "[oneAPI]\nname=Intel® oneAPI repository\nbaseurl=https://yum.repos.intel.com/oneapi\nenabled=1\ngpgcheck=1\nrepo_gpgcheck=1\ngpgkey=https://yum.repos.intel.com/intel-gpg-keys/GPG-PUB-KEY-INTEL-SW-PRODUCTS.PUB\n" > /etc/yum.repos.d/oneAPI.repo'

    echo $PASSWD | sudo -S mv /tmp/oneAPI.repo /etc/yum.repos.d

    echo $PASSWD | sudo -S dnf install intel-cpp-essentials -y

    # install the Intel compilers
    echo $PASSWD | sudo -S dnf upgrade intel-cpp-essentials -y
    echo $PASSWD | sudo -S dnf install intel-oneapi-base-toolkit -y
    echo $PASSWD | sudo -S dnf install intel-oneapi-hpc-toolkit -y
    echo $PASSWD | sudo -S dnf install intel-oneapi-python -y

    echo $PASSWD | sudo -S dnf update
    echo $PASSWD | sudo -S dnf -y install cmake pkgconfig
    echo $PASSWD | sudo -S dnf groupinstall "Development Tools" -y

    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    # add the Intel compiler file paths to various environment variables
    source /opt/intel/oneapi/setvars.sh --force

    # some of the libraries we install below need one or more of these variables

    export CC=icx
    export CXX=icpx
    export FC=ifx
    export F77=ifx
    export F90=ifx
    export MPIFC=mpiifx
    export MPIF77=mpiifx
    export MPIF90=mpiifx
    export MPICC=mpiicx
    export MPICXX=mpiicpx
    export CFLAGS="-fPIC -fPIE -O3 -Wno-incompatible-pointer-types -Wno-implicit-function-declaration -Wno-unused-command-line-argument"
    export FFLAGS=""
    export FCFLAGS=""

    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4)) # quarter of availble cores on system
    # Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))

    # If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system.
    if [ $CPU_CORE -le $CPU_6CORE ]; then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    # ----------------------------------------------------------------------
    # Installation Directories
    # makes necessary directories
    # ----------------------------------------------------------------------

    export HOME=$(
      cd ~ \
        && pwd
    )
    export WRF_FOLDER=$HOME/WRF_Intel
    export DIR="${WRF_FOLDER}"/Libs
    mkdir "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"
    mkdir Downloads

    mkdir Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://parallel-netcdf.github.io/Release/pnetcdf-$Pnetcdf_Version.tar.gz

    echo " "

    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # other libraries below need these variables to be set
    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 and Parallel I/O
    # Compile HDF5 with MPI support before building parallel NetCDF
    # interfaces.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # other libraries below need these variables to be set
    export HDF5=$DIR/grib2
    export PATH=$HDF5/bin:$PATH
    export PHDF5=$DIR/grib2
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # PnetCDF | Parallel NetCDF Library
    # Install the MPI-enabled PnetCDF library in the configured
    # scientific-library prefix.
    # Make file created with half of available cpu cores
    # Hard path for MPI added
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf pnetcdf-$Pnetcdf_Version.tar.gz
    cd pnetcdf-$Pnetcdf_Version
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --enable-static 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make check

    export PNETCDF=$DIR/grib2
    export PNETCDF_DIR=$DIR/grib2
    export PNETCDF_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/

    # these variables need to be set for the NetCDF-C install to work
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgcc -lm -ldl -lpnetcdf"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-pnetcdf --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    # other libraries below need these variables to be set
    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$DIR/NETCDF/include
    export NETCDF_LIB=$DIR/NETCDF/lib
    export NETCDF_ROOT=$DIR/NETCDF
    export NetCDF_ROOT=$DIR/NETCDF
    export LD_LIBRARY_PATH=$DIR/grib2/lib:$DIR/NETCDF/lib:$LD_LIBRARY_PATH

    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/

    # these variables need to be set for the NetCDF-Fortran install to work
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lpnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc"
    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}/Tests/Environment"
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # Reuse path: the earlier YAML checks already validated the library
    # locations; restore compiler and link flags without rebuilding them.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  if [ "${SYSTEMOS:-}" = "Linux" ] || [ "${SYSTEMOS:-}" = "RHL" ]; then
    if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
      # Register the just-tested shared libraries for future compatible
      # WRF-ARW, WRF-Chem, or WRF-Hydro installations.
      wrf_mosit_save_library_profile || echo "WARNING: library profile was not saved."
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # OpenGrADS | Visualization Utilities
  # Install the architecture-compatible OpenGrADS package selected in the main
  # menu.
  # Verison 2.2.1 64bit of Linux
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 1 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c https://sourceforge.net/projects/opengrads/files/grads2/2.2.1.oga.1/Linux%20%2864%20Bits%29/opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf opengrads-2.2.1.oga.1-bundle-x86_64-pc-linux-gnu-glibc_2.17.tar.gz -C "${WRF_FOLDER}"/ -C "${WRF_FOLDER}"/
    cd "${WRF_FOLDER}"/
    mv "${WRF_FOLDER}"/opengrads-2.2.1.oga.1 "${WRF_FOLDER}"/GrADS
    cd GrADS/Contents
    wget -O g2ctl.pl https://raw.githubusercontent.com/regisgrundig/SIMOP/master/g2ctl.pl
    chmod +x g2ctl.pl
    wget -c https://sourceforge.net/projects/opengrads/files/wgrib2/0.1.9.4/wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    cd wgrib2-v0.1.9.4/bin
    mv wgrib2 "${WRF_FOLDER}"/GrADS/Contents
    cd "${WRF_FOLDER}"/GrADS/Contents
    rm wgrib2-v0.1.9.4-bin-x86_64-glibc2.5-linux-gnu.tar.gz
    rm -r wgrib2-v0.1.9.4

    export PATH="${WRF_FOLDER}"/GrADS/Contents:$PATH
  fi
  # ----------------------------------------------------------------------
  # GrADS | Visualization Utilities
  # Install GrADS if the user selected the standard visualization package.
  # Version  2.2.1
  # Sublibs library instructions: http://cola.gmu.edu/grads/gadoc/supplibs2.html
  # GrADS instructions: http://cola.gmu.edu/grads/downloads.php
  # ----------------------------------------------------------------------
  if [[ $GRADS_PICK -eq 2 ]]; then
    cd "${WRF_FOLDER}"/Downloads
    wget -c ftp://cola.gmu.edu/grads/2.2/grads-2.2.1-bin-centos7.4-x86_64.tar.gz
    LD_LIBRARY_PATH env -u LD_LIBRARY_PATH tar -xzf grads-2.2.1-bin-centos7.4-x86_64.tar.gz -C "${WRF_FOLDER}"
    cd "${WRF_FOLDER}"/grads-2.2.1/bin
    chmod 775 *

  fi

  # ----------------------------------------------------------------------
  # NCL | NCAR Command Language
  # Install NCL in the local Conda environment for the selected modeling
  # system.
  # Install NCL through Conda
  # Use the upstream-recommended Conda installation method.
  # Reference: https://www.ncl.ucar.edu/index.shtml
  # ----------------------------------------------------------------------
  echo " "
  echo " "
  # Installing Miniconda3 to WRF directory and updating libraries

  echo $PASSWD | sudo -S dnf -y install python3-zstandard python3-zstd

  export Miniconda_Install_DIR="${WRF_FOLDER}"/miniconda3

  mkdir -p $Miniconda_Install_DIR

  wget -c https://repo.anaconda.com/miniconda/Miniconda3-latest-Linux-x86_64.sh -O $Miniconda_Install_DIR/miniconda.sh
  bash $Miniconda_Install_DIR/miniconda.sh -b -u -p $Miniconda_Install_DIR

  rm -rf $Miniconda_Install_DIR/miniconda.sh

  export PATH="${WRF_FOLDER}"/miniconda3/bin:$PATH

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  $Miniconda_Install_DIR/bin/conda init bash

  conda tos accept
  conda config --add channels conda-forge
  conda config --set auto_activate_base false
  conda update -n root --all -y

  # Special Thanks to @_WaylonWalker for code development
  echo " "
  # Installing NCL via Conda
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create -n ncl_stable -c conda-forge ncl -y
  conda activate ncl_stable
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # OBSGRID | Objective Analysis Utility
  # Compile obsgrid.exe; auxiliary plotting executables are optional.
  # OBSGRID
  # Downloaded from git tagged releases
  # Option #3
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/
  # OBSGRID provides objective analysis preprocessing.
  # The primary required result is obsgrid.exe; plot helpers are optional.
  git clone https://github.com/wrf-model/OBSGRID.git
  cd "${WRF_FOLDER}"/OBSGRID

  ./clean -a
  conda activate ncl_stable

  export HOME=$(
    cd ~ \
      && pwd
  )
  export DIR="${WRF_FOLDER}"/Libs
  export NETCDF=$DIR/NETCDF

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 3 | ./configure 2>&1 | tee configure.log #Option 3 for itnel and distribunted memory
  else
    ./configure 2>&1 | tee configure.log #Option 3 for intel and distribunted memory
  fi

  sed -i '27s/-lnetcdf -lnetcdff/ -lnetcdff -lnetcdf/g' configure.oa

  sed -i '31s/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo/-lncarg -lncarg_gks -lncarg_c -lX11 -lm -lcairo -lfontconfig -lpixman-1 -lfreetype -lhdf5 -lhdf5_hl /g' configure.oa

  sed -i '38s/ifort/ifx/g' configure.oa
  sed -i '43s/gcc/icx/g' configure.oa
  sed -i '45s|/lib/cpp|ifx|g' configure.oa
  sed -i '46s|-I. -C -P -DDEC -traditional|-fpp -DDEC -I.|g' configure.oa

  # Patch .F90.o rule to use direct compile with Intel Fortran + fpp
  sed -i '/^\.F90\.o:/,/^\t\$(RM) \$\*\.f/ c\.F90.o:\n\t$(RM) $@ $*.mod\n\t$(FC) $(FFLAGS) -fpp $(CPPFLAGS) ${NETCDF_INC} -c $<' configure.oa

  echo " "
  ./compile 2>&1 | tee compile.obsgrid.log

  conda deactivate
  conda deactivate
  conda deactivate

  echo " "
  # IF statement to check that all files were created.
  # Require obsgrid.exe itself; optional graphical helper programs
  # do not determine whether the main OBSGRID build succeeded.
  if [[ -x ./obsgrid.exe ]]; then
    echo "obsgrid.exe found."
    read -r -t 5 -p "Finished installing OBSGRID. I am going to wait for 5 seconds only ..."
  else
    echo "obsgrid.exe is missing. Attempting to compile again..."

    ./clean -a
    ./compile 2>&1 | tee compile.obsgrid.retry.log

    # Require obsgrid.exe itself; optional graphical helper programs
    # do not determine whether the main OBSGRID build succeeded.
    if [[ -x ./obsgrid.exe ]]; then
      echo "obsgrid.exe successfully created after recompilation."
      read -r -t 5 -p "Finished retrying OBSGRID compile. I am going to wait for 5 seconds only ..."
    else
      echo "Still missing obsgrid.exe after recompile. Exiting the script."
      read -r -p "Please contact script authors for assistance. Press 'Enter' to exit."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # wrf-python | Python Diagnostics
  # Install wrf-python for WRF output processing and analysis.
  # Install wrf-python through Conda
  # Use the upstream-recommended Conda installation method.
  # https://wrf-python.readthedocs.io/en/latest/installation.html  ##################
  # ----------------------------------------------------------------------
  source $Miniconda_Install_DIR/etc/profile.d/conda.sh
  conda env create -f $HOME/WRF-MOSIT/wrf-python-stable.yml

  # ----------------------------------------------------------------------
  # ncview | NetCDF Visualization
  # Install the NetCDF viewer through the local Conda environment.
  # ----------------------------------------------------------------------
  conda create -n ncview -c conda-forge ncview -y

  # ----------------------------------------------------------------------
  # CDO | Climate Data Operators
  # Install CDO for NetCDF processing and diagnostics.
  # Install CDO through Conda
  # Use the existing Conda environment for this utility.
  # Conda reference: https://bairdlangenbrunner.github.io/python-for-climate-scientists/conda/setting-up-conda-environments.html
  # ----------------------------------------------------------------------

  source $Miniconda_Install_DIR/etc/profile.d/conda.sh

  conda create --name cdo_stable -y
  conda activate cdo_stable
  conda install -c conda-forge cdo -y
  conda update --all -y
  conda deactivate
  conda deactivate
  conda deactivate

  echo " "

  # ----------------------------------------------------------------------
  # WRF-ARW | Model Compilation
  # Build WRF-ARW using the selected compiler, nesting mode, and
  # scientific-library stack.
  # WRF v${WPS_VERSION}
  # Downloaded from git tagged releases
  # option 78, option 1 for intel and distributed memory w/basic nesting
  # large file support enable with WRFiO_NCD_LARGE_FILE_SUPPORT=1
  # ----------------------------------------------------------------------

  source /opt/intel/oneapi/setvars.sh --force

  cd "${WRF_FOLDER}"/Downloads
  # Retrieve the exact WRF source version selected for this install.
  # The source is staged separately from the reusable library prefix.
  wget -c https://github.com/wrf-model/WRF/releases/download/v${WRF_VERSION}/v${WRF_VERSION}.tar.gz -O WRF-${WRF_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/

  # If statment for changing folder name
  # Check if WRF directory exists
  if [ -d "${WRF_FOLDER}/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRF" "${WRF_FOLDER}/WRF-${WRF_VERSION}"

  # Else, check for any folder matching WRFV*
  else
    for dir in "${WRF_FOLDER}"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
  # Enable WRF support for larger NetCDF output files.
  export WRFIO_NCD_LARGE_FILE_SUPPORT=1
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    (
      echo 78
      echo "$WRF_NESTING_OPTION"
    ) | ./configure

  else
    ./configure 2>&1 | tee configure.log #option 78 intel compiler with distributed memory option 1 for basic nesting
  fi

  # Need to remove mpich/GNU config calls to Intel config calls
  sed -i '136s|mpif90 -f90=$(SFC)|mpiifx|g' "${WRF_FOLDER}"/WRF-${WRF_VERSION}/configure.wrf
  sed -i '137s|mpicc -cc=$(SCC)|mpiicx|g' "${WRF_FOLDER}"/WRF-${WRF_VERSION}/configure.wrf

  # Build the real-data WRF model using the chosen compiler configuration.
  ./compile -j 2 em_real 2>&1 | tee compile.wrf1.log

  # Expose the compiled WRF source path to WPS and related tools.
  export WRF_DIR="${WRF_FOLDER}"/WRF-${WRF_VERSION}

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n >= 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 em_real 2>&1 | tee compile.wrf2.log
    cd "${WRF_FOLDER}"/WRF-${WRF_VERSION}/main
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n >= 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WPS | Geogrid, Ungrib, and Metgrid
  # Download, configure, and compile the preprocessing system with the
  # installed WRF libraries.
  # WPS v${WPS_VERSION}
  # Downloaded from git tagged releases
  # Option 19 for gfortran and distributed memory
  # ----------------------------------------------------------------------

  cd "${WRF_FOLDER}"/Downloads
  # Fetch WPS independently of WRF so each version is explicit;
  # the subsequent configure step uses the matching WRF_DIR.
  wget -c https://github.com/wrf-model/WPS/archive/refs/tags/v${WPS_VERSION}.tar.gz -O WPS-${WPS_VERSION}.tar.gz
  env -u LD_LIBRARY_PATH tar -xzf WPS-${WPS_VERSION}.tar.gz -C "${WRF_FOLDER}"/
  # Keep WPS in its versioned directory without moving it onto itself.
  if [ -d "${WRF_FOLDER}/WPS-${WPS_VERSION}" ]; then
    echo "WPS-${WPS_VERSION} directory already exists; skipping rename."
  elif [ -d "${WRF_FOLDER}/WPS" ]; then
    mv -f "${WRF_FOLDER}/WPS" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
  else
    for dir in "${WRF_FOLDER}"/WPSV* "${WRF_FOLDER}"/WPS-*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WPS-${WPS_VERSION}"
        break
      fi
    done
  fi
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 19 | ./configure 2>&1 | tee configure.log #Option 19 for intel and distributed memory
  else
    ./configure 2>&1 | tee configure.log #Option 19 intel compiler with distributed memory
  fi

  sed -i '67s|mpif90|mpiifx|g' "${WRF_FOLDER}"/WPS-${WPS_VERSION}/configure.wps
  sed -i '68s|mpicc|mpiicx|g' "${WRF_FOLDER}"/WPS-${WPS_VERSION}/configure.wps

  ./compile 2>&1 | tee compile.wps.log

  echo " "
  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  if (($n == 3)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    ./compile 2>&1 | tee compile.wps2.log
    cd "${WRF_FOLDER}"/WPS-${WPS_VERSION}
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    if (($n == 3)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WPS. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "
  # ----------------------------------------------------------------------
  # WRFPLUS | 4DVAR Tangent-Linear and Adjoint
  # Build the WRFPLUS support required by the four-dimensional assimilation
  # workflow.
  # WRFPLUS v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFPLUS is built within the WRF git folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 40 for intel and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFPLUS
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFPLUS

  # If statement for changing folder name inside WRFPLUS
  if [ -d "${WRF_FOLDER}/WRFPLUS/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFPLUS/WRF" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFPLUS"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFPLUS/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFPLUS/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFPLUS
  cd "${WRF_FOLDER}"/WRFPLUS
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 40 | ./configure wrfplus 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  else
    ./configure wrfplus 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  fi
  echo " "

  sed -i '136s|mpif90 -f90=$(SFC)|mpiifx|g' "${WRF_FOLDER}"/WRFPLUS/configure.wrf
  sed -i '137s|mpicc -cc=$(SCC)|mpiicx|g' "${WRF_FOLDER}"/WRFPLUS/configure.wrf

  # Compile WRFPLUS for tangent-linear and adjoint / 4DVAR support.
  ./compile -j 2 wrfplus 2>&1 | tee wrfplus1.compile.log

  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS

  echo " "

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFPLUS/main
  n=$(ls ./wrfplus.exe | wc -l)
  if (($n == 1)); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFPLUS/
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 wrfplus 2>&1 | tee compile.wrfplus2.log
    cd "${WRF_FOLDER}"/WRFPLUS/main
    n=$(ls ./wrfplus.exe | wc -l)
    if (($n == 1)); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRF Plus 4DVAR. I am going to wait for 5 seconds only ..."
    else
      echo "Missing one or more expected files."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi

  echo " "

  # ----------------------------------------------------------------------
  # WRFDA | 4DVAR Data Assimilation
  # Compile 4DVAR after the WRFPLUS dependency has been prepared.
  # WRFDA v${WPS_VERSION} 4DVAR
  # Downloaded from git tagged releases
  # WRFDA is built within the WRFPLUS folder
  # Does not include RTTOV library for radiation data.  If wanted will need to
  # install library then reconfigure
  # Note: if you intend to run both 3DVAR and 4DVAR experiments, it is not
  # necessary to compile the code twice.
  # Option 40 for intel and distributed memory
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"/Downloads
  mkdir "${WRF_FOLDER}"/WRFDA
  env -u LD_LIBRARY_PATH tar -xzf WRF-${WRF_VERSION}.tar.gz -C "${WRF_FOLDER}"/WRFDA

  # If statement for changing folder name inside WRFDA
  if [ -d "${WRF_FOLDER}/WRFDA/WRF" ]; then
    mv -f "${WRF_FOLDER}/WRFDA/WRF" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"

  else
    for dir in "${WRF_FOLDER}/WRFDA"/WRFV*; do
      if [ -d "$dir" ]; then
        mv -f "$dir" "${WRF_FOLDER}/WRFDA/WRF-${WRF_VERSION}"
        break
      fi
    done
  fi

  cd "${WRF_FOLDER}"/WRFDA/WRF-${WRF_VERSION}
  mv * "${WRF_FOLDER}"/WRFDA
  cd "${WRF_FOLDER}"/WRFDA
  rm -rf WRF-${WRF_VERSION}/
  export NETCDF=$DIR/NETCDF
  export HDF5=$DIR/grib2
  export WRFPLUS_DIR="${WRF_FOLDER}"/WRFPLUS
  rm -f "${WRF_FOLDER}"/WRFDA/var/da/da_minimisation/da_residual.inc
  ./clean -a

  # Automatic configuration feeds the preselected platform/model
  # choices to the upstream menu; otherwise configure is interactive.
  if [ ${auto_config} -eq 1 ]; then
    echo 40 | ./configure 4dvar 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  else
    ./configure 4dvar 2>&1 | tee configure.log #Option 40 for intel and distribunted memory
  fi
  echo " "

  sed -i '136s|mpif90 -f90=$(SFC)|mpiifx|g' "${WRF_FOLDER}"/WRFDA/configure.wrf
  sed -i '137s|mpicc -cc=$(SCC)|mpiicx|g' "${WRF_FOLDER}"/WRFDA/configure.wrf

  # Compile WRFDA executables used by the selected data-assimilation workflow.
  ./compile -j 2 all_wrfvar 2>&1 | tee wrfda.compile.log
  echo " "

  # IF statement to check that all files were created.
  cd "${WRF_FOLDER}"/WRFDA/var/da
  # Count generated executables. The following branch decides whether
  # the expected build products exist or compilation needs a retry.
  n=$(ls ./*.exe | wc -l)
  cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
  m=$(ls ./*.exe | wc -l)
  if ((($n == 43) && ($m == 1))); then
    echo "All expected files created."
    read -r -t 5 -p "Finished installing WRFDA-4DVAR. I am going to wait for 5 seconds only ..."
  else
    echo "Missing one or more expected files."
    echo "Running compiler again"
    cd "${WRF_FOLDER}"/WRFDA
    # Retry this target after the initial executable check failed; recheck afterward.
    ./compile -j 2 all_wrfvar 2>&1 | tee compile.chem.wrfvar2.log
    cd "${WRF_FOLDER}"/WRFDA/var/da
    # Count generated executables. The following branch decides whether
    # the expected build products exist or compilation needs a retry.
    n=$(ls ./*.exe | wc -l)
    cd "${WRF_FOLDER}"/WRFDA/var/obsproc/src
    m=$(ls ./*.exe | wc -l)
    if ((($n == 43) && ($m == 1))); then
      echo "All expected files created."
      read -r -t 5 -p "Finished installing WRFDA. I am going to wait for 5 seconds only ..."
    else
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
      exit 1
    fi
  fi
  echo " "

  # ----------------------------------------------------------------------
  # WPS Geography | Mandatory and Optional Datasets
  # Download geographic input datasets unless an existing WPS_GEOG
  # installation was selected.
  # http://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # These files are large so if you only need certain ones comment the others
  # off
  # All files downloaded and untarred is 200GB
  # https://www2.mmm.ucar.edu/wrf/users/download/get_sources_wps_geog.html
  # ----------------------------------------------------------------------
  # Download mandatory WPS geography only when an existing GEOG
  # dataset was not selected in the startup menu.
  if [ "${MOSIT_REUSE_GEOG:-0}" != "1" ]; then
    cd "${WRF_FOLDER}"/Downloads
    mkdir "${WRF_FOLDER}"/GEOG
    mkdir "${WRF_FOLDER}"/GEOG/WPS_GEOG

    echo " "
    echo "Mandatory WRF Preprocessing System (WPS) Geographical Input Data Mandatory Fields Downloads"
    echo " "
    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_high_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_high_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/

    wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_low_res_mandatory.tar.gz
    env -u LD_LIBRARY_PATH tar -xzf geog_low_res_mandatory.tar.gz -C "${WRF_FOLDER}"/GEOG/
    cp -a -n "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES/. "${WRF_FOLDER}"/GEOG/WPS_GEOG/
    rm -rf "${WRF_FOLDER}"/GEOG/WPS_GEOG_LOW_RES

    # These extra geographical fields support particular physics
    # or applications and are downloaded only if requested.
    if [ ${WPS_Specific_Applications} -eq 1 ]; then
      echo " "
      echo " WPS Geographical Input Data Mandatory for Specific Applications"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_thompson28_chem.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_thompson28_chem.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_noahmp.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_noahmp.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/irrigation.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf irrigation.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_px.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_px.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_urban.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_urban.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_ssib.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_ssib.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/lake_depth.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf lake_depth.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/topobath_30s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf topobath_30s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/gsl_gwd.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf gsl_gwd.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/cglc_modis_lcz_global.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf cglc_modis_lcz_global.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

    fi

    # These supplemental datasets are optional; leaving this choice
    # off avoids downloading additional large source archives.
    if [ ${Optional_GEOG} -eq 1 ]; then
      echo " "
      echo "Optional WPS Geographical Input Data"
      echo " "

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_older_than_2000.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_older_than_2000.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s_with_lakes.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf modis_landuse_20class_15s_with_lakes.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/geog_alt_lsm.tar.gz
      env -u LD_LIBRARY_PATH tar -xzf geog_alt_lsm.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/nlcd2006_ll_9s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf nlcd2006_ll_9s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/updated_Iceland_LU.tar.gz
      env -u LD_LIBRARY_PATH tar -xvf updated_Iceland_LU.tar.gz -C "${WRF_FOLDER}"/GEOG/WPS_GEOG

      wget -c https://www2.mmm.ucar.edu/wrf/src/wps_files/modis_landuse_20class_15s.tar.bz2
      env -u LD_LIBRARY_PATH tar -xvf modis_landuse_20class_15s.tar.bz2 -C "${WRF_FOLDER}"/GEOG/WPS_GEOG
    fi
  else
    # Use the selected existing WPS_GEOG directory, avoiding another
    # large download while retaining the new model installation tree.
    wrf_mosit_link_existing_geog || exit 1
    echo "[PASS] Skipping GEOG downloads; using $MOSIT_GEOG_SOURCE"
  fi

fi

################################################################################
# COAWST | Coupled Ocean, Atmosphere, Waves, and Sediment
# Build fresh GNU scientific libraries and the Model Coupling Toolkit (MCT);
# shared-library YAML reuse is not supported.
# COAWST installation with parallel process.
# Tested in Ubuntu 22.04 & 24.04, Rocky Linux 9 & macOS Ventura 64bit
# Built in 64-bit system
# Built with GNU compilers
# Tested with current available libraries on 03/01/2025
# If newer libraries exist edit script paths for changes
# Estimated Run Time ~ 90 - 150 Minutes with 10mb/s downloadspeed.
# Special thanks to:
# USGS's Dr. John Warner
################################################################################

################################################################################
# COAWST | Ubuntu/Debian | GNU | x86_64
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$Ubuntu_64bit_GNU" = "1" ] && [ "$COAWST_PICK" = "1" ] && [ "$aarch64" != "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
    echo "$PASSWD" | sudo -S apt -y install default-jdk
    echo "$PASSWD" | sudo -S apt -y install default-jre
    echo "$PASSWD" | sudo -S apt -y install flex
    echo "$PASSWD" | sudo -S apt -y install freeglut3-dev
    echo "$PASSWD" | sudo -S apt -y install libfl-dev
    echo "$PASSWD" | sudo -S apt -y install g++
    echo "$PASSWD" | sudo -S apt -y install gawk
    echo "$PASSWD" | sudo -S apt -y install gcc
    echo "$PASSWD" | sudo -S apt -y install gettext
    echo "$PASSWD" | sudo -S apt -y install gfortran
    echo "$PASSWD" | sudo -S apt -y install git
    echo "$PASSWD" | sudo -S apt -y install ksh
    echo "$PASSWD" | sudo -S apt -y install libcurl4-gnutls-dev
    echo "$PASSWD" | sudo -S apt -y install libjpeg-dev
    echo "$PASSWD" | sudo -S apt -y install libncurses6
    echo "$PASSWD" | sudo -S apt -y install libncursesw5-dev
    echo "$PASSWD" | sudo -S apt -y install libpixman-1-dev
    echo "$PASSWD" | sudo -S apt -y install libpng-dev
    echo "$PASSWD" | sudo -S apt -y install libtool
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16-dev
    echo "$PASSWD" | sudo -S apt -y install libxml-libxml-perl
    echo "$PASSWD" | sudo -S apt -y install m4
    echo "$PASSWD" | sudo -S apt -y install make
    echo "$PASSWD" | sudo -S apt -y install ncview
    echo "$PASSWD" | sudo -S apt -y install pipenv
    echo "$PASSWD" | sudo -S apt -y install pkg-config
    echo "$PASSWD" | sudo -S apt -y install python3
    echo "$PASSWD" | sudo -S apt -y install python3-dev
    echo "$PASSWD" | sudo -S apt -y install python3-pip
    echo "$PASSWD" | sudo -S apt -y install python3-dateutil
    echo "$PASSWD" | sudo -S apt -y install tcsh
    echo "$PASSWD" | sudo -S apt -y install unzip
    echo "$PASSWD" | sudo -S apt -y install xauth
    echo "$PASSWD" | sudo -S apt -y install xorg
    echo "$PASSWD" | sudo -S apt -y install time
    echo "$PASSWD" | sudo -S apt -y install ghostscript
    echo "$PASSWD" | sudo -S apt -y install less
    echo "$PASSWD" | sudo -S apt -y install libbz2-dev
    echo "$PASSWD" | sudo -S apt -y install libc6-dev
    echo "$PASSWD" | sudo -S apt -y install libffi-dev
    echo "$PASSWD" | sudo -S apt -y install libgdbm-dev
    echo "$PASSWD" | sudo -S apt -y install libopenblas-dev
    echo "$PASSWD" | sudo -S apt -y install libreadline-dev
    echo "$PASSWD" | sudo -S apt -y install libssl-dev
    echo "$PASSWD" | sudo -S apt -y install libtiff-dev
    echo "$PASSWD" | sudo -S apt -y install libgeotiff-dev
    echo "$PASSWD" | sudo -S apt -y install tk-dev
    echo "$PASSWD" | sudo -S apt -y install vim
    echo "$PASSWD" | sudo -S apt -y install wget

    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/COAWST
    export WRF_FOLDER=$HOME/COAWST
    cd "${WRF_FOLDER}"/
    mkdir Downloads

    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-cxx4/archive/refs/tags/v$Netcdf_CXX_Version.tar.gz
    wget -c http://mtc-m21c.sid.inpe.br/col/sid.inpe.br/mtc-m21c/2020/10.02.15.11/doc/publicacao.pdf

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/bin/gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/bin/gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/bin/g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export HDF5_INCDIR=$DIR/grib2/include
    export HDF5_LIBDIR=$DIR/grib2/lib
    export PHDF5=$DIR/grib2
    export PHDF5_INCDIR=$DIR/grib2/include
    export PHDF5_LIBDIR=$DIR/grib2/lib
    export PATH=$DIR/grib2/bin:$PATH
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$NETCDF/include
    export NETCDF_LIB=$NETCDF/lib
    export NETCDF_INCDIR=$NETCDF/include
    export NETCDF_LIBDIR=$NETCDF/lib
    export NETCDFPATH=$NETCDF
    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-CXX | C++ Interface
    # Build the C++ bindings used by this specialized model branch.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_CXX_Version.tar.gz
    cd netcdf-cxx4-$Netcdf_CXX_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdff -lnetcdf  -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make check

    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # COAWST | Source, MCT Coupling, and Compilation
  # Set up the COAWST source tree, compile MCT, and run the coupled-model
  # build.
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"

  # COAWST couples multiple models. Compile its MCT coupling library
  # against the same MPI stack used by this dedicated installation.
  git clone https://github.com/DOI-USGS/COAWST.git

  # Compile Model Coupling Toolkit (MCT)
  if [ "${MOSIT_REUSE_LIBS:-0}" = "1" ] && [ -n "${MCT_DIR:-}" ] && [ -d "$MCT_DIR/include" ] && [ -d "$MCT_DIR/lib" ]; then
    ln -s "$MCT_DIR" "$WRF_FOLDER/Libs/MCT" || exit 1
    echo "[PASS] Reusing registered MCT scientific library"
  else
    cd "${WRF_FOLDER}"/COAWST/Lib/MCT

    chmod 775 configure install-sh mkinstalldirs

    MPIHEADER="-I$DIR/MPICH/include" ./configure --prefix="${WRF_FOLDER}"/Libs/MCT 2>&1 | tee coawst.configure.log

    make 2>&1 | tee coawst.make.log
    make install 2>&1 | tee coawst.make.install.log

  fi

  export MCT_INCDIR="${WRF_FOLDER}"/Libs/MCT/include
  export MCT_LIBDIR="${WRF_FOLDER}"/Libs/MCT/lib

  cd "${WRF_FOLDER}"/COAWST

  # Modify build_coawst.sh for installation paths and libraries
  sed -i '137s/INLET_TEST/SANDY/g' build_coawst.sh
  sed -i "145s|/cygdrive/d/models/COAWST|${WRF_FOLDER}/COAWST|g" build_coawst.sh
  sed -i '213s|export|#export|g' build_coawst.sh
  sed -i '214s|#export|export|g' build_coawst.sh
  sed -i '255s|#export|export|g' build_coawst.sh
  sed -i '309s|Inlet_test/Coupled|Sandy|g' build_coawst.sh
  sed -i '310s|Inlet_test/Coupled|Sandy|g' build_coawst.sh

  # Configure GNU Fortran flags
  cd "${WRF_FOLDER}"/COAWST/Compilers

  sed -i '41a\      FFLAGS += -frecord-marker=4 -fconvert=big-endian' Linux-gfortran.mk

  # Automatically select GNU compiler and basic nesting
  cd "${WRF_FOLDER}"/COAWST/WRF/arch/

  sed -i '452s|.*|  $response = "34 \\n";|g' Config.pl
  sed -i '919s|.*|  $response = "1 \\n";|g' Config.pl

  # Compile COAWST
  cd "${WRF_FOLDER}"/COAWST/

  chmod 775 *.sh

  ./build_coawst.sh -j 2 2>&1 | tee build_coawst.log

  if [ $? -eq 0 ] && [ -e "coawstM" ]; then
    echo "Script ran successfully and coawstM exists."
  else
    echo "Script did not run successfully or coawstM does not exist."
    echo "Running compiler again"
    cd "${WRF_FOLDER}/COAWST/WRF/arch/"
    ./build_coawst.sh -j 2 2>&1 | tee build_coawst2.log
    if [ $? -eq 0 ] && [ -e "coawstM" ]; then
      echo "Script ran successfully and coawstM exists."
    else
      echo "Script did not run successfully or coawstM does not exist."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    fi
  fi

fi

################################################################################
# COAWST | Ubuntu/Debian | GNU | ARM64
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$Ubuntu_64bit_GNU" = "1" ] && [ "$COAWST_PICK" = "1" ] && [ "$aarch64" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then
    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S apt -y update
    echo $PASSWD | sudo -S apt -y upgrade

    release_version=$(lsb_release -r -s)

    echo "$PASSWD" | sudo -S apt-get install -y --no-install-recommends emacs

    echo "$PASSWD" | sudo -S apt -y install bison
    echo "$PASSWD" | sudo -S apt -y install build-essential
    echo "$PASSWD" | sudo -S apt -y install byacc
    echo "$PASSWD" | sudo -S apt -y install cmake
    echo "$PASSWD" | sudo -S apt -y install csh
    echo "$PASSWD" | sudo -S apt -y install curl
    echo "$PASSWD" | sudo -S apt -y install default-jdk
    echo "$PASSWD" | sudo -S apt -y install default-jre
    echo "$PASSWD" | sudo -S apt -y install flex
    echo "$PASSWD" | sudo -S apt -y install freeglut3-dev
    echo "$PASSWD" | sudo -S apt -y install libfl-dev
    echo "$PASSWD" | sudo -S apt -y install g++
    echo "$PASSWD" | sudo -S apt -y install gawk
    echo "$PASSWD" | sudo -S apt -y install gcc
    echo "$PASSWD" | sudo -S apt -y install gettext
    echo "$PASSWD" | sudo -S apt -y install gfortran
    echo "$PASSWD" | sudo -S apt -y install git
    echo "$PASSWD" | sudo -S apt -y install ksh
    echo "$PASSWD" | sudo -S apt -y install libcurl4-gnutls-dev
    echo "$PASSWD" | sudo -S apt -y install libjpeg-dev
    echo "$PASSWD" | sudo -S apt -y install libncurses6
    echo "$PASSWD" | sudo -S apt -y install libncursesw5-dev
    echo "$PASSWD" | sudo -S apt -y install libpixman-1-dev
    echo "$PASSWD" | sudo -S apt -y install libpng-dev
    echo "$PASSWD" | sudo -S apt -y install libtool
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16
    echo "$PASSWD" | sudo -S apt -y install libxml2
    echo "$PASSWD" | sudo -S apt -y install libxml2-16-dev
    echo "$PASSWD" | sudo -S apt -y install libxml-libxml-perl
    echo "$PASSWD" | sudo -S apt -y install m4
    echo "$PASSWD" | sudo -S apt -y install make
    echo "$PASSWD" | sudo -S apt -y install ncview
    echo "$PASSWD" | sudo -S apt -y install pipenv
    echo "$PASSWD" | sudo -S apt -y install pkg-config
    echo "$PASSWD" | sudo -S apt -y install python3
    echo "$PASSWD" | sudo -S apt -y install python3-dev
    echo "$PASSWD" | sudo -S apt -y install python3-pip
    echo "$PASSWD" | sudo -S apt -y install python3-dateutil
    echo "$PASSWD" | sudo -S apt -y install tcsh
    echo "$PASSWD" | sudo -S apt -y install unzip
    echo "$PASSWD" | sudo -S apt -y install xauth
    echo "$PASSWD" | sudo -S apt -y install xorg
    echo "$PASSWD" | sudo -S apt -y install time
    echo "$PASSWD" | sudo -S apt -y install ghostscript
    echo "$PASSWD" | sudo -S apt -y install less
    echo "$PASSWD" | sudo -S apt -y install libbz2-dev
    echo "$PASSWD" | sudo -S apt -y install libc6-dev
    echo "$PASSWD" | sudo -S apt -y install libffi-dev
    echo "$PASSWD" | sudo -S apt -y install libgdbm-dev
    echo "$PASSWD" | sudo -S apt -y install libopenblas-dev
    echo "$PASSWD" | sudo -S apt -y install libreadline-dev
    echo "$PASSWD" | sudo -S apt -y install libssl-dev
    echo "$PASSWD" | sudo -S apt -y install libtiff-dev
    echo "$PASSWD" | sudo -S apt -y install libgeotiff-dev
    echo "$PASSWD" | sudo -S apt -y install tk-dev
    echo "$PASSWD" | sudo -S apt -y install vim
    echo "$PASSWD" | sudo -S apt -y install wget

    echo " "
    # ----------------------------------------------------------------------
    # Installation Directories
    # ----------------------------------------------------------------------
    export HOME=$(
      cd ~ \
        && pwd
    )

    mkdir $HOME/COAWST
    export WRF_FOLDER=$HOME/COAWST
    cd "${WRF_FOLDER}"/
    mkdir Downloads

    mkdir Libs
    export DIR="${WRF_FOLDER}"/Libs
    mkdir Libs/grib2
    mkdir Libs/NETCDF
    mkdir Libs/MPICH
    mkdir -p Tests/Environment
    mkdir -p Tests/Compatibility

    echo " "
    # ----------------------------------------------------------------------
    # Parallel Build Settings | CPU Cores
    # Set the number of parallel compilation jobs from the available processor
    # count.
    # ----------------------------------------------------------------------

    export CPU_CORE=$(nproc) # number of available threads on system
    export CPU_6CORE="6"
    export CPU_QUARTER=$(($CPU_CORE / 4))                          #quarter of availble cores on system
    export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2))) #Forces CPU cores to even number to avoid partial core export. ie 7 cores would be 3.5 cores.

    if [ $CPU_CORE -le $CPU_6CORE ]; then #If statement for low core systems.  Forces computers to only use 1 core if there are 4 cores or less on the system. then
      export CPU_QUARTER_EVEN="2"
    else
      export CPU_QUARTER_EVEN=$(($CPU_QUARTER - ($CPU_QUARTER % 2)))
    fi

    echo "##########################################"
    echo "Number of Threads being used $CPU_QUARTER_EVEN"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # Scientific Libraries | Download Source Archives
    # Download the versions pinned in the dependency section; unpack and build
    # each library below.
    # ----------------------------------------------------------------------
    cd Downloads
    wget -c https://github.com/madler/zlib/releases/download/v$Zlib_Version/zlib-$Zlib_Version.tar.gz
    wget -c https://github.com/HDFGroup/hdf5/releases/download/hdf5_$HDF5_Version/hdf5-$HDF5_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-c/archive/refs/tags/v$Netcdf_C_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-fortran/archive/refs/tags/v$Netcdf_Fortran_Version.tar.gz
    wget -c https://download.sourceforge.net/libpng/libpng-$Libpng_Version.tar.gz
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/jasper-$Jasper_Version.tar.gz
    wget -c https://github.com/pmodels/mpich/releases/download/v$Mpich_Version/mpich-$Mpich_Version.tar.gz
    wget -c https://github.com/Unidata/netcdf-cxx4/archive/refs/tags/v$Netcdf_CXX_Version.tar.gz
    wget -c http://mtc-m21c.sid.inpe.br/col/sid.inpe.br/mtc-m21c/2020/10.02.15.11/doc/publicacao.pdf

    echo " "
    # ----------------------------------------------------------------------
    # Compiler Environment and Build Flags
    # Set compiler executables, compatibility flags, and library paths for
    # this platform.
    # ----------------------------------------------------------------------
    export CC=gcc
    export CXX=g++
    export FC=gfortran
    export F77=gfortran
    export CFLAGS="-fPIC -fPIE -O3 -Wno-implicit-function-declaration -Wno-incompatible-pointer-types"

    # IF statement for GNU compiler issue
    export GCC_VERSION=$(/usr/bin/gcc -dumpfullversion | awk '{print$1}')
    export GFORTRAN_VERSION=$(/usr/bin/gfortran -dumpfullversion | awk '{print$1}')
    export GPLUSPLUS_VERSION=$(/usr/bin/g++ -dumpfullversion | awk '{print$1}')

    export GCC_VERSION_MAJOR_VERSION=$(echo $GCC_VERSION | awk -F. '{print $1}')
    export GFORTRAN_VERSION_MAJOR_VERSION=$(echo $GFORTRAN_VERSION | awk -F. '{print $1}')
    export GPLUSPLUS_VERSION_MAJOR_VERSION=$(echo $GPLUSPLUS_VERSION | awk -F. '{print $1}')

    export version_10="10"

    if [ $GCC_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GFORTRAN_VERSION_MAJOR_VERSION -ge $version_10 ] || [ $GPLUSPLUS_VERSION_MAJOR_VERSION -ge $version_10 ]; then
      export fallow_argument=-fallow-argument-mismatch
      export boz_argument=-fallow-invalid-boz
    else
      export fallow_argument=
      export boz_argument=
    fi

    export FFLAGS="$fallow_argument"
    export FCFLAGS="$fallow_argument"

    echo "##########################################"
    echo "FFLAGS = $FFLAGS"
    echo "FCFLAGS = $FCFLAGS"
    echo "CFLAGS = $CFLAGS"
    echo "##########################################"

    echo " "
    # ----------------------------------------------------------------------
    # zlib | Compression Library
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf zlib-$Zlib_Version.tar.gz
    cd zlib-$Zlib_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    export ZLIB_ROOT=$DIR/grib2
    export ZLIBLIB=$DIR/grib2/lib
    export ZLIBINC=$DIR/grib2/include

    echo " "
    # ----------------------------------------------------------------------
    # MPICH | MPI Implementation
    # F90= due to compiler issues with mpich install
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf mpich-$Mpich_Version.tar.gz
    cd mpich-$Mpich_Version/

    F90= ./configure --prefix=$DIR/MPICH --with-device=ch3 FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/MPICH/bin:$PATH

    export MPIFC=$DIR/MPICH/bin/mpifort
    export MPIF77=$DIR/MPICH/bin/mpifort
    export MPIF90=$DIR/MPICH/bin/mpifort
    export MPICC=$DIR/MPICH/bin/mpicc
    export MPICXX=$DIR/MPICH/bin/mpicxx

    echo " "
    # ----------------------------------------------------------------------
    # libpng | PNG Support
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads

    # other libraries below need these variables to be set
    export LDFLAGS=-L$DIR/grib2/lib
    export CPPFLAGS=-I$DIR/grib2/include

    env -u LD_LIBRARY_PATH tar -xzf libpng-$Libpng_Version.tar.gz
    cd libpng-$Libpng_Version/

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PNG_ROOT=$DIR/grib2

    echo " "
    # ----------------------------------------------------------------------
    # JasPer | GRIB2 JPEG-2000 Support
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf jasper-$Jasper_Version.tar.gz
    cd jasper-$Jasper_Version/

    F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --build=aarch64-unknown-linux-gnu --host=aarch64-unknown-linux-gnu --prefix="$DIR/grib2" 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export JASPERLIB=$DIR/grib2/lib
    export JASPERINC=$DIR/grib2/include
    export JASPER_DIR=$DIR/grib2
    export Jasper_ROOT=$DIR/grib2/lib

    echo " "
    # ----------------------------------------------------------------------
    # HDF5 | NetCDF-4 Storage Support
    # Compile HDF5 before NetCDF so NetCDF-4 can use HDF5 storage.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf hdf5-$HDF5_Version.tar.gz
    cd hdf5-$HDF5_Version

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/grib2 --with-zlib=$DIR/grib2 --enable-hl --enable-fortran --enable-parallel 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export HDF5=$DIR/grib2
    export HDF5_INCDIR=$DIR/grib2/include
    export HDF5_LIBDIR=$DIR/grib2/lib
    export PHDF5=$DIR/grib2
    export PHDF5_INCDIR=$DIR/grib2/include
    export PHDF5_LIBDIR=$DIR/grib2/lib
    export PATH=$DIR/grib2/bin:$PATH
    export HDF5_ROOT=$DIR/grib2
    export PHDF5_ROOT=$DIR/grib2

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-C | Core NetCDF Library
    # Build NetCDF-C against the previously installed HDF5 and compression
    # libraries.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_C_Version.tar.gz
    cd netcdf-c-$Netcdf_C_Version/
    export CPPFLAGS=-I$DIR/grib2/include
    export LDFLAGS="-L$DIR/grib2/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lhdf5_hl -lhdf5 -lz -lcurl -lgfortran -lgcc -lm -ldl"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --disable-dap --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-cdf5 --enable-parallel-tests --enable-logging 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    export PATH=$DIR/NETCDF/bin:$PATH
    export NETCDF=$DIR/NETCDF
    export NETCDF_INC=$NETCDF/include
    export NETCDF_LIB=$NETCDF/lib
    export NETCDF_INCDIR=$NETCDF/include
    export NETCDF_LIBDIR=$NETCDF/lib
    export NETCDFPATH=$NETCDF
    echo " "
    # ----------------------------------------------------------------------
    # NetCDF-Fortran | Fortran Interface
    # Build the Fortran interface using the installed NetCDF-C library.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_Fortran_Version.tar.gz
    cd netcdf-fortran-$Netcdf_Fortran_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdf -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log

    echo " "

    # ----------------------------------------------------------------------
    # NetCDF-CXX | C++ Interface
    # Build the C++ bindings used by this specialized model branch.
    # ----------------------------------------------------------------------
    cd "${WRF_FOLDER}"/Downloads
    env -u LD_LIBRARY_PATH tar -xzf v$Netcdf_CXX_Version.tar.gz
    cd netcdf-cxx4-$Netcdf_CXX_Version/
    export LD_LIBRARY_PATH=$DIR/NETCDF/lib:$LD_LIBRARY_PATH
    export CPPFLAGS="-I$DIR/NETCDF/include -I$DIR/grib2/include"
    export LDFLAGS="-L$DIR/NETCDF/lib -L$DIR/grib2/lib -Wl,-rpath,$DIR/NETCDF/lib -Wl,-rpath,$DIR/grib2/lib"
    export LIBS="-lnetcdff -lnetcdf  -lcurl -lhdf5_hl -lhdf5 -lz -lm -ldl -lgcc -lgfortran"

    CC=$MPICC FC=$MPIFC F77=$MPIF77 F90=$MPIF90 CXX=$MPICXX CFLAGS=$CFLAGS FFLAGS=$FFLAGS FCFLAGS=$FCFLAGS ./configure --prefix=$DIR/NETCDF --enable-netcdf-4 --enable-netcdf4 --enable-static --enable-parallel-tests --enable-logging --enable-hdf5 2>&1 | tee configure.log

    make -j 2 2>&1 | tee make.log
    make -j 2 install 2>&1 | tee make.install.log
    # make check

    echo " "

    # ----------------------------------------------------------------------
    # Scientific Libraries | Environment and Compatibility Tests
    # Run the original Fortran/C, NetCDF, and MPI compatibility checks before
    # model compilation.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Downloads
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_NETCDF_MPI_tests.tar
    wget -c https://www2.mmm.ucar.edu/wrf/OnLineTutorial/compile_tutorial/tar_files/Fortran_C_tests.tar

    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_tests.tar -C "${WRF_FOLDER}"/Tests/Environment
    env -u LD_LIBRARY_PATH tar -xvf Fortran_C_NETCDF_MPI_tests.tar -C "${WRF_FOLDER}"/Tests/Compatibility

    export one="1"
    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Environment

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Environment Testing "
    echo "Test 1"
    $FC TEST_1_fortran_only_fixed.f
    ./a.out | tee env_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test1.txt | awk '{print$1}')
    # Require the upstream test program to report SUCCESS before
    # proceeding to the remaining compiler/link compatibility checks.
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 1 Passed"
    else
      echo "Environment Compiler Test 1 Failed"
      exit 1
    fi
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 2"
    $FC TEST_2_fortran_only_free.f90
    ./a.out | tee env_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 2 Passed"
    else
      echo "Environment Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 3"
    $CC TEST_3_c_only.c
    ./a.out | tee env_test3.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test3.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 3 Passed"
    else
      echo "Environment Compiler Test 3 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    echo "Test 4"
    $CC -c TEST_4_fortran+c_c.c
    $FC -c TEST_4_fortran+c_f.f90
    $FC TEST_4_fortran+c_f.o TEST_4_fortran+c_c.o
    ./a.out | tee env_test4.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" env_test4.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Enviroment Test 4 Passed"
    else
      echo "Environment Compiler Test 4 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "
    # ----------------------------------------------------------------------
    # Environment Test Suite | Fortran, C, NetCDF, and MPI
    # Verify the compilers and links for the scientific libraries with the
    # bundled test programs.
    # ----------------------------------------------------------------------

    cd "${WRF_FOLDER}"/Tests/Compatibility

    cp ${NETCDF}/include/netcdf.inc .

    echo " "
    echo " "
    echo "Library Compatibility Tests "
    echo "Test 1"
    $FC -c 01_fortran+c+netcdf_f.f
    $CC -c 01_fortran+c+netcdf_c.c
    $FC 01_fortran+c+netcdf_f.o 01_fortran+c+netcdf_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    ./a.out | tee comp_test1.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test1.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 1 Passed"
    else
      echo "Compatibility Compiler Test 1 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."

    echo " "

    echo "Test 2"
    $MPIFC -c 02_fortran+c+netcdf+mpi_f.f
    $MPICC -c 02_fortran+c+netcdf+mpi_c.c
    $MPIFC 02_fortran+c+netcdf+mpi_f.o \
      02_fortran+c+netcdf+mpi_c.o \
      -L${NETCDF}/lib -lnetcdff -lnetcdf

    $DIR/MPICH/bin/mpirun ./a.out | tee comp_test2.txt
    export TEST_PASS=$(grep -w -o -c "SUCCESS" comp_test2.txt | awk '{print$1}')
    if [ $TEST_PASS -ge 1 ]; then
      echo "Compatibility Test 2 Passed"
    else
      echo "Compatibility Compiler Test 2 Failed"
      exit 1
    fi
    echo " "
    read -r -t 3 -p "I am going to wait for 3 seconds only ..."
    echo " "

    echo " All tests completed and passed"
  else
    # This generic fallback is retained in the original branch,
    # but the specialized-model menu always selects fresh libraries.
    wrf_mosit_restore_reused_libraries || exit 1
  fi
  echo " "

  # ----------------------------------------------------------------------
  # COAWST | Source, MCT Coupling, and Compilation
  # Set up the COAWST source tree, compile MCT, and run the coupled-model
  # build.
  # ----------------------------------------------------------------------
  cd "${WRF_FOLDER}"

  # COAWST couples multiple models. Compile its MCT coupling library
  # against the same MPI stack used by this dedicated installation.
  git clone https://github.com/DOI-USGS/COAWST.git

  # Compile Model Coupling Toolkit (MCT)
  if [ "${MOSIT_REUSE_LIBS:-0}" = "1" ] && [ -n "${MCT_DIR:-}" ] && [ -d "$MCT_DIR/include" ] && [ -d "$MCT_DIR/lib" ]; then
    ln -s "$MCT_DIR" "$WRF_FOLDER/Libs/MCT" || exit 1
    echo "[PASS] Reusing registered MCT scientific library"
  else
    cd "${WRF_FOLDER}"/COAWST/Lib/MCT

    chmod 775 configure install-sh mkinstalldirs

    MPIHEADER="-I$DIR/MPICH/include" ./configure --prefix="${WRF_FOLDER}"/Libs/MCT 2>&1 | tee coawst.configure.log

    make 2>&1 | tee coawst.make.log
    make install 2>&1 | tee coawst.make.install.log

  fi

  export MCT_INCDIR="${WRF_FOLDER}"/Libs/MCT/include
  export MCT_LIBDIR="${WRF_FOLDER}"/Libs/MCT/lib

  cd "${WRF_FOLDER}"/COAWST

  # Modify build_coawst.sh for installation paths and libraries
  sed -i '137s/INLET_TEST/SANDY/g' build_coawst.sh
  sed -i "145s|/cygdrive/d/models/COAWST|${WRF_FOLDER}/COAWST|g" build_coawst.sh
  sed -i '213s|export|#export|g' build_coawst.sh
  sed -i '214s|#export|export|g' build_coawst.sh
  sed -i '255s|#export|export|g' build_coawst.sh
  sed -i '309s|Inlet_test/Coupled|Sandy|g' build_coawst.sh
  sed -i '310s|Inlet_test/Coupled|Sandy|g' build_coawst.sh

  # Configure GNU Fortran flags
  cd "${WRF_FOLDER}"/COAWST/Compilers

  sed -i '41a\      FFLAGS += -frecord-marker=4 -fconvert=big-endian' Linux-gfortran.mk

  # Automatically select GNU compiler and basic nesting
  cd "${WRF_FOLDER}"/COAWST/WRF/arch/

  sed -i '452s|.*|  $response = "34 \\n";|g' Config.pl
  sed -i '919s|.*|  $response = "1 \\n";|g' Config.pl

  # Compile COAWST
  cd "${WRF_FOLDER}"/COAWST/

  chmod 775 *.sh

  ./build_coawst.sh -j 2 2>&1 | tee build_coawst.log

  if [ $? -eq 0 ] && [ -e "coawstM" ]; then
    echo "Script ran successfully and coawstM exists."
  else
    echo "Script did not run successfully or coawstM does not exist."
    echo "Running compiler again"
    cd "${WRF_FOLDER}/COAWST/WRF/arch/"
    ./build_coawst.sh -j 2 2>&1 | tee build_coawst2.log
    if [ $? -eq 0 ] && [ -e "coawstM" ]; then
      echo "Script ran successfully and coawstM exists."
    else
      echo "Script did not run successfully or coawstM does not exist."
      read -r -p "Please contact script authors for assistance, press 'Enter' to exit script."
    fi
  fi

fi

################################################################################
# COAWST | RHL | GNU
# Fresh, model-specific scientific libraries are required; YAML reuse is
# disabled.
################################################################################
if [ "$RHL_64bit_GNU" = "1" ] && [ "$COAWST_PICK" = "1" ]; then
  # The original scientific-library installation remains unchanged for fresh installs.
  # This model has extra or differently configured scientific libraries.
  # Its installer menu forces a fresh build instead of shared YAML reuse.
  if [ "${MOSIT_REUSE_LIBS:-0}" != "1" ]; then

    # ----------------------------------------------------------------------
    # System Prerequisites | Package Installation
    # ----------------------------------------------------------------------
    echo $PASSWD | sudo -S yum install epel-release -y
    echo $PASSWD | sudo -S yum install dnf -y
    echo $PASSWD | sudo -S dnf install epel-release -y
    echo $PASSWD | sudo -S dnf install dnf -y
    echo $PASSWD | sudo -S dnf -y update
    echo $PASSWD | sudo -S dnf -y upgrade

    echo "$PASSWD" | sudo -S dnf -y install byacc
    echo "$PASSWD" | sudo -S dnf -y install bzip2
